function getConfigInterfaceModeDeps() {
  return {
    appConfig,
    get billingConfig() { return billingConfig; },
    estaOnline,
    FEATURE_MATRIX,
    getAssinaturaSaas,
    getInterfaceMode,
    getUsuarioAtual,
    getUsuarioSessaoReal,
    INTERFACE_MODE_LABELS,
    INTERFACE_MODE_LEGACY_STORAGE_KEY,
    INTERFACE_MODE_STORAGE_KEY,
    INTERFACE_MODE_UPDATED_AT_STORAGE_KEY,
    INTERFACE_MODE_VALUES,
    INTERFACE_MODES,
    get interfaceModePreferenceState() { return interfaceModePreferenceState; },
    isModoManutencaoSuperadminAtivo,
    isSuperAdmin,
    localStorage,
    normalizarInterfaceMode,
    normalizarSlugPlano,
    PLAN_RANK,
    PRINTER_FEATURE_ENABLED,
    registrarDiagnostico,
    renderUiIcon,
    requisicaoSupabase,
    resolverInterfaceModePreferida,
    serializeInterfaceMode,
    setInterfaceMode,
    syncConfig,
    window
  };
}
function normalizarInterfaceMode(value = "") {
  return window.SimplificaConfigInterfaceMode.normalizarInterfaceMode(value, getConfigInterfaceModeDeps());
}

function getInterfaceModeStorageValue() {
  return window.SimplificaConfigInterfaceMode.getInterfaceModeStorageValue(getConfigInterfaceModeDeps());
}

function resolverInterfaceModePreferida(fallback = appConfig?.interfaceMode) {
  return window.SimplificaConfigInterfaceMode.resolverInterfaceModePreferida(fallback, getConfigInterfaceModeDeps());
}

function serializeInterfaceMode(mode = getInterfaceMode()) {
  return window.SimplificaConfigInterfaceMode.serializeInterfaceMode(mode, getConfigInterfaceModeDeps());
}


appConfig.interfaceMode = normalizarInterfaceMode(
  getInterfaceModeStorageValue() || appConfig.interfaceMode
);
localStorage.setItem(INTERFACE_MODE_STORAGE_KEY, serializeInterfaceMode(appConfig.interfaceMode));
localStorage.removeItem(INTERFACE_MODE_LEGACY_STORAGE_KEY);
function getInterfaceMode() {
  return window.SimplificaConfigInterfaceMode.getInterfaceMode(getConfigInterfaceModeDeps());
}

function isSimplificaMode() {
  return window.SimplificaConfigInterfaceMode.isSimplificaMode(getConfigInterfaceModeDeps());
}

function isProfissionalMode() {
  return window.SimplificaConfigInterfaceMode.isProfissionalMode(getConfigInterfaceModeDeps());
}

function getInterfaceModeLabel(mode = getInterfaceMode()) {
  return window.SimplificaConfigInterfaceMode.getInterfaceModeLabel(mode, getConfigInterfaceModeDeps());
}

function getHomeLayout() {
  return window.SimplificaHomeLayout.resolve({
    storedValue: window.SimplificaHomeLayout.read(localStorage),
    configValue: appConfig.homeLayout
  });
}

appConfig.homeLayout = window.SimplificaHomeLayout.persist(getHomeLayout(), {
  storage: localStorage,
  config: appConfig
});

function alterarHomeLayout(layout, { render = true, notify = true } = {}) {
  const anterior = getHomeLayout();
  const proximo = window.SimplificaHomeLayout.persist(layout, {
    storage: localStorage,
    config: appConfig,
    save: salvarDados
  });
  if (notify && anterior !== proximo) {
    mostrarToast(proximo === "carousel" ? "Home em carrossel ativada." : "Home simples ativada.", "sucesso", 2800);
  }
  if (render) renderizarPreservandoScroll();
  return proximo;
}


function setInterfaceMode(mode, { render = true, notify = true, persistRemote = true, updatedAt = "" } = {}) {
  const next = normalizarInterfaceMode(mode);
  const changed = getInterfaceMode() !== next;
  const preferenceUpdatedAt = String(updatedAt || new Date().toISOString());
  appConfig.interfaceMode = next;
  localStorage.setItem(INTERFACE_MODE_STORAGE_KEY, serializeInterfaceMode(next));
  localStorage.setItem(INTERFACE_MODE_UPDATED_AT_STORAGE_KEY, preferenceUpdatedAt);
  if (!isScreenVisibleInCurrentMode(telaAtual, next)) {
    telaAtual = "dashboard";
  }
  salvarDados();
  if (persistRemote) salvarPreferenciaModoInterfaceRemota(next, preferenceUpdatedAt);
  if (notify && changed) {
    mostrarToast(`${getInterfaceModeLabel(next)} ativado. Os dados foram preservados.`, "sucesso", 3200);
  }
  if (render) renderizarPreservandoScroll();
  return next;
}
function alternarInterfaceMode(mode) {
  return window.SimplificaConfigInterfaceMode.alternarInterfaceMode(mode, getConfigInterfaceModeDeps());
}


