const SUPERADMIN_MAINTENANCE_SESSION_KEY = "simplificaSuperadminMaintenanceSession";

function getUsuarioSessaoReal() {
  const emailAtual = normalizarEmail(usuarioAtualEmail);
  if (!emailAtual) return null;
  usuarios = normalizarUsuarios(usuarios);
  const usuario = usuarios.find((item) => item.email === emailAtual && item.ativo) || null;
  if (!usuario) return null;
  const sessaoSuperadmin = sessionStorage.getItem("simplificaSuperadminAuthenticated") === "true";
  return sessaoSuperadmin ? { ...usuario, papel: "superadmin", clientId: "", companyId: "" } : usuario;
}

function getSessaoManutencaoSuperadmin() {
  try {
    const raw = sessionStorage.getItem(SUPERADMIN_MAINTENANCE_SESSION_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (_) {
    return window.__superadminMaintenanceSession || null;
  }
}

function setSessaoManutencaoSuperadmin(sessao = null) {
  window.__superadminMaintenanceSession = sessao || null;
  try {
    if (sessao) sessionStorage.setItem(SUPERADMIN_MAINTENANCE_SESSION_KEY, JSON.stringify(sessao));
    else sessionStorage.removeItem(SUPERADMIN_MAINTENANCE_SESSION_KEY);
  } catch (_) {}
}

function getUsuarioManutencaoSuperadmin() {
  const sessao = getSessaoManutencaoSuperadmin();
  const superadminReal = getUsuarioSessaoReal();
  if (!sessao || !superadminReal || superadminReal.papel !== "superadmin") return null;
  if (normalizarEmail(sessao.superadminEmail) !== normalizarEmail(superadminReal.email)) return null;
  usuarios = normalizarUsuarios(usuarios);
  const alvo = usuarios.find((usuario) => String(usuario.id || "") === String(sessao.targetUserId || "") && usuario.ativo !== false);
  if (!alvo || alvo.papel === "superadmin") return null;
  return {
    ...alvo,
    papel: "admin",
    superadminMaintenance: true,
    maintenanceSuperadminEmail: superadminReal.email,
    maintenanceStartedAt: sessao.startedAt || ""
  };
}

function isModoManutencaoSuperadminAtivo() {
  return !!getUsuarioManutencaoSuperadmin();
}

function getUsuarioAtual() {
  if (telaAtual === "superadmin") return getUsuarioSessaoReal();
  return getUsuarioManutencaoSuperadmin() || getUsuarioSessaoReal();
}

function isDono() {
  return false;
}

function isSuperAdmin(usuario = getUsuarioAtual()) {
  if (usuario?.papel === "superadmin") return true;
  if (usuario?.superadminMaintenance !== true || !usuario?.maintenanceSuperadminEmail) return false;
  const superadminReal = getUsuarioSessaoReal();
  return superadminReal?.papel === "superadmin"
    && normalizarEmail(superadminReal.email) === normalizarEmail(usuario.maintenanceSuperadminEmail);
}

function getSuperAdminPrincipal() {
  usuarios = normalizarUsuarios(usuarios);
  return usuarios.find((usuario) => usuario.papel === "superadmin") || null;
}

function isSuperAdminPrincipal(usuario) {
  const principal = getSuperAdminPrincipal();
  return !!usuario && !!principal && String(usuario.id) === String(principal.id);
}

function isAdminCliente() {
  const usuario = getUsuarioAtual();
  return ["owner", "admin", "superadmin"].includes(usuario?.papel);
}

function podeGerenciarUsuarios() {
  return !contaPendenteExclusao() && (adminLogado || isSuperAdmin() || (isAdminCliente() && PlanService.podeUsarRecurso("employees")));
}

function existeAdminCliente(clientId = getClientIdAtual()) {
  usuarios = normalizarUsuarios(usuarios);
  return usuarios.some((usuario) => {
    if (usuario.papel !== "admin" || usuario.ativo === false || usuario.bloqueado) return false;
    return !clientId || usuario.clientId === clientId || (!usuario.clientId && usuario.email === normalizarEmail(billingConfig.licenseEmail));
  });
}

