function isMobile() {
  return getViewportMode() === "mobile";
}

function isTablet() {
  const largura = window.innerWidth || 0;
  const altura = window.innerHeight || 0;
  return Math.min(largura, altura) >= 600 && Math.max(largura, altura) <= 1366;
}

function isDesktop() {
  return getViewportMode() === "desktop";
}

function getViewportMode() {
  const viewportWidth = window.innerWidth || 1024;
  const viewportHeight = window.innerHeight || 0;
  const tabletPorDimensao = Math.min(viewportWidth, viewportHeight) >= 600
    && Math.max(viewportWidth, viewportHeight) <= 1366;
  if (tabletPorDimensao) return viewportWidth > viewportHeight ? "desktop" : "mobile";
  if (viewportWidth < 768) return "mobile";
  if (viewportWidth < 1024) return viewportWidth > viewportHeight ? "desktop" : "mobile";
  return "desktop";
}

function applyViewportModeClasses(target = document.body) {
  if (!target?.classList) return getViewportMode();
  const mode = getViewportMode();
  target.classList.remove("viewport-mobile", "viewport-tablet", "viewport-desktop");
  target.classList.add(`viewport-${mode}`);
  target.dataset.viewportMode = mode;
  return mode;
}

function getUiProfile() {
  return isAndroidNativeApp() ? "android_apk" : "web_pwa";
}

function isWebPwaProfile() {
  return getUiProfile() === "web_pwa";
}

function isPwaSettingsSplitPane(elemento = null) {
  return isWebPwaProfile()
    && !isMobile()
    && !!elemento?.closest?.(".settings-accordion-list");
}

function detectarTipoDispositivo() {
  const agente = navigator.userAgent || "";
  if (/Android|iPhone|iPad|iPod|Mobile/i.test(agente) || isMobile()) return "mobile";
  return "desktop";
}

function nomeTipoDispositivo(tipo) {
  return tipo === "mobile" ? "celular Android" : "Windows/navegador";
}

function getPlatformAdapter() {
  const capacitor = window.Capacitor || null;
  const platform = String(capacitor?.getPlatform?.() || (isAndroid() ? "android-web" : "web")).toLowerCase();
  const isAPK = isAndroidNativeApp();
  const isPWA = !isAPK;
  return {
    id: isAPK ? "android_apk" : "web_pwa",
    platform,
    isPWA,
    isAndroid: isAndroid(),
    isAPK,
    supportsLocalAI: isAPK && !!window.Capacitor?.Plugins?.SimplificaFiles,
    supportsInstallPrompt: isPWA,
    supportsServiceWorker: isPWA && "serviceWorker" in navigator && location.protocol !== "file:",
    safeAreaInsets: {
      top: "env(safe-area-inset-top)",
      right: "env(safe-area-inset-right)",
      bottom: "env(safe-area-inset-bottom)",
      left: "env(safe-area-inset-left)"
    }
  };
}

function getManagedSafeAreaInsets() {
  const safeArea = window.safeArea && typeof window.safeArea === "object" ? window.safeArea : null;
  if (!safeArea) return null;
  const px = (value) => `${Math.max(0, Math.round(Number(value) || 0))}px`;
  return {
    top: px(safeArea.top),
    right: px(safeArea.right),
    bottom: px(safeArea.bottom),
    left: px(safeArea.left),
    keyboard: px(safeArea.keyboardHeight),
    viewportHeight: px(safeArea.viewportHeight || safeArea.visualViewportHeight || window.innerHeight)
  };
}

function getLimitesDispositivos() {
  const limitePlano = getSessionLimitPlano();
  return {
    mobile: limitePlano,
    desktop: limitePlano,
    total: limitePlano
  };
}

function normalizarDispositivosLicenca(lista = billingConfig.registeredDevices) {
  const vistos = new Set();
  return (Array.isArray(lista) ? lista : []).map((item) => {
    const email = normalizarEmail(item?.email);
    const id = String(item?.id || "").trim();
    const tipo = item?.tipo === "desktop" ? "desktop" : "mobile";
    if (!email || !id) return null;
    const chave = `${email}:${tipo}:${id}`;
    if (vistos.has(chave)) return null;
    vistos.add(chave);
    return {
      id,
      email,
      tipo,
      nome: String(item?.nome || nomeTipoDispositivo(tipo)).trim(),
      ultimoAcesso: item?.ultimoAcesso || new Date().toISOString()
    };
  }).filter(Boolean);
}

function getEmailLicencaAtual() {
  const usuario = getUsuarioAtual();
  return normalizarEmail(usuario?.email || billingConfig.licenseEmail || "");
}

function getDataOwnerId() {
  const remoto = getEscopoDadosAtual();
  if (remoto) return remoto;
  const usuario = getUsuarioAtual();
  return isSuperAdmin(usuario) ? "superadmin" : normalizarEmail(usuario?.email || billingConfig.licenseEmail || deviceId);
}

function prepararRegistroOnline(registro = {}) {
  const atualizadoEm = registro.updated_at || registro.updatedAt || registro.atualizadoEm || new Date().toISOString();
  const ownerId = getDataOwnerId();
  return {
    ...registro,
    user_id: pareceUuid(ownerId) ? ownerId : registro.user_id || registro.userId || null,
    owner_id: ownerId,
    source_device_id: registro.source_device_id || registro.sourceDeviceId || deviceId,
    sourceDeviceId: registro.sourceDeviceId || registro.source_device_id || deviceId,
    sync_status: registro.sync_status || registro.syncStatus || "pending",
    updated_at: atualizadoEm,
    updatedAt: registro.updatedAt || atualizadoEm
  };
}

function gerarUuidOperacional() {
  try {
    if (crypto?.randomUUID) return crypto.randomUUID();
  } catch (_) {}
  return window.Simplifica3dFinancialCore?.uuidFrom?.(`operation:${Date.now()}:${Math.random()}`)
    || "00000000-0000-4000-8000-000000000000";
}

function gerarHashOperacional(valor = "") {
  const texto = String(valor || "");
  let hash = 2166136261;
  for (let i = 0; i < texto.length; i += 1) {
    hash ^= texto.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function getPlataformaDispositivoOperacional() {
  const ua = String(navigator?.userAgent || "").toLowerCase();
  if (/android/.test(ua)) return "android";
  if (/iphone|ipad|ipod/.test(ua)) return "ios";
  if (/mobile/.test(ua)) return "mobile-web";
  return "web";
}

function criarMetadadosOperacaoFinanceira(tipo, referencia = {}, opcoes = {}) {
  const agora = opcoes.createdAt || new Date().toISOString();
  const escopo = getEscopoDadosAtual?.() || getDataOwnerId() || "local";
  const referenciaId = referencia.id || referencia.sale_id || referencia.pedidoId || referencia.record_id || Date.now();
  const operationUuid = opcoes.operation_uuid || gerarUuidOperacional();
  const baseRequest = [
    tipo || "financial",
    escopo,
    deviceId,
    referenciaId,
    referencia.total ?? referencia.valor ?? "",
    referencia.status ?? "",
    referencia.updated_at || referencia.atualizadoEm || agora
  ].join("|");
  const clientRequestId = opcoes.client_request_id || `${tipo || "financial"}:${escopo}:${deviceId}:${referenciaId}:${gerarHashOperacional(baseRequest)}`;
  const requestHash = opcoes.request_hash || gerarHashOperacional(JSON.stringify({
    tipo,
    referenciaId,
    total: referencia.total ?? referencia.valor ?? null,
    itens: referencia.itens?.length ?? null,
    status: referencia.status || "",
    cliente: referencia.cliente || ""
  }));
  const offline = !estaOnline();
  return {
    operation_uuid: operationUuid,
    operationUuid,
    client_request_id: clientRequestId,
    clientRequestId,
    request_hash: requestHash,
    requestHash,
    created_from_device: deviceId,
    createdFromDevice: deviceId,
    financial_flow_version: FINANCIAL_FLOW_VERSION,
    financialFlowVersion: FINANCIAL_FLOW_VERSION,
    operation_source: opcoes.operation_source || "pwa_shadow",
    operationSource: opcoes.operation_source || "pwa_shadow",
    sync_version: FINANCIAL_SYNC_VERSION,
    syncVersion: FINANCIAL_SYNC_VERSION,
    sync_attempts: opcoes.sync_attempts ?? 0,
    syncAttempts: opcoes.sync_attempts ?? 0,
    last_sync_error: opcoes.last_sync_error || "",
    lastSyncError: opcoes.last_sync_error || "",
    recovery_source: opcoes.recovery_source || "",
    recoverySource: opcoes.recovery_source || "",
    recovered_at: opcoes.recovered_at || "",
    recoveredAt: opcoes.recovered_at || "",
    reconciliation_version: FINANCIAL_RECONCILIATION_VERSION,
    reconciliationVersion: FINANCIAL_RECONCILIATION_VERSION,
    processing_node: opcoes.processing_node || getPlataformaDispositivoOperacional(),
    processingNode: opcoes.processing_node || getPlataformaDispositivoOperacional(),
    worker_version: FINANCIAL_WORKER_VERSION,
    workerVersion: FINANCIAL_WORKER_VERSION,
    worker_node: opcoes.worker_node || `${getPlataformaDispositivoOperacional()}:${deviceId}`,
    workerNode: opcoes.worker_node || `${getPlataformaDispositivoOperacional()}:${deviceId}`,
    retry_strategy: opcoes.retry_strategy || "exponential",
    retryStrategy: opcoes.retry_strategy || "exponential",
    retry_backoff_level: opcoes.retry_backoff_level ?? 0,
    retryBackoffLevel: opcoes.retry_backoff_level ?? 0,
    processing_priority: opcoes.processing_priority ?? 0,
    processingPriority: opcoes.processing_priority ?? 0,
    app_version: APP_VERSION,
    appVersion: APP_VERSION,
    pwa_version: APP_VERSION,
    pwaVersion: APP_VERSION,
    sync_source: offline ? "offline_queue" : "online",
    syncSource: offline ? "offline_queue" : "online",
    offline_created_at: offline ? agora : "",
    offlineCreatedAt: offline ? agora : "",
    synced_at: "",
    syncedAt: "",
    device_platform: getPlataformaDispositivoOperacional(),
    devicePlatform: getPlataformaDispositivoOperacional(),
    shadow_validation_json: {
      mode: "shadow",
      legacyFlow: "active",
      atomicFlow: "prepared",
      generatedAt: agora
    },
    shadowValidation: {
      mode: "shadow",
      legacyFlow: "active",
      atomicFlow: "prepared",
      generatedAt: agora
    }
  };
}

function registrarShadowFinanceiroLocal(tipo, detalhes = {}) {
  try {
    registrarDiagnostico("financeiro-shadow", tipo, JSON.stringify({
      ...detalhes,
      financial_flow_version: FINANCIAL_FLOW_VERSION,
      app_version: APP_VERSION,
      device_id: deviceId
    }).slice(0, 900), { silent: true });
  } catch (_) {}
}

function getEmpresaIdFinanceiroAtual() {
  return String(billingConfig.companyId || getUsuarioAtual()?.companyId || getUsuarioAtual()?.company_id || "").trim();
}

function getChaveEstadoFinanceiroCanonico() {
  const escopo = getEscopoDadosAtual?.() || getDataOwnerId() || "local";
  const empresa = getEmpresaIdFinanceiroAtual() || "sem-empresa";
  return `simplifica:financial-canonical:v2:${escopo}:${empresa}`;
}

function criarEstadoFinanceiroCanonicoVazio() {
  return { version: 1, events: [], operations: [], movements: [], paymentMethods: [], updatedAt: "", lastError: "" };
}

function carregarEstadoFinanceiroCanonico() {
  try {
    const salvo = JSON.parse(localStorage.getItem(getChaveEstadoFinanceiroCanonico()) || "null");
    if (!salvo || typeof salvo !== "object") return criarEstadoFinanceiroCanonicoVazio();
    return {
      ...criarEstadoFinanceiroCanonicoVazio(),
      ...salvo,
      events: Array.isArray(salvo.events) ? salvo.events.slice(-300) : [],
      operations: Array.isArray(salvo.operations) ? salvo.operations.slice(0, 600) : [],
      movements: Array.isArray(salvo.movements) ? salvo.movements.slice(0, 800) : [],
      paymentMethods: Array.isArray(salvo.paymentMethods) ? salvo.paymentMethods : []
    };
  } catch (_) {
    return criarEstadoFinanceiroCanonicoVazio();
  }
}

function salvarEstadoFinanceiroCanonico(estado) {
  const seguro = { ...criarEstadoFinanceiroCanonicoVazio(), ...(estado || {}), updatedAt: new Date().toISOString() };
  try { localStorage.setItem(getChaveEstadoFinanceiroCanonico(), JSON.stringify(seguro)); }
  catch (_) {}
  return seguro;
}

function operacaoRemotaDeEventoFinanceiro(evento = {}) {
  return {
    id: `local:${evento.operationUuid}`,
    operation_uuid: evento.operationUuid,
    client_request_id: evento.clientRequestId,
    sale_id: evento.orderId,
    operation_type: evento.eventType === "cancel" ? "refund" : "sale",
    status: "completed",
    payload_json: { sale_id: evento.orderId, total_amount: evento.totalAmount, metadata: evento.metadata },
    created_at: evento.createdAt || evento.orderCreatedAt || new Date().toISOString(),
    updated_at: evento.updatedAt || evento.createdAt || new Date().toISOString(),
    source: "local_financial_event"
  };
}

function movimentoRemotoDeEventoFinanceiro(evento = {}) {
  const amount = evento.eventType === "cancel" ? Number(evento.refundAmount) || 0 : Number(evento.receivedAmount) || 0;
  if (!(amount > 0)) return null;
  return {
    id: `local-movement:${evento.operationUuid}`,
    operation_uuid: evento.operationUuid,
    type: evento.eventType === "cancel" ? "estorno" : "sale",
    amount,
    reference_collection: "pedidos",
    reference_id: evento.orderId,
    created_at: evento.createdAt || new Date().toISOString(),
    source: "local_financial_event"
  };
}

