    const digitado = await solicitarEntradaTexto({
      titulo: "WhatsApp do cliente",
      mensagem: "Informe o número com DDD ou DDI.",
      valor: "",
      tipo: "tel"
    });
    numero = normalizarTelefoneWhatsapp(digitado);
