function capturarScrollInterface() {
  if (typeof document === "undefined") return [];
  const snapshot = [];
  const registrar = (elemento, chave) => {
    if (!elemento) return;
    snapshot.push({
      chave,
      top: Number(elemento.scrollTop) || 0,
      left: Number(elemento.scrollLeft) || 0
    });
  };

  registrar(document.scrollingElement || document.documentElement, "__page");
  [
    "#app-content",
    ".mobile-home",
    ".mobile-panel-content",
    ".desktop-main",
    ".sfe-workspace__main",
    ".sfe-workspace__preview",
    ".side-drawer",
    ".profile-premium-panel",
    ".popup-box",
    ".modal-card"
  ].forEach((seletor) => {
    document.querySelectorAll(seletor).forEach((elemento, index) => registrar(elemento, `${seletor}:${index}`));
  });

  return snapshot;
}

function restaurarScrollInterface(snapshot = []) {
  if (!Array.isArray(snapshot) || !snapshot.length || typeof document === "undefined") return;
  const obterElemento = (chave) => {
    if (chave === "__page") return document.scrollingElement || document.documentElement;
    const separador = chave.lastIndexOf(":");
    const seletor = chave.slice(0, separador);
    const index = Number(chave.slice(separador + 1)) || 0;
    return document.querySelectorAll(seletor)[index] || null;
  };
  const aplicar = () => {
    snapshot.forEach((item) => {
      const elemento = obterElemento(item.chave);
      if (!elemento) return;
      elemento.scrollTop = item.top;
      elemento.scrollLeft = item.left;
    });
  };
  requestAnimationFrame(() => {
    aplicar();
    requestAnimationFrame(aplicar);
  });
}

function renderizarPreservandoScroll() {
  const snapshot = capturarScrollInterface();
  const foco = capturarFocoInterface();
  renderApp();
  restaurarScrollInterface(snapshot);
  restaurarFocoInterface(foco);
}

function capturarFocoInterface() {
  const ativo = document.activeElement;
  if (!ativo || !["INPUT", "TEXTAREA", "SELECT"].includes(ativo.tagName)) return null;
  const chave = String(ativo.dataset?.preserveFocusKey || ativo.id || "");
  if (!chave) return null;
  return {
    chave,
    porData: !!ativo.dataset?.preserveFocusKey,
    inicio: typeof ativo.selectionStart === "number" ? ativo.selectionStart : null,
    fim: typeof ativo.selectionEnd === "number" ? ativo.selectionEnd : null
  };
}

function restaurarFocoInterface(snapshot) {
  if (!snapshot?.chave) return;
  requestAnimationFrame(() => {
    const seletor = snapshot.porData
      ? `[data-preserve-focus-key="${CSS.escape(snapshot.chave)}"]`
      : `#${CSS.escape(snapshot.chave)}`;
    const campo = document.querySelector(seletor);
    if (!campo) return;
    campo.focus({ preventScroll: true });
    if (snapshot.inicio !== null && typeof campo.setSelectionRange === "function") {
      const limite = String(campo.value || "").length;
      campo.setSelectionRange(Math.min(snapshot.inicio, limite), Math.min(snapshot.fim ?? snapshot.inicio, limite));
    }
  });
}

function resetarScrollTelaAtiva() {
  if (typeof window === "undefined" || typeof document === "undefined") return;
  requestAnimationFrame(() => {
    try {
      window.scrollTo({ top: 0, left: 0, behavior: "auto" });
    } catch (_) {
      window.scrollTo(0, 0);
    }
    [
      ".desktop-main",
      ".desktop-focus",
      ".mobile-home",
      ".mobile-panel-content"
    ].forEach((seletor) => {
      document.querySelectorAll(seletor).forEach((elemento) => {
        elemento.scrollTop = 0;
        elemento.scrollLeft = 0;
      });
    });
  });
}

function agendarRenderizacaoPreservandoScroll(atraso = 120) {
  if (window.__simplificaRenderPreserveTimer) clearTimeout(window.__simplificaRenderPreserveTimer);
  window.__simplificaRenderPreserveTimer = setTimeout(() => {
    window.__simplificaRenderPreserveTimer = null;
    renderizarPreservandoScroll();
  }, Math.max(0, Number(atraso) || 0));
}

function iniciarTransicaoNavegacao(tipo = "forward") {
  if (typeof document === "undefined") return;
  // Live status refreshes reuse the same render path as navigation. Keeping
  // screen containers opaque prevents the whole interface from flashing.
  clearTimeout(window.__simplificaMotionTimer);
  document.body.classList.remove("motion-forward", "motion-back", "motion-up", "motion-down", "motion-refresh");
  delete document.documentElement.dataset.navDirection;
}

function renderAppComTransicaoNavegacao(tipo = "forward") {
  iniciarTransicaoNavegacao(tipo);
  renderApp();
  requestAnimationFrame(() => aplicarMotionSequenciado());
}

function aplicarMotionSequenciado() {
  if (typeof document === "undefined") return;
  document.querySelectorAll(".motion-stagger-item, .superadmin-cascade-item").forEach((elemento) => {
    elemento.getAnimations?.().forEach((animacao) => animacao.cancel());
    elemento.classList.remove("motion-stagger-item", "superadmin-cascade-item");
    elemento.style.removeProperty("opacity");
    elemento.style.removeProperty("transform");
    elemento.style.removeProperty("will-change");
  });
  window.__simplificaMotionPrimed = true;
  return;
  const superadminEmTransicao = document.body.matches(".motion-forward, .motion-back, .motion-up, .motion-down")
    && !!document.querySelector(".superadmin-platform-shell");
  if (superadminEmTransicao) {
    const alvosSuperadmin = [
      ".superadmin-priority-card",
      ".superadmin-kpi-card",
      ".superadmin-overview-card",
      ".superadmin-plan-card",
      ".superadmin-recent-row",
      ".clients-saas-panel > :not(.users-list)",
      ".clients-saas-panel .client-admin-row",
      ".superadmin-profile-screen > *"
    ].join(",");
    const direcao = document.documentElement.dataset.navDirection || "forward";
    const larguraTela = window.innerWidth || document.documentElement.clientWidth || 0;
    document.querySelectorAll(alvosSuperadmin).forEach((elemento, index) => {
      if (index > 9) return;
      const retangulo = elemento.getBoundingClientRect();
      const estaNaEsquerda = retangulo.left + retangulo.width / 2 <= larguraTela / 2;
      const deslocamento = direcao === "down"
        ? "translate3d(0, -22px, 0)"
        : direcao === "up"
          ? "translate3d(0, 22px, 0)"
          : estaNaEsquerda
            ? "translate3d(-28px, 0, 0)"
            : "translate3d(28px, 0, 0)";
      elemento.getAnimations?.().forEach((animacao) => animacao.cancel());
      elemento.classList.remove("motion-stagger-item", "superadmin-cascade-item");
      elemento.style.opacity = "0";
      elemento.style.transform = deslocamento;
      elemento.style.willChange = "opacity, transform";
      requestAnimationFrame(() => {
        const animacao = elemento.animate([
          { opacity: 0, transform: deslocamento },
          { opacity: 1, transform: "translate3d(0, 0, 0)" }
        ], {
          duration: 1300,
          delay: 200 + index * 410,
          easing: "cubic-bezier(.22,.8,.24,1)",
          fill: "both"
        });
        animacao.onfinish = () => {
          elemento.style.removeProperty("opacity");
          elemento.style.removeProperty("transform");
          elemento.style.removeProperty("will-change");
        };
      });
    });
  }
  if (isMobile() && document.body.dataset.motion !== "high") return;
  const animar = document.body.classList.contains("motion-forward")
    || document.body.classList.contains("motion-back")
    || window.__simplificaMotionPrimed !== true;
  if (!animar) return;
  window.__simplificaMotionPrimed = true;
  const alvos = [
    ".dashboard-kpis .kpi-card",
    ".dashboard-analytics-hero",
    ".analytics-kpi",
    ".dashboard-chart-card",
    ".dashboard-insights",
    ".insight-card",
    ".order-list-card",
    ".order-item-card",
    ".chart-card",
    ".plan-card",
    ".dashboard-simplifica-metric",
    ".dashboard-simplifica-actions",
    ".dashboard-simplifica-grid > .card",
    ".mobile-panel-content > .card",
    ".desktop-focus > .card",
    ".desktop-main > .card"
  ].join(",");
  document.querySelectorAll(alvos).forEach((elemento, index) => {
    if (index > 26) return;
    elemento.classList.add("motion-stagger-item");
    elemento.style.setProperty("--motion-index", String(index));
  });
}

function renderizarStatusSyncSeVisivel() {
  if (["backup", "config", "conta"].includes(telaAtual)) renderizarPreservandoScroll();
}

function sincronizarBannersSeNecessario(force = false) {
  if (!ADS_ENABLED) {
    window.AdMobService?.hideBanner?.("RUNTIME_DISABLED");
    window.AdSenseService?.hideBanner?.("RUNTIME_DISABLED");
    window.AdSenseService?.hideStorefrontSlots?.("RUNTIME_DISABLED");
    return;
  }
  sincronizarAnunciosLojaPublica();
  const agora = Date.now();
  const chave = `${telaAtual}:${getPlanoAtual().status}:${isMobile() ? "m" : "d"}`;
  if (!force && window.__simplificaBannerSyncKey === chave && agora - Number(window.__simplificaBannerSyncAt || 0) < 1500) return;
  window.__simplificaBannerSyncKey = chave;
  window.__simplificaBannerSyncAt = agora;
  sincronizarBannerAdMob();
  sincronizarBannerAdSense();
}

function getParentScreenForBack(tela = telaAtual) {
  const pais = {
    assinatura: "conta",
    planos: "conta",
    minhaAssinatura: "conta",
    seguranca: "conta",
    empresa: "conta",
    preferencias: "config",
    personalizacao: "config",
    pdf: "config",
    backup: "config",
    pedido: "pedidos"
  };
  return pais[tela] || "dashboard";
}

function isDashboardRoute(tela = telaAtual) {
  return String(tela || "").trim() === "dashboard";
}

function fecharCamadaAtualSeExistir() {
  if (fecharSubmenuConfiguracaoAtivo()) {
    return true;
  }
  const popup = document.getElementById("popup");
  if (popup && popup.innerHTML.trim()) {
    fecharPopup();
    return true;
  }
  if (fecharMenusContextuaisUi()) {
    return true;
  }
  if (fecharNavegacaoContextualLojaSeExistir()) {
    return true;
  }
  if (sideDrawerOpen || document.querySelector(".side-drawer")) {
    fecharDrawerLateral();
    return true;
  }
  return false;
}
function fecharNavegacaoContextualLojaSeExistir() {
  return window.SimplificaStorefrontEditor.fecharNavegacaoContextualLojaSeExistir(getStorefrontEditorDeps());
}

function navegarVoltarLojaSeguroInterno(ignoreDirty = false) {
  return window.SimplificaStorefrontEditor.navegarVoltarLojaSeguroInterno(ignoreDirty, getStorefrontEditorDeps());
}


function navegarVoltarSeguroInterno() {
  if (fecharCamadaAtualSeExistir()) {
    atualizarHistoricoBrowserApp(true);
    return true;
  }
  if (navegarVoltarLojaSeguroInterno()) return true;
  if (isDashboardRoute()) return false;

  const destinoStack = navigationStack[navigationStack.length - 1];
  if (destinoStack && telas[destinoStack] && destinoStack !== telaAtual) {
    voltarTela();
    return true;
  }

  const destinoPai = getParentScreenForBack(telaAtual);
  trocarTela(telas[destinoPai] ? destinoPai : "dashboard", {
    resetStack: true,
    skipStack: true,
    replaceHistory: true
  });
  return true;
}

function atualizarHistoricoBrowserApp(replace = false) {
  if (typeof window === "undefined" || !window.history) return;
  const state = { simplifica: true, tela: telaAtual };
  try {
    if (replace) window.history.replaceState(state, document.title, window.location.href);
    else window.history.pushState(state, document.title, window.location.href);
  } catch (_) {}
}

function isModoErpSuperadminAtivo() {
  if (!isSuperAdmin(getUsuarioSessaoReal())) return false;
  try {
    return sessionStorage.getItem("simplificaSuperadminErpMode") === "true";
  } catch (_) {
    return window.__superAdminErpMode === true;
  }
}

function setModoErpSuperadmin(ativo) {
  window.__superAdminErpMode = ativo === true;
  try {
    if (ativo) sessionStorage.setItem("simplificaSuperadminErpMode", "true");
    else sessionStorage.removeItem("simplificaSuperadminErpMode");
  } catch (_) {}
}

function entrarModoErpSuperadmin() {
  if (!isSuperAdmin(getUsuarioSessaoReal())) return;
  setSessaoManutencaoSuperadmin(null);
  billingConfig.clientId = "";
  billingConfig.companyId = "";
  setModoErpSuperadmin(true);
  trocarTela("dashboard", { resetStack: true, skipStack: true, menuRoot: true, replaceHistory: true });
}

function voltarModoSuperadmin() {
  setSessaoManutencaoSuperadmin(null);
  setModoErpSuperadmin(false);
  window.__superAdminTab = normalizarAbaSuperAdmin(window.__superAdminTab || "dashboard");
  trocarTela("superadmin", { resetStack: true, skipStack: true, menuRoot: true, replaceHistory: true });
}

function entrarManutencaoClienteSaas(clientId) {
  const superadminReal = getUsuarioSessaoReal();
  if (!isSuperAdmin(superadminReal)) {
    mostrarToast("Entre como superadmin para abrir manutenção.", "erro", 4200);
    return;
  }
  const cliente = saasClients.find((item) => String(item.id) === String(clientId));
  if (!cliente) {
    mostrarToast("Cliente não encontrado.", "erro", 3600);
    return;
  }
  usuarios = normalizarUsuarios(usuarios);
  const usuariosCliente = getUsuariosDoCliente(cliente.id).filter((usuario) => usuario.ativo !== false && usuario.papel !== "superadmin");
  const usuarioAlvo = usuariosCliente.find((usuario) => usuario.papel === "admin") || usuariosCliente[0];
  if (!usuarioAlvo) {
    mostrarToast("Este cliente ainda não tem usuário ativo para manutenção.", "aviso", 5200);
    return;
  }
  const nomeCliente = cliente.name || usuarioAlvo.nome || usuarioAlvo.email || "cliente";
  const confirmado = confirm(`Abrir manutenção no ERP de ${nomeCliente}?\n\nSua sessão de superadmin será mantida e o login do cliente não será salvo neste aparelho.`);
  if (!confirmado) return;
  setSessaoManutencaoSuperadmin({
    superadminEmail: superadminReal.email,
    targetUserId: usuarioAlvo.id,
    targetEmail: usuarioAlvo.email,
    clientId: cliente.id,
    startedAt: new Date().toISOString()
  });
  setModoErpSuperadmin(false);
  registrarAuditoria("manutenção superadmin iniciada", { targetEmail: usuarioAlvo.email }, cliente.id);
  mostrarToast("Modo manutenção aberto. A sessão do cliente não foi gravada.", "sucesso", 5200);
  trocarTela("dashboard", { resetStack: true, skipStack: true, menuRoot: true, replaceHistory: true });
}

function sairManutencaoSuperadmin() {
  const sessao = getSessaoManutencaoSuperadmin();
  setSessaoManutencaoSuperadmin(null);
  setModoErpSuperadmin(false);
  if (sessao?.clientId) registrarAuditoria("manutenção superadmin encerrada", { targetEmail: sessao.targetEmail || "" }, sessao.clientId);
  mostrarToast("Manutenção encerrada. Você voltou para o painel Superadmin.", "info", 4200);
  voltarModoSuperadmin();
}

function trocarTela(tela, opcoes = {}) {
  fecharMenusContextuaisUi();
  const screenRegistry = window.SimplificaScreenRegistry?.registry;
  const canonicalScreen = screenRegistry?.resolve?.(tela);
  if (canonicalScreen) tela = canonicalScreen.id;
  if (!telas[tela]) {
    tela = "dashboard";
  }
  if (tela === "superadmin" && isSuperAdmin(getUsuarioSessaoReal())) {
    setSessaoManutencaoSuperadmin(null);
    setModoErpSuperadmin(false);
  }

  if (!canAccessScreen(tela)) {
    registrarSeguranca("Acesso negado", "erro", "Tela: " + tela);
    tela = "acessoNegado";
  }

  const mudouTela = telaAtual !== tela;
  if (mudouTela && telaAtual === "relatorios") window.SimplificaReportsFeature?.controller?.unmount?.();
  if (tela === "pedidos" && !opcoes.preservarDetalhePedido) {
    pedidoVisualizandoId = null;
    window.__pedidoDetalheFechado = true;
  }
  if (opcoes.resetStack) {
    navigationStack = [];
  }
  if (mudouTela) {
    if (!opcoes.skipStack && !opcoes.resetStack) {
      const anterior = telaAtual;
      const ultimo = navigationStack[navigationStack.length - 1];
      if (anterior && anterior !== tela && ultimo !== anterior) {
        navigationStack.push(anterior);
        if (navigationStack.length > 24) navigationStack = navigationStack.slice(-24);
      }
    }
    telaAnterior = opcoes.menuRoot ? "dashboard" : (opcoes.resetStack ? getParentScreenForBack(tela) : telaAtual);
  }

  telaAtual = tela;
    if (tela === "relatorios") window.SimplificaAiRuntimeLoader?.ensureFeatureLoaded?.("reports").then(() => { if (telaAtual === "relatorios") renderApp(); }).catch(() => {});
  atualizarContextoAssistantCore3d();
  registrarEventoUsoLocal("tela_aberta", { tela });
  if (tela === "calculadora" && appConfig.calculatorWidget?.open) {
    appConfig.calculatorWidget.open = false;
    salvarDados();
  }
  if (mudouTela && !opcoes.fromHistory) {
    const rotaEspecial = parseStorefrontAdminRoute(location.pathname) || parseStorefrontPublicRoute(location.pathname);
    if (rotaEspecial && tela !== "lojaAdmin" && tela !== "lojaPublica") {
      try {
        history.pushState({ simplifica: true, tela }, document.title, "/");
      } catch (_) {
        atualizarHistoricoBrowserApp(!!opcoes.replaceHistory);
      }
    } else {
      atualizarHistoricoBrowserApp(!!opcoes.replaceHistory);
    }
  }
  if (mudouTela) renderAppComTransicaoNavegacao(opcoes.motionDirection || (tela === "dashboard" ? "back" : "forward"));
  else renderApp();
  if (tela === "promocoes") {
    setTimeout(() => carregarPromocoes3d({ force: true }), 80);
  }
  if (tela === "config") {
    setTimeout(() => carregarConfiguracaoAssistenteIa({ render: true }), 80);
  }
  if (mudouTela) resetarScrollTelaAtiva();
}

function voltarTela() {
  if (fecharCamadaAtualSeExistir()) return;
  if (telaAtual === "pedidos" && pedidoVisualizandoId != null) {
    fecharDetalhesPedido();
    return;
  }
  const destinoStack = navigationStack.pop();
  const destino = telas[destinoStack] ? destinoStack : (telas[telaAnterior] ? telaAnterior : getParentScreenForBack(telaAtual));
  const atual = telaAtual;
  telaAtual = destino;
  telaAnterior = navigationStack[navigationStack.length - 1] || getParentScreenForBack(destino);
  atualizarHistoricoBrowserApp(true);
  renderAppComTransicaoNavegacao("back");
  if (atual !== destino) resetarScrollTelaAtiva();
}

function voltarInicio() {
  telaAnterior = telaAtual;
  navigationStack = [];
  telaAtual = "dashboard";
  atualizarHistoricoBrowserApp(true);
  renderAppComTransicaoNavegacao("back");
}

async function lidarComVoltarSistema(event = null) {
  return handleAndroidBackPress({ source: "system", event });
}

async function solicitarConfirmacaoSaidaAndroid() {
  if (androidBackConfirmOpen) return false;
  androidBackConfirmOpen = true;
  try {
    return await solicitarConfirmacaoAcao({
      titulo: "Sair do aplicativo",
      mensagem: "Deseja realmente sair do aplicativo?",
      confirmar: "Sair",
      cancelar: "Cancelar",
      perigo: false
    });
  } catch (erro) {
    registrarDiagnostico("Navegação", "Confirmação de saída falhou", erro?.message || String(erro || ""));
    return window.confirm("Deseja realmente sair do aplicativo?");
  } finally {
    androidBackConfirmOpen = false;
  }
}

function sairAplicativoAndroidConfirmado() {
  if (androidBackExitInProgress) return true;
  androidBackExitInProgress = true;
  try {
    const appPlugin = window.Capacitor?.Plugins?.App;
    if (isAndroidNativeApp() && appPlugin?.exitApp) {
      appPlugin.exitApp();
      return true;
    }
  } catch (erro) {
    registrarDiagnostico("Navegação", "Falha ao fechar APK", erro?.message || String(erro || ""));
  } finally {
    setTimeout(() => {
      androidBackExitInProgress = false;
    }, 1600);
  }
  return false;
}

async function handleAndroidBackPress(opcoes = {}) {
  const dados = opcoes && typeof opcoes === "object" && ("source" in opcoes || "event" in opcoes || "nativeEvent" in opcoes)
    ? opcoes
    : { source: "event", event: opcoes };
  const evento = dados.event || dados.nativeEvent || null;
  evento?.preventDefault?.();
  const origem = String(dados.source || "");
  const agora = Date.now();
  if (androidBackConfirmOpen) return true;
  if (agora - lastAndroidBackHandledAt < 450) return true;
  lastAndroidBackHandledAt = agora;

  if (navegarVoltarSeguroInterno()) return true;

  if (!isDashboardRoute()) {
    trocarTela("dashboard", { resetStack: true, skipStack: true, replaceHistory: true });
    return true;
  }

  atualizarHistoricoBrowserApp(true);
  if (!isAndroidNativeApp()) return true;
  const confirmou = await solicitarConfirmacaoSaidaAndroid();
  if (!confirmou) {
    lastDashboardBackPromptAt = Date.now();
    mostrarToast("Saída cancelada.", "info", 1800);
    atualizarHistoricoBrowserApp(true);
    return true;
  }

  if (!sairAplicativoAndroidConfirmado()) {
    mostrarToast("Não foi possível fechar o app automaticamente.", "erro", 2600);
    atualizarHistoricoBrowserApp(true);
  }
  return true;
}

function removerAndroidBackHandler() {
  try {
    androidBackButtonListener?.remove?.();
  } catch (_) {}
  androidBackButtonListener = null;
  window.__simplificaAndroidBackHandlerConfigured = false;
}

function registrarAndroidBackHandler() {
  if (!isAndroidNativeApp()) return;
  const appPlugin = window.Capacitor?.Plugins?.App;
  if (!appPlugin?.addListener || window.__simplificaAndroidBackHandlerConfigured) return;
  window.__simplificaAndroidBackHandlerConfigured = true;
  try {
    const listener = appPlugin.addListener("backButton", (event) => {
      handleAndroidBackPress({ source: "capacitor-back", nativeEvent: event });
    });
    if (listener?.then) {
      listener
        .then((handle) => {
          androidBackButtonListener = handle;
        })
        .catch((erro) => {
          window.__simplificaAndroidBackHandlerConfigured = false;
          registrarDiagnostico("Navegação", "BackHandler Android não registrado", erro?.message || String(erro || ""));
        });
    } else {
      androidBackButtonListener = listener;
    }
  } catch (erro) {
    window.__simplificaAndroidBackHandlerConfigured = false;
    registrarDiagnostico("Navegação", "BackHandler Android falhou", erro?.message || String(erro || ""));
  }
}

