function renderDesktop() {
  if (telaAtual === "lojaPublica") {
    return renderTela("lojaPublica");
  }
  if (telaAtual === "lojaAdmin") {
    return renderStorefrontAdminStandalone();
  }
  if (!getUsuarioAtual() && telaAtual === "admin") {
    return `<main class="auth-desktop-main">${renderAdmin()}</main>`;
  }
  if (telaAtual === "superadmin" && isSuperAdmin()) {
    return `<main class="superadmin-only-main app-content">${renderTela("superadmin")}</main>`;
  }
  const classeMenu = appConfig.sidebarCollapsed ? " sidebar-collapsed" : "";
  return `
    <div class="desktop-shell${classeMenu}">
      ${renderMenuLateral()}
      <main class="desktop-main app-content">
        ${renderTopbar()}
        ${renderSuperAdminMaintenanceBanner()}
        ${renderAccountDeletionBanner()}
        ${renderDesktopConteudo()}
      </main>
    </div>
  `;
}

function renderDesktopConteudo() {
  if (!canAccessScreen(telaAtual)) {
    return `<div class="desktop-focus app-page">${renderAcessoNegado()}</div>`;
  }

  const configuracoes = ["config", "backup", "personalizacao", "empresa", "administracao", "preferencias", "pdf", "mais", "conta", "assinatura", "minhaAssinatura", "planos", "admin", "usuarios", "seguranca", "lojaOnline", "lojaAdmin", "superadmin", "privacy", "terms", "acessoNegado"];
  const atualizacaoAndroid = renderAtualizacaoAndroidDownload();

  if (configuracoes.includes(telaAtual)) {
    return `<div class="desktop-focus app-page">${atualizacaoAndroid}${renderTelaComUiV3(telaAtual)}</div>`;
  }

  if (telaAtual !== "dashboard") {
    return `<div class="desktop-focus app-page desktop-page-${escaparAttr(telaAtual)}">${atualizacaoAndroid}${renderTelaComUiV3(telaAtual)}</div>`;
  }

  return `${atualizacaoAndroid}${renderDashboard()}`;
}

