function getMobileBottomNavItems() {
  const itensSimplifica = [
    { tela: "dashboard", icone: "⌂", texto: "Início" },
    { tela: "pedidos", icone: "pedidos", texto: "Pedidos" },
    { tela: "calculadora", icone: "calculadora", texto: "Calcular" },
    { acao: "abrirMenuPopup()", iconKey: "plus", icone: "+", texto: "Mais" }
  ];
  const itensProfissional = [
    { tela: "dashboard", icone: "⌂", texto: "Home" },
    { tela: "pedidos", icone: "pedidos", texto: "Pedidos" },
    { tela: "producao", icone: "producao", texto: "Produção" },
    { tela: "caixa", icone: "caixa", texto: "Caixa" }
  ];
  return (isSimplificaMode() ? itensSimplifica : itensProfissional)
    .filter((item) => shouldShowMenuItem(item) && (!item.tela || canAccessScreen(item.tela)));
}

function getMobileBottomNavActive() {
  const principais = new Set(getMobileBottomNavItems().map((item) => item.tela));
  return principais.has(telaAtual) ? telaAtual : "";
}

function renderMobileBottomNav() {
  const ativo = getMobileBottomNavActive();
  const itens = getMobileBottomNavItems();
  if (!itens.length || !getUsuarioAtual()) return "";
  return `
    <nav class="mobile-bottom-nav app-bottom-navigation" aria-label="Navegação principal" style="grid-template-columns:repeat(${itens.length}, minmax(0, 1fr))">
      ${itens.map((item) => `
        <button class="mobile-bottom-nav-button ${item.tela && ativo === item.tela ? "active" : ""}" ${item.tela ? `data-tela="${item.tela}"` : `data-nav-action="more"`} type="button" onclick="${item.acao || `navegarMenuPrincipal('${item.tela}')`}" aria-label="${escaparAttr(item.texto)}">
          <span>${renderUiIcon(item.iconKey || getUiScreenRelation(item.tela)?.icon || item.tela, item.icone)}</span>
          <small>${escaparHtml(item.texto)}</small>
        </button>
      `).join("")}
    </nav>
  `;
}

function gerenciarScrollContainerTeclado(event) {
  if (!event || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.target?.closest?.("input, textarea, select, button, a, [contenteditable='true']")) return;
  const container = event.currentTarget;
  if (!container || container.scrollHeight <= container.clientHeight) return;
  const pageStep = Math.max(160, Math.round(container.clientHeight * 0.82));
  const key = String(event.key || "");
  let nextTop = null;
  if (key === "PageDown" || (key === " " && !event.shiftKey)) nextTop = container.scrollTop + pageStep;
  if (key === "PageUp" || (key === " " && event.shiftKey)) nextTop = container.scrollTop - pageStep;
  if (key === "ArrowDown") nextTop = container.scrollTop + 48;
  if (key === "ArrowUp") nextTop = container.scrollTop - 48;
  if (key === "Home") nextTop = 0;
  if (key === "End") nextTop = container.scrollHeight;
  if (nextTop === null) return;
  event.preventDefault();
  container.scrollTo({ top: nextTop, behavior: "smooth" });
}

function renderPainelMobile(tela) {
  if (tela === "calculadora") {
    return `
      <section class="mobile-panel mobile-panel-calculator" role="dialog" aria-modal="true" aria-label="${escaparAttr(telas[tela])}">
        <div class="mobile-panel-content app-content calculator-panel-content" tabindex="0" onkeydown="gerenciarScrollContainerTeclado(event)">
          ${renderTelaComUiV3(tela)}
        </div>
      </section>
    `;
  }
  const classePainel = tela === "pedido" ? " mobile-panel-order" : "";
  const exibirMenuPainel = !["mais", "acessoNegado", "planos", "assinatura", "minhaAssinatura", "privacy", "terms", "sobre"].includes(tela);
  return `
    <section class="mobile-panel${classePainel}" role="dialog" aria-modal="true" aria-label="${escaparAttr(telas[tela])}">
      <div class="mobile-panel-bar app-header">
        <button class="icon-button" onclick="${tela === "administracao" ? "voltarAdministracaoEmpresa()" : "voltarTela()"}" title="Voltar">←</button>
        <h2>${escaparHtml(telas[tela])}</h2>
        <div class="mobile-panel-actions">
          ${exibirMenuPainel ? `<button class="icon-button mobile-panel-menu-button" onclick="abrirMenuPopup()" title="Abrir menu" aria-label="Abrir menu">${renderMenuHandleIcon()}</button>` : ""}
        </div>
      </div>
      <div class="mobile-panel-content app-content" tabindex="0" onkeydown="gerenciarScrollContainerTeclado(event)">
        ${renderTelaComUiV3(tela)}
      </div>
    </section>
  `;
}

function renderTelaComUiV3(tela) {
  return window.SimplificaScreenV3Wrapper.render(tela, { escaparAttr, renderScreen: renderTela });
}

function renderTela(tela) {
  return window.SimplificaScreenDispatcher.render(tela, { canAccessScreen, renderAcessoNegado, screenRegistry: window.SimplificaScreenRegistry?.registry, renderers: { mais: renderMais, promocoes: renderPromocoes3d, conta: renderConta, administracao: renderAdministracaoEmpresa, calculadora: renderCalculadoraTela, pedido: renderPedido, producao: renderProducao, impressoras: renderImpressoras, estoque: renderEstoque, pedidos: renderListaPedidos, clientes: renderClientes, caixa: renderCaixa, relatorios: renderRelatorios, backup: renderConfig, config: renderConfig, empresa: renderEmpresaConfig, preferencias: renderCalculadoraConfigPage, personalizacao: renderAparenciaConfig, pdf: renderPdfConfig, planos: renderAssinatura, assinatura: renderAssinatura, minhaAssinatura: renderMinhaAssinatura, feedback: renderFeedback, sobre: renderSobre, seguranca: renderSeguranca, onboarding: renderOnboarding, acessoNegado: renderAcessoNegado, usuarios: renderAdmin, admin: renderAdmin, lojaOnline: renderLojaOnlineHub, lojaAdmin: renderStorefrontAdminPanel, lojaPublica: renderLojaOnlinePublica, superadmin: renderSuperAdmin, dashboard: renderDashboard, renderDocumentoLegalPage } });
}

function lerPreferenciaAvisosPromocoes3d() {
  try {
    return localStorage.getItem(PROMOTIONS_3D_ALERTS_KEY) === "true";
  } catch {
    return false;
  }
}

function carregarMonitorPromocoes3d() {
  try {
    const stored = JSON.parse(localStorage.getItem(PROMOTIONS_3D_MONITOR_KEY) || "{}");
    const watches = Array.isArray(stored.watches) ? stored.watches
      .map((item) => ({
        id: String(item?.id || ""),
        type: item?.type === "product" ? "product" : "query",
        value: String(item?.value || "").slice(0, 180),
        label: String(item?.label || item?.value || "").slice(0, 180),
        createdAt: String(item?.createdAt || "")
      }))
      .filter((item) => item.id && item.value && item.label)
      .slice(0, PROMOTIONS_3D_MAX_WATCHES) : [];
    promotions3dMonitorState = {
      initialized: stored.initialized === true,
      watches,
      knownIds: Array.isArray(stored.knownIds) ? [...new Set(stored.knownIds.map(String).filter(Boolean))].slice(0, 120) : [],
      unreadIds: Array.isArray(stored.unreadIds) ? [...new Set(stored.unreadIds.map(String).filter(Boolean))].slice(0, 99) : [],
      lastCheckedAt: String(stored.lastCheckedAt || "")
    };
  } catch {
    promotions3dMonitorState = { initialized: false, watches: [], knownIds: [], unreadIds: [], lastCheckedAt: "" };
  }
  return promotions3dMonitorState;
}

function salvarMonitorPromocoes3d() {
  try {
    localStorage.setItem(PROMOTIONS_3D_MONITOR_KEY, JSON.stringify(promotions3dMonitorState));
  } catch {}
}

function getNovidadesPromocoes3dCount() {
  return new Set(promotions3dMonitorState.unreadIds || []).size;
}

function atualizarIndicadoresMenuPromocoes3d() {
  const count = getNovidadesPromocoes3dCount();
  document.querySelectorAll("[data-promo-badge]").forEach((badge) => {
    badge.textContent = String(Math.min(99, count));
    badge.hidden = count <= 0;
  });
}

function getTextoBuscaPromocao3d(item = {}) {
  return normalizarTextoBusca(`${item.title || ""} ${item.store || ""} ${getNomeCategoriaPromocao3d(item.category)} ${item.id || ""}`);
}

function promocaoCorrespondeAcompanhamento3d(item, watch) {
  if (!item || !watch) return false;
  if (watch.type === "product") return String(item.id) === String(watch.value);
  const query = normalizarTextoBusca(watch.value || watch.label || "");
  return !!query && getTextoBuscaPromocao3d(item).includes(query);
}

function getAcompanhamentosPromocao3d(item = null) {
  const watches = Array.isArray(promotions3dMonitorState.watches) ? promotions3dMonitorState.watches : [];
  return item ? watches.filter((watch) => promocaoCorrespondeAcompanhamento3d(item, watch)) : watches;
}

function processarMonitorPromocoes3d(items = []) {
  if (!promotions3dMonitorState.initialized && !promotions3dMonitorState.watches.length && !promotions3dMonitorState.knownIds.length) {
    carregarMonitorPromocoes3d();
  }
  const validItems = Array.isArray(items) ? items.filter(Boolean) : [];
  const currentIds = new Set(validItems.map((item) => String(item.id)));
  const knownIds = new Set(promotions3dMonitorState.knownIds || []);
  const newItems = promotions3dMonitorState.initialized
    ? validItems.filter((item) => !knownIds.has(String(item.id)))
    : [];
  const watchedNewItems = newItems.filter((item) => getAcompanhamentosPromocao3d(item).length);
  const unreadIds = new Set((promotions3dMonitorState.unreadIds || []).filter((id) => currentIds.has(String(id))));
  newItems.forEach((item) => unreadIds.add(String(item.id)));
  promotions3dMonitorState.initialized = true;
  promotions3dMonitorState.knownIds = Array.from(currentIds).slice(0, 120);
  promotions3dMonitorState.unreadIds = Array.from(unreadIds).slice(0, 99);
  promotions3dMonitorState.lastCheckedAt = new Date().toISOString();
  salvarMonitorPromocoes3d();
  atualizarIndicadoresMenuPromocoes3d();
  if (!newItems.length) return;
  const monitoredCount = watchedNewItems.length;
  if (monitoredCount) {
    mostrarToast(monitoredCount === 1
      ? "O monitor encontrou uma nova oferta que você acompanha."
      : `O monitor encontrou ${monitoredCount} novas ofertas que você acompanha.`, "sucesso", 6200);
  }
  if (lerPreferenciaAvisosPromocoes3d()) {
    mostrarNotificacaoExternaPromocoes3d(watchedNewItems.length ? watchedNewItems : newItems);
  }
}

function mostrarNotificacaoExternaPromocoes3d(items = []) {
  if (!lerPreferenciaAvisosPromocoes3d() || typeof Notification === "undefined" || Notification.permission !== "granted") return;
  const first = items[0];
  if (!first) return;
  try {
    const notification = new Notification(items.length === 1 ? "Nova oferta 3D" : `${items.length} novas ofertas 3D`, {
      body: items.length === 1 ? `${first.title} por ${formatarMoeda(first.currentPrice)}` : "Abra o Simplifica 3D para conferir as novidades.",
      icon: PROJECT_ICON_IMAGE,
      tag: "simplifica-3d-promocoes",
      renotify: true
    });
    notification.onclick = () => {
      window.focus?.();
      trocarTela("promocoes");
      notification.close?.();
    };
  } catch {}
}

function marcarPromocoes3dComoVistas() {
  promotions3dMonitorState.unreadIds = [];
  salvarMonitorPromocoes3d();
  atualizarIndicadoresMenuPromocoes3d();
  atualizarPainelMonitorPromocoes3d();
  mostrarToast("Novidades marcadas como vistas.", "info", 2400);
}

function salvarBuscaAtualPromocoes3d() {
  const query = String(promotions3dState.query || "").trim().replace(/\s+/g, " ");
  if (query.length < 2) {
    mostrarToast("Digite o produto que deseja acompanhar.", "aviso", 3000);
    return;
  }
  carregarMonitorPromocoes3d();
  if (promotions3dMonitorState.watches.some((watch) => watch.type === "query" && normalizarTextoBusca(watch.value) === normalizarTextoBusca(query))) {
    mostrarToast("Essa busca já está sendo acompanhada.", "info", 2600);
    return;
  }
  if (promotions3dMonitorState.watches.length >= PROMOTIONS_3D_MAX_WATCHES) {
    mostrarToast(`Você pode acompanhar até ${PROMOTIONS_3D_MAX_WATCHES} buscas ou produtos.`, "aviso", 3400);
    return;
  }
  promotions3dMonitorState.watches.push({
    id: `query-${Date.now()}`,
    type: "query",
    value: query,
    label: query,
    createdAt: new Date().toISOString()
  });
  salvarMonitorPromocoes3d();
  atualizarPainelMonitorPromocoes3d();
  atualizarResultadosPromocoes3d();
  mostrarToast(`O monitor agora acompanha “${query}”.`, "sucesso", 3200);
}

function alternarAcompanhamentoProdutoPromocao3d(id = "") {
  carregarMonitorPromocoes3d();
  const item = promotions3dState.items.find((offer) => String(offer.id) === String(id));
  if (!item) return mostrarToast("Esta oferta não está mais disponível.", "aviso", 3000);
  const existingIndex = promotions3dMonitorState.watches.findIndex((watch) => watch.type === "product" && String(watch.value) === String(item.id));
  if (existingIndex >= 0) {
    promotions3dMonitorState.watches.splice(existingIndex, 1);
    mostrarToast("Produto removido do monitor.", "info", 2600);
  } else {
    if (promotions3dMonitorState.watches.length >= PROMOTIONS_3D_MAX_WATCHES) {
      return mostrarToast(`Você pode acompanhar até ${PROMOTIONS_3D_MAX_WATCHES} buscas ou produtos.`, "aviso", 3400);
    }
    promotions3dMonitorState.watches.push({
      id: `product-${String(item.id)}`,
      type: "product",
      value: String(item.id),
      label: String(item.title),
      createdAt: new Date().toISOString()
    });
    mostrarToast("Produto adicionado ao monitor de ofertas.", "sucesso", 3000);
  }
  salvarMonitorPromocoes3d();
  atualizarPainelMonitorPromocoes3d();
  atualizarResultadosPromocoes3d();
}

function removerAcompanhamentoPromocao3d(id = "") {
  carregarMonitorPromocoes3d();
  promotions3dMonitorState.watches = promotions3dMonitorState.watches.filter((watch) => String(watch.id) !== String(id));
  salvarMonitorPromocoes3d();
  atualizarPainelMonitorPromocoes3d();
  atualizarResultadosPromocoes3d();
}

function aplicarAcompanhamentoPromocao3d(id = "") {
  const watch = promotions3dMonitorState.watches.find((item) => String(item.id) === String(id));
  if (!watch) return;
  const item = watch.type === "product"
    ? promotions3dState.items.find((offer) => String(offer.id) === String(watch.value))
    : null;
  const query = item?.title || watch.label;
  promotions3dState.query = String(query || "").slice(0, 80);
  const search = document.querySelector(".promotions-3d-search input");
  if (search) search.value = promotions3dState.query;
  atualizarResultadosPromocoes3d();
  atualizarPainelMonitorPromocoes3d();
}

function carregarCachePromocoes3d() {
  try {
    const cache = JSON.parse(localStorage.getItem(PROMOTIONS_3D_CACHE_KEY) || "{}");
    const items = Array.isArray(cache.items) ? cache.items.map(normalizarPromocao3d).filter(Boolean) : [];
    const stores = Array.isArray(cache.stores) ? cache.stores.filter((store) => store?.name && store?.host) : [];
    if (items.length) {
      promotions3dState.items = items;
      promotions3dState.stores = stores;
      promotions3dState.updatedAt = String(cache.updatedAt || "");
    }
  } catch {}
}

function salvarCachePromocoes3d() {
  try {
    localStorage.setItem(PROMOTIONS_3D_CACHE_KEY, JSON.stringify({
      items: promotions3dState.items,
      stores: promotions3dState.stores,
      updatedAt: promotions3dState.updatedAt
    }));
  } catch {}
}

function normalizarPromocao3d(item = {}) {
  try {
    const url = new URL(String(item.url || ""));
    if (url.protocol !== "https:" || !PROMOTIONS_3D_OFFICIAL_HOSTS.includes(url.hostname.toLowerCase())) return null;
    const categorias = new Set(["impressoras", "filamentos", "resinas", "materiais"]);
    const category = categorias.has(item.category) ? item.category : "materiais";
    const currentPrice = Number(item.currentPrice) || 0;
    if (!item.id || !item.title || currentPrice <= 0) return null;
    const imageUrl = String(item.image || "");
    const image = imageUrl.startsWith("https://") ? imageUrl : "";
    const expiresAt = Number.isFinite(Date.parse(String(item.expiresAt || ""))) ? String(item.expiresAt) : "";
    if (expiresAt && Date.parse(expiresAt) <= Date.now()) return null;
    return {
      id: String(item.id),
      store: String(item.store || "Loja oficial"),
      host: url.hostname.toLowerCase(),
      title: String(item.title),
      category,
      currentPrice,
      pixPrice: Math.max(0, Number(item.pixPrice) || 0),
      oldPrice: Math.max(0, Number(item.oldPrice) || 0),
      discount: Math.max(0, Math.min(99, Math.round(Number(item.discount) || 0))),
      image,
      url: url.toString(),
      publishedAt: Number.isFinite(Date.parse(String(item.publishedAt || ""))) ? String(item.publishedAt) : "",
      updatedAt: Number.isFinite(Date.parse(String(item.updatedAt || ""))) ? String(item.updatedAt) : "",
      expiresAt
    };
  } catch {
    return null;
  }
}

function formatarAtualizacaoPromocoes3d(value = promotions3dState.updatedAt) {
  return window.SimplificaDateFormatters.formatUpdatedAt(value);
}

function formatarTempoOfertaPromocao3d(item = {}) {
  return window.SimplificaStorefrontPromotionFormatters.formatOfferTime(item);
}

function getNomeCategoriaPromocao3d(category = "") {
  return window.SimplificaStorefrontPromotionFormatters.getCategoryLabel(category);
}

function getPromocoes3dVisiveis() {
  const query = normalizarTextoBusca(promotions3dState.query || "");
  const filtered = promotions3dState.items.filter((item) => {
    if (promotions3dState.filter !== "todas" && item.category !== promotions3dState.filter) return false;
    if (promotions3dState.store !== "todas" && item.host !== promotions3dState.store) return false;
    if (item.discount < promotions3dState.discountMin) return false;
    if (!query) return true;
    return normalizarTextoBusca(`${item.title} ${item.store} ${getNomeCategoriaPromocao3d(item.category)}`).includes(query);
  });
  const sorted = filtered.sort((a, b) => {
    if (promotions3dState.sort === "menor-preco") return a.currentPrice - b.currentPrice || b.discount - a.discount;
    if (promotions3dState.sort === "maior-desconto") return b.discount - a.discount || a.currentPrice - b.currentPrice;
    if (promotions3dState.sort === "melhores") {
      return Number(b.discount > 0) - Number(a.discount > 0)
        || b.discount - a.discount
        || Date.parse(b.updatedAt || b.publishedAt || 0) - Date.parse(a.updatedAt || a.publishedAt || 0)
        || a.currentPrice - b.currentPrice;
    }
    return Date.parse(b.updatedAt || b.publishedAt || 0) - Date.parse(a.updatedAt || a.publishedAt || 0)
      || Number(b.discount > 0) - Number(a.discount > 0)
      || b.discount - a.discount
      || a.currentPrice - b.currentPrice;
  });
  if (promotions3dState.store !== "todas" || promotions3dState.sort !== "recentes") {
    return sorted.slice(0, PROMOTIONS_3D_VISIBLE_LIMIT);
  }
  const queues = new Map();
  sorted.forEach((item) => {
    const queue = queues.get(item.host) || [];
    queue.push(item);
    queues.set(item.host, queue);
  });
  const diverse = [];
  while (diverse.length < PROMOTIONS_3D_VISIBLE_LIMIT && Array.from(queues.values()).some((queue) => queue.length)) {
    queues.forEach((queue) => {
      if (queue.length && diverse.length < PROMOTIONS_3D_VISIBLE_LIMIT) diverse.push(queue.shift());
    });
  }
  return diverse;
}

function deveDestacarOfertasRelampago3d() {
  return !normalizarTextoBusca(promotions3dState.query || "")
    && promotions3dState.filter === "todas"
    && promotions3dState.store === "todas"
    && promotions3dState.sort === "recentes";
}

function renderCardPromocao3d(item, index = 0, { flash = false, highlight = true } = {}) {
  const highlighted = flash || (highlight && index < 3 && item.discount > 0);
  const monitored = promotions3dMonitorState.watches.some((watch) => watch.type === "product" && String(watch.value) === String(item.id));
  return `
    <article class="promotion-3d-card ${highlighted ? "is-highlighted" : ""} ${flash ? "is-flash" : ""}">
      <div class="promotion-3d-media">
        ${item.image
          ? `<img src="${escaparAttr(item.image)}" alt="${escaparAttr(item.title)}" loading="lazy" onerror="this.remove()">`
          : `<span>${renderUiIcon(item.category === "impressoras" ? "impressoras" : item.category === "filamentos" ? "filamento" : item.category === "resinas" ? "resina" : "produtos")}</span>`}
        <div class="promotion-3d-badges">
          ${highlighted ? `<strong>${flash ? "Oferta relâmpago" : "Melhor oferta"}</strong>` : ""}
          ${item.discount > 0 ? `<em>${item.discount}% OFF</em>` : `<em>Oferta</em>`}
        </div>
      </div>
      <div class="promotion-3d-card-body">
        <div class="promotion-3d-store">
          <span>${renderUiIcon("seguranca")} Loja oficial</span>
          <span class="promotion-3d-store-actions">
            <strong>${escaparHtml(item.store)}</strong>
            <button class="promotion-watch-product ${monitored ? "active" : ""}" type="button" aria-pressed="${monitored}" onclick="alternarAcompanhamentoProdutoPromocao3d('${escaparAttr(item.id)}')" title="${monitored ? "Parar de acompanhar" : "Acompanhar este produto"}" aria-label="${monitored ? "Parar de acompanhar este produto" : "Acompanhar este produto"}">
              ${renderUiIcon("bell")}
            </button>
          </span>
        </div>
        <h3>${escaparHtml(item.title)}</h3>
        <span class="promotion-3d-category">${escaparHtml(getNomeCategoriaPromocao3d(item.category))}</span>
        <div class="promotion-3d-price">
          ${item.oldPrice > item.currentPrice ? `<del>${formatarMoeda(item.oldPrice)}</del>` : ""}
          <strong>${formatarMoeda(item.currentPrice)}</strong>
          ${item.pixPrice > 0 && item.pixPrice < item.currentPrice
            ? `<small class="promotion-3d-pix">No Pix: <strong>${formatarMoeda(item.pixPrice)}</strong></small>`
            : `<small>Preço anunciado • confira o valor final na loja</small>`}
        </div>
        <span class="promotion-3d-validity ${item.expiresAt ? "has-expiration" : ""}">
          ${renderUiIcon("clock")} ${escaparHtml(formatarTempoOfertaPromocao3d(item))}
        </span>
        <a class="btn promotion-3d-open" href="${escaparAttr(item.url)}" target="_blank" rel="noopener noreferrer">
          ${renderUiIcon("lojaonline")} Ver oferta
        </a>
      </div>
    </article>
  `;
}

function renderPainelMonitorPromocoes3d() {
  const watches = getAcompanhamentosPromocao3d();
  const unread = getNovidadesPromocoes3dCount();
  const query = String(promotions3dState.query || "").trim();
  return `
    <section class="promotions-3d-monitor card" aria-labelledby="promotions-monitor-title">
      <div class="promotions-monitor-head">
        <span class="promotions-monitor-icon">${renderUiIcon("bell")}</span>
        <div>
          <span class="promotions-monitor-status">Monitor automático ativo</span>
          <h2 id="promotions-monitor-title">Acompanhe o que você quer comprar</h2>
          <p>Pesquise um produto e salve a busca. O Simplifica continuará conferindo enquanto estiver aberto.</p>
        </div>
        ${unread ? `
          <div class="promotions-monitor-news" role="status">
            <strong>${unread}</strong>
            <span>${unread === 1 ? "novidade" : "novidades"}</span>
            <button type="button" onclick="marcarPromocoes3dComoVistas()">Marcar como vistas</button>
          </div>
        ` : `<span class="promotions-monitor-ok">${renderUiIcon("seguranca")} Tudo conferido</span>`}
      </div>
      <div class="promotions-monitor-action">
        <span>${query ? `Busca atual: <strong>${escaparHtml(query)}</strong>` : "Digite acima o produto que deseja acompanhar."}</span>
        <button class="btn secondary" id="promotionsWatchQueryButton" type="button" onclick="salvarBuscaAtualPromocoes3d()" ${query.length >= 2 ? "" : "disabled"}>
          ${renderUiIcon("plus")} Acompanhar esta busca
        </button>
      </div>
      ${watches.length ? `
        <div class="promotions-monitor-watches" aria-label="Buscas e produtos acompanhados">
          ${watches.map((watch) => `
            <span class="promotions-monitor-watch">
              <button type="button" onclick="aplicarAcompanhamentoPromocao3d('${escaparAttr(watch.id)}')" title="Mostrar ofertas relacionadas">${renderUiIcon(watch.type === "product" ? "produtos" : "search")} ${escaparHtml(watch.label)}</button>
              <button type="button" onclick="removerAcompanhamentoPromocao3d('${escaparAttr(watch.id)}')" title="Parar de acompanhar" aria-label="Parar de acompanhar ${escaparAttr(watch.label)}">×</button>
            </span>
          `).join("")}
        </div>
      ` : ""}
    </section>
  `;
}

function renderResultadosPromocoes3d() {
  const items = getPromocoes3dVisiveis();
  const updating = promotions3dState.status === "loading";
  if (!items.length && updating) {
    return `
      <div class="promotions-3d-empty">
        <span class="smart-loader-spinner" aria-hidden="true"></span>
        <strong>Buscando ofertas ativas...</strong>
        <p>Estamos conferindo as lojas oficiais.</p>
      </div>
    `;
  }
  if (!items.length) {
    return `
      <div class="promotions-3d-empty">
        ${renderUiIcon("search")}
        <strong>Nenhuma oferta encontrada</strong>
        <p>Tente outro nome ou escolha “Todas”.</p>
        <button class="btn secondary" type="button" onclick="limparFiltrosPromocoes3d()">Limpar filtros</button>
      </div>
    `;
  }
  const flashItems = deveDestacarOfertasRelampago3d()
    ? items.filter((item) => item.discount > 0).slice(0, 3)
    : [];
  const flashUrls = new Set(flashItems.map((item) => item.url));
  const regularItems = flashItems.length
    ? items.filter((item) => !flashUrls.has(item.url))
    : items;
  return `
    ${flashItems.length ? `
      <section class="promotions-3d-flash" aria-labelledby="promotions-3d-flash-title">
        <div class="promotions-3d-section-head">
          <div>
            <span>${renderUiIcon("cupom")} Destaques de agora</span>
            <h2 id="promotions-3d-flash-title">Ofertas relâmpago</h2>
            <p>Ofertas atualizadas recentemente nas lojas oficiais. Elas podem acabar rápido.</p>
          </div>
          ${updating ? `<small>Atualizando...</small>` : `<small>${escaparHtml(formatarAtualizacaoPromocoes3d())}</small>`}
        </div>
        <div class="promotions-3d-flash-grid">
          ${flashItems.map((item, index) => renderCardPromocao3d(item, index, { flash: true })).join("")}
        </div>
      </section>
    ` : ""}
    ${regularItems.length ? `
      <section class="promotions-3d-all" aria-label="${flashItems.length ? "Mais ofertas" : "Ofertas encontradas"}">
        <div class="promotions-3d-result-head">
          <span><strong>${items.length}</strong> oferta(s) ativa(s) exibida(s)</span>
          ${flashItems.length
            ? `<small>Mais ofertas para você</small>`
            : updating
              ? `<small>Atualizando...</small>`
              : `<small>${escaparHtml(formatarAtualizacaoPromocoes3d())}</small>`}
        </div>
        <div class="promotions-3d-grid">
          ${regularItems.map((item, index) => renderCardPromocao3d(item, index, { highlight: !flashItems.length })).join("")}
        </div>
      </section>
    ` : ""}
  `;
}
function renderOpcoesLojasPromocoes3d() {
  return window.SimplificaStorefrontAdminRender.renderOpcoesLojasPromocoes3d(getStorefrontAdminRenderDeps());
}


function renderPromocoes3d() {
  if (promotions3dState.status === "idle" && !promotions3dState.items.length) carregarCachePromocoes3d();
  if (!promotions3dMonitorState.initialized && !promotions3dMonitorState.watches.length) carregarMonitorPromocoes3d();
  const alertsEnabled = lerPreferenciaAvisosPromocoes3d();
  return `
    <section class="ui3-real-screen ui3-page ui3-stack ui3-gap-5 promotions-3d-page" data-ui-version="v3" data-ui3-screen="promocoes">
      <header class="promotions-3d-hero">
        <div>
          <span class="promotions-3d-kicker">${renderUiIcon("cupom")} Promoções relâmpago</span>
          <h1>Encontre bons preços sem procurar por horas</h1>
          <p>Até 60 ofertas recentes de impressoras, filamentos, resinas e materiais em diversas lojas brasileiras.</p>
        </div>
        <div class="promotions-3d-hero-actions">
          <button class="btn secondary promotion-alert-button ${alertsEnabled ? "active" : ""}" type="button" aria-pressed="${alertsEnabled}" onclick="alternarAvisosPromocoes3d()">
            ${renderUiIcon(alertsEnabled ? "bell" : "bell")} ${alertsEnabled ? "Avisos ativados" : "Avisar sobre novas ofertas"}
          </button>
          <button class="btn promotion-refresh-button" type="button" onclick="carregarPromocoes3d({ force: true, userRequested: true })">
            ${renderUiIcon("refresh")} Atualizar ofertas
          </button>
        </div>
      </header>

      <section class="promotions-3d-search-card card">
        <div class="promotions-3d-search-row">
          <label class="promotions-3d-search">
            <span class="search-lens-icon" aria-hidden="true">${renderUiIcon("search")}</span>
            <input type="search" aria-label="Pesquisar promoções" value="${escaparAttr(promotions3dState.query)}" placeholder="Ex.: filamento PLA, resina ou impressora" oninput="pesquisarPromocoes3d(this.value)">
          </label>
          <button class="promotions-3d-filter-toggle" type="button" aria-label="Abrir filtros e monitor" aria-expanded="false" aria-controls="promotions3dFilterPanel" onclick="alternarPainelFiltrosPromocoes3d(this)">
            ${renderUiIcon("filtro")}
          </button>
        </div>
        <div class="promotions-3d-filter-panel" id="promotions3dFilterPanel">
          <div class="promotions-3d-filters" role="group" aria-label="Filtrar promoções">
            ${[
              ["todas", "Todas"],
              ["impressoras", "Impressoras"],
              ["filamentos", "Filamentos"],
              ["resinas", "Resinas"],
              ["materiais", "Materiais"]
            ].map(([value, label]) => `
              <button class="promotion-filter-button ${promotions3dState.filter === value ? "active" : ""}" type="button" aria-pressed="${promotions3dState.filter === value}" onclick="filtrarPromocoes3d('${value}')">${label}</button>
            `).join("")}
          </div>
          <div class="promotions-3d-selects">
            <label>
              <span>Loja</span>
              <select class="promotions-store-filter" onchange="filtrarLojaPromocoes3d(this.value)">
                ${renderOpcoesLojasPromocoes3d()}
              </select>
            </label>
            <label>
              <span>Organizar</span>
              <select onchange="ordenarPromocoes3d(this.value)">
                <option value="recentes" ${promotions3dState.sort === "recentes" ? "selected" : ""}>Mais recentes</option>
                <option value="melhores" ${promotions3dState.sort === "melhores" ? "selected" : ""}>Melhores ofertas</option>
                <option value="maior-desconto" ${promotions3dState.sort === "maior-desconto" ? "selected" : ""}>Maior desconto</option>
                <option value="menor-preco" ${promotions3dState.sort === "menor-preco" ? "selected" : ""}>Menor preço</option>
              </select>
            </label>
            <label>
              <span>Desconto mínimo</span>
              <select class="promotions-discount-filter" onchange="filtrarDescontoPromocoes3d(this.value)">
                ${[0, 10, 20, 30, 40, 50].map((value) => `
                  <option value="${value}" ${promotions3dState.discountMin === value ? "selected" : ""}>${value ? `${value}% ou mais` : "Todos"}</option>
                `).join("")}
              </select>
            </label>
            <small class="promotions-updated-label">Busca automática ativa • atualização a cada 5 minutos</small>
          </div>
          <div id="promocoes3dMonitor">
            ${renderPainelMonitorPromocoes3d()}
          </div>
        </div>
      </section>

      <div id="promocoes3dResultado">
        ${renderResultadosPromocoes3d()}
      </div>

      <footer class="promotions-3d-note">
        ${renderUiIcon("seguranca")}
        <p><strong>Somente lojas oficiais.</strong> Preços e estoque podem mudar; confirme tudo antes de comprar.</p>
      </footer>
    </section>
  `;
}

function alternarPainelFiltrosPromocoes3d(button) {
  const panel = document.getElementById("promotions3dFilterPanel");
  if (!panel) return;
  const open = panel.classList.toggle("is-open");
  if (button) {
    button.setAttribute("aria-expanded", String(open));
    button.setAttribute("aria-label", open ? "Fechar filtros e monitor" : "Abrir filtros e monitor");
  }
}

function atualizarResultadosPromocoes3d() {
  const root = document.getElementById("promocoes3dResultado");
  if (root) root.innerHTML = renderResultadosPromocoes3d();
  const storeSelect = document.querySelector(".promotions-store-filter");
  if (storeSelect) storeSelect.innerHTML = renderOpcoesLojasPromocoes3d();
  const updatedLabel = document.querySelector(".promotions-updated-label");
  if (updatedLabel) updatedLabel.textContent = promotions3dState.status === "loading"
    ? "Atualizando ofertas..."
    : `${formatarAtualizacaoPromocoes3d()} • nova busca em 5 minutos`;
  const refreshButton = document.querySelector(".promotion-refresh-button");
  if (refreshButton) {
    refreshButton.disabled = promotions3dState.status === "loading";
    refreshButton.innerHTML = `${renderUiIcon("refresh")} ${promotions3dState.status === "loading" ? "Atualizando..." : "Atualizar ofertas"}`;
  }
  atualizarIndicadoresMenuPromocoes3d();
}

function atualizarPainelMonitorPromocoes3d() {
  const root = document.getElementById("promocoes3dMonitor");
  if (root) root.innerHTML = renderPainelMonitorPromocoes3d();
}

function agendarAtualizacaoPromocoes3d() {
  if (promotions3dRefreshTimer) clearTimeout(promotions3dRefreshTimer);
  promotions3dRefreshTimer = setTimeout(() => {
    if (!estaOnline()) {
      agendarAtualizacaoPromocoes3d();
      return;
    }
    carregarPromocoes3d({ force: true, background: true });
  }, PROMOTIONS_3D_REFRESH_MS);
}

function iniciarMonitorPromocoes3d() {
  carregarMonitorPromocoes3d();
  atualizarIndicadoresMenuPromocoes3d();
  setTimeout(() => {
    if ((getUsuarioAtual() || adminLogado) && estaOnline()) {
      carregarPromocoes3d({ force: true, background: true });
      return;
    }
    agendarAtualizacaoPromocoes3d();
  }, 2600);
}

function monitorPromocoes3dPrecisaAtualizar() {
  const lastChecked = Date.parse(promotions3dMonitorState.lastCheckedAt || promotions3dState.updatedAt || "");
  return !Number.isFinite(lastChecked) || Date.now() - lastChecked >= PROMOTIONS_3D_REFRESH_MS;
}

function criarAssinaturaVisualPromocoes3d(items = []) {
  return JSON.stringify(items.map((item) => [
    item.id,
    item.title,
    item.currentPrice,
    item.originalPrice,
    item.pixPrice,
    item.discount,
    item.image,
    item.url,
    item.expiresAt
  ]));
}

async function carregarPromocoes3d({ force = false, userRequested = false, background = false } = {}) {
  if (promotions3dState.status === "loading") return;
  if (!promotions3dState.items.length) carregarCachePromocoes3d();
  const tinhaOfertas = promotions3dState.items.length > 0;
  const assinaturaAnterior = criarAssinaturaVisualPromocoes3d(promotions3dState.items);
  const assinaturaMonitorAnterior = JSON.stringify({
    watches: promotions3dMonitorState.watches,
    unreadIds: promotions3dMonitorState.unreadIds
  });
  promotions3dState.status = "loading";
  promotions3dState.message = "";
  if (!tinhaOfertas) {
    atualizarResultadosPromocoes3d();
  } else if (!background) {
    const refreshButton = document.querySelector(".promotion-refresh-button");
    if (refreshButton) {
      refreshButton.disabled = true;
      refreshButton.innerHTML = `${renderUiIcon("refresh")} Atualizando...`;
    }
  }
  try {
    const separator = PROMOTIONS_3D_API_URL.includes("?") ? "&" : "?";
    const url = force ? `${PROMOTIONS_3D_API_URL}${separator}t=${Date.now()}` : PROMOTIONS_3D_API_URL;
    const response = await fetch(url, { headers: { accept: "application/json" } });
    if (!response.ok) throw new Error("OFFERS_UNAVAILABLE");
    const payload = await response.json();
    const items = (Array.isArray(payload?.offers) ? payload.offers : []).map(normalizarPromocao3d).filter(Boolean);
    if (!payload?.ok || !items.length) throw new Error("NO_ACTIVE_OFFERS");
    promotions3dState.items = items;
    promotions3dState.stores = Array.isArray(payload.stores) ? payload.stores : [];
    promotions3dState.updatedAt = String(payload.updatedAt || new Date().toISOString());
    promotions3dState.status = "ready";
    salvarCachePromocoes3d();
    processarMonitorPromocoes3d(items);
    const ofertasMudaram = assinaturaAnterior !== criarAssinaturaVisualPromocoes3d(items);
    if (!tinhaOfertas || ofertasMudaram) {
      atualizarResultadosPromocoes3d();
    } else {
      const updatedLabel = document.querySelector(".promotions-updated-label");
      if (updatedLabel) updatedLabel.textContent = `${formatarAtualizacaoPromocoes3d()} • nova busca em 5 minutos`;
    }
    const monitorMudou = assinaturaMonitorAnterior !== JSON.stringify({
      watches: promotions3dMonitorState.watches,
      unreadIds: promotions3dMonitorState.unreadIds
    });
    if (!tinhaOfertas || monitorMudou) atualizarPainelMonitorPromocoes3d();
    if (!background && !ofertasMudaram) {
      const refreshButton = document.querySelector(".promotion-refresh-button");
      if (refreshButton) {
        refreshButton.disabled = false;
        refreshButton.innerHTML = `${renderUiIcon("refresh")} Atualizar ofertas`;
      }
    }
    if (userRequested) {
      mostrarToast("Ofertas atualizadas.", "sucesso", 2400);
    }
  } catch {
    promotions3dState.status = promotions3dState.items.length ? "ready" : "error";
    promotions3dState.message = "Não foi possível atualizar agora. Tente novamente em alguns minutos.";
    if (!tinhaOfertas) {
      atualizarResultadosPromocoes3d();
    } else if (!background) {
      const refreshButton = document.querySelector(".promotion-refresh-button");
      if (refreshButton) {
        refreshButton.disabled = false;
        refreshButton.innerHTML = `${renderUiIcon("refresh")} Atualizar ofertas`;
      }
    }
    if (userRequested || (!background && !promotions3dState.items.length)) {
      mostrarToast(promotions3dState.message, "aviso", 4200);
    }
  } finally {
    agendarAtualizacaoPromocoes3d();
  }
}

function pesquisarPromocoes3d(value = "") {
  promotions3dState.query = String(value || "").slice(0, 80);
  atualizarResultadosPromocoes3d();
  atualizarPainelMonitorPromocoes3d();
}

function filtrarPromocoes3d(category = "todas") {
  promotions3dState.filter = ["todas", "impressoras", "filamentos", "resinas", "materiais"].includes(category) ? category : "todas";
  document.querySelectorAll(".promotion-filter-button").forEach((button) => {
    const active = button.getAttribute("onclick")?.includes(`'${promotions3dState.filter}'`);
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  atualizarResultadosPromocoes3d();
}
function filtrarLojaPromocoes3d(host = "todas") {
  return window.SimplificaStorefrontAdminRender.filtrarLojaPromocoes3d(host, getStorefrontAdminRenderDeps());
}


function ordenarPromocoes3d(sort = "recentes") {
  promotions3dState.sort = ["recentes", "melhores", "maior-desconto", "menor-preco"].includes(sort) ? sort : "recentes";
  atualizarResultadosPromocoes3d();
}

function filtrarDescontoPromocoes3d(value = 0) {
  const discount = Number(value);
  promotions3dState.discountMin = [0, 10, 20, 30, 40, 50].includes(discount) ? discount : 0;
  atualizarResultadosPromocoes3d();
}

function limparFiltrosPromocoes3d() {
  promotions3dState.query = "";
  promotions3dState.filter = "todas";
  promotions3dState.store = "todas";
  promotions3dState.discountMin = 0;
  promotions3dState.sort = "recentes";
  const search = document.querySelector(".promotions-3d-search input");
  if (search) search.value = "";
  const store = document.querySelector(".promotions-store-filter");
  if (store) store.value = "todas";
  const discount = document.querySelector(".promotions-discount-filter");
  if (discount) discount.value = "0";
  filtrarPromocoes3d("todas");
}

async function alternarAvisosPromocoes3d() {
  const enabled = !lerPreferenciaAvisosPromocoes3d();
  let externalAllowed = false;
  if (enabled && typeof Notification !== "undefined") {
    try {
      const permission = Notification.permission === "default"
        ? await Notification.requestPermission()
        : Notification.permission;
      externalAllowed = permission === "granted";
    } catch {}
  }
  try {
    localStorage.setItem(PROMOTIONS_3D_ALERTS_KEY, enabled ? "true" : "false");
  } catch {}
  const button = document.querySelector(".promotion-alert-button");
  if (button) {
    button.classList.toggle("active", enabled);
    button.setAttribute("aria-pressed", enabled ? "true" : "false");
    button.innerHTML = `${renderUiIcon("bell")} ${enabled ? "Avisos ativados" : "Avisar sobre novas ofertas"}`;
  }
  if (!enabled) {
    mostrarToast("Avisos de novas ofertas desativados.", "info", 3000);
  } else if (externalAllowed) {
    mostrarToast("Avisos de novas ofertas ativados neste aparelho.", "sucesso", 3400);
  } else {
    mostrarToast("Avisos na guia ativados. O aparelho não permitiu alertas fora do app.", "info", 4200);
  }
}

