function getOperationalNotificationSeenKey() {
  return `simplifica-operational-notifications-seen:${getStorefrontScopedOwnerId()}`;
}

function getOperationalNotificationSignature(item = {}) {
  return [
    item.id || "notification",
    Number(item.count) || 1,
    item.title || "",
    item.description || ""
  ].join("|");
}

function getSeenOperationalNotifications() {
  try {
    const parsed = JSON.parse(localStorage.getItem(getOperationalNotificationSeenKey()) || "[]");
    return new Set(Array.isArray(parsed) ? parsed.map(String) : []);
  } catch (_) {
    return new Set();
  }
}

function markOperationalNotificationsSeen(notificacoes = getOperationalNotifications()) {
  const signatures = notificacoes.map(getOperationalNotificationSignature).filter(Boolean);
  try {
    localStorage.setItem(getOperationalNotificationSeenKey(), JSON.stringify(signatures.slice(0, 80)));
  } catch (_) {}
  atualizarMenu();
}

function getOperationalNotifications() {
  const atrasados = getPedidosAtrasadosDashboard();
  const materiais = normalizarEstoque().filter((material) => ["low", "critical"].includes(material.stock_status));
  const leadsLoja = getStorefrontPreviewLeadsLocal()
    .filter((lead) => String(lead.status || "novo") === "novo")
    .slice(0, 9);
  const notificacoes = [];
  if (leadsLoja.length) {
    notificacoes.push({
      id: "storefront-orders",
      count: leadsLoja.length,
      tone: "info",
      icon: "lojaOnline",
      title: `${leadsLoja.length} pedido${leadsLoja.length === 1 ? "" : "s"} da loja aguardando`,
      description: leadsLoja.slice(0, 3).map((lead) => lead.customer_name || "Cliente da loja").join(", "),
      action: "fecharPopup();trocarTela('lojaAdmin')",
      actionLabel: "Abrir loja"
    });
  }
  if (atrasados.length) {
    notificacoes.push({
      id: "late-orders",
      tone: "danger",
      icon: "pedidos",
      title: `${atrasados.length} pedido${atrasados.length === 1 ? " atrasado" : "s atrasados"}`,
      description: "Revise os prazos e atualize a produção ou a entrega.",
      action: "fecharPopup();window.__pedidosFiltroDashboard='atrasados';trocarTela('pedidos')",
      actionLabel: "Ver pedidos"
    });
  }
  const criticos = materiais.filter((material) => material.stock_status === "critical");
  const baixos = materiais.filter((material) => material.stock_status === "low");
  if (criticos.length) {
    notificacoes.push({
      id: "critical-stock",
      tone: "danger",
      icon: "estoque",
      title: `${criticos.length} material${criticos.length === 1 ? " em nível crítico" : "ais em nível crítico"}`,
      description: criticos.slice(0, 3).map((item) => item.nome).join(", "),
      action: "fecharPopup();trocarTela('estoque')",
      actionLabel: "Abrir estoque"
    });
  }
  if (baixos.length) {
    notificacoes.push({
      id: "low-stock",
      tone: "warning",
      icon: "estoque",
      title: `${baixos.length} material${baixos.length === 1 ? " com estoque baixo" : "ais com estoque baixo"}`,
      description: baixos.slice(0, 3).map((item) => item.nome).join(", "),
      action: "fecharPopup();trocarTela('estoque')",
      actionLabel: "Conferir"
    });
  }
  if (pendingSync.length) {
    notificacoes.push({
      id: "pending-sync",
      tone: "warning",
      icon: "backup",
      title: `${pendingSync.length} alteração${pendingSync.length === 1 ? " aguardando" : "ões aguardando"} envio`,
      description: "Os dados continuam salvos neste aparelho e serão enviados quando houver conexão.",
      action: "fecharPopup();trocarTela('config')",
      actionLabel: "Ver sincronização"
    });
  }
  return notificacoes;
}

function renderDashboardCommunicationActions() {
  const vistos = getSeenOperationalNotifications();
  const total = getOperationalNotifications()
    .filter((item) => !vistos.has(getOperationalNotificationSignature(item)))
    .reduce((soma, item) => soma + (Number(item.count) || 1), 0);
  return `
    <button class="icon-button dashboard-notification-button" type="button" onclick="abrirNotificacoesOperacionais()" title="Notificações do sistema" aria-label="Abrir notificações do sistema">${renderUiIcon("bell")}${total ? `<span class="notification-count">${Math.min(total, 9)}</span>` : ""}</button>
  `;
}

async function abrirNotificacoesOperacionais() {
  await sincronizarLojaOnlineAdminRemoto(false).catch(() => {});
  const notificacoes = getOperationalNotifications();
  markOperationalNotificationsSeen(notificacoes);
  window.UiV3?.Dialog?.({ title: "Notificações", content: `
        <div class="ui3-settings-list ui3-notification-list">
          ${notificacoes.map((item) => `
            <article class="ui3-settings-row tone-${escaparAttr(item.tone)}">
              <span class="ui3-settings-row__icon">${renderUiIcon(item.icon)}</span>
              <div><strong>${escaparHtml(item.title)}</strong><small>${escaparHtml(item.description)}</small></div>
              <button class="ui3-button" data-variant="secondary" type="button" onclick="window.UiV3.closeOverlay();${item.action.replace(/fecharPopup\(\);?/g, "")}">${escaparHtml(item.actionLabel)}</button>
            </article>
          `).join("") || `<div class="ui3-state">${renderUiIcon("bell")}<strong>Tudo em dia</strong></div>`}
        </div>
  ` });
}

