async function salvarCategoriaLojaOnline(event) {
  event?.preventDefault?.();
  const form = event?.target;
  let shouldRestoreCatalog = false;
  if (!storefrontBeginOperation("storefront-category-save")) return;
  const botao = form?.querySelector?.("button[type='submit']");
  setBotaoLoading(botao, true, "Salvando...");
  const store = getStorefrontAdminStoreLocal();
  const categories = getStorefrontAdminCategoriesLocal();
  try {
    const id = form?.categoryId?.value || "";
    const name = form?.categoryName?.value?.trim();
    if (!name) throw new Error("Informe o nome da categoria.");
    const slug = storefrontAdminSlugify(form?.categorySlug?.value || name);
    if (categories.some((cat) => !cat.__demo && !cat.__template && cat.slug === slug && cat.id !== id)) throw new Error("Já existe categoria com este nome.");
    let nextCategory = {
      id: id || `cat-${Date.now()}`,
      store_id: store.id,
      owner_id: store.owner_id || storefrontAdminCurrentOwnerId(),
      name,
      slug,
      icon: form?.categoryIcon?.value?.trim() || "",
      order_index: Number(form?.categoryOrder?.value || categories.length + 1),
      visible: !!form?.categoryVisible?.checked
    };
    let next = id ? categories.map((cat) => cat.id === id ? { ...cat, ...nextCategory } : cat) : [...categories, nextCategory];
    storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.categories, next);
    let syncPending = false;
    if (storefrontAdminRemoteReady()) {
      try {
        storefrontAdminRequireRemoteStore();
        nextCategory = await storefrontAdminUpsertCategory(nextCategory);
        next = id ? next.map((cat) => String(cat.id) === String(id) ? { ...cat, ...nextCategory } : cat) : next.map((cat) => String(cat.id) === String(nextCategory.id) || String(cat.slug) === String(nextCategory.slug) ? { ...cat, ...nextCategory } : cat);
        storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.categories, next);
      } catch (syncError) {
        syncPending = true;
        storefrontQueuePendingAction("category-upsert", nextCategory);
        registrarStorefrontDebugLeve("persistencia_falhou", "Categoria salva localmente e aguardando sincronização.", { message: syncError?.message || String(syncError) });
      }
    } else {
      syncPending = true;
      storefrontQueuePendingAction("category-upsert", nextCategory);
    }
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingCategory);
    limparStorefrontAlteracoesPendentes(syncPending ? "Categoria salva; atualização online automática" : "Categoria salva");
    if (telaAtual === "lojaPublica" && (isMobile() || isWebPwaProfile())) {
      shouldRestoreCatalog = true;
      returnToStorefrontGuidedCatalog("categories", {
        highlightId: String(nextCategory.id || ""),
        source: "guided-category-save"
      });
    } else {
      storefrontGuidedSelection = { type: "category", id: String(nextCategory.id || "") };
    }
    registrarStorefrontActivity(id ? "Categoria atualizada" : "Categoria criada", nextCategory.name);
    if (syncPending) confirmarStorefrontSalvamentoLocal("Categoria salva neste aparelho.");
    else mostrarToast("Categoria salva.", "sucesso", 3200);
    renderApp();
    if (shouldRestoreCatalog) restoreStorefrontGuidedCatalogState("categories");
    concluirNavegacaoPendenteLoja();
  } catch (error) {
    mostrarToast("Não foi possível salvar a categoria agora.", "erro", 4200);
    registrarStorefrontDebugLeve("save_falhou", "Falha ao salvar categoria da loja.", { message: error?.message || String(error) });
    console.error("[Storefront admin] salvar categoria", error);
  } finally {
    setBotaoLoading(botao, false);
    storefrontEndOperation("storefront-category-save");
  }
}
