function abrirEditorProdutoLojaOnline(id = "") {
  storefrontProductMobileStep = 1;
  const limits = getStorefrontLimitsLocal(getPlanoAtual()?.slug);
  if (Number.isFinite(limits.productLimit) && limits.productLimit <= 0) {
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProduct);
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProductSeed);
    setStorefrontAdminTab("products");
    mostrarToast("Produtos da loja online ficam disponíveis no Start ou Pro.", "info", 4200);
    return;
  }
  if (id) {
    const product = getStorefrontAdminProductsLocal().find((item) => String(item.id) === String(id));
    if (product?.__demo || product?.__template) {
      if (!window.confirm("Usar este exemplo como modelo? Revise foto, nome, descrição e preço antes de salvar. O produto será criado como rascunho e não será publicado automaticamente.")) return;
      const seed = {
        ...product,
        id: "",
        slug: "",
        category_id: null,
        image_url: "",
        visible: false,
        __demo: false,
        __template: false,
        public_observations: ""
      };
      storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.editingProductSeed, seed);
      storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProduct);
      mostrarToast("Modelo carregado como rascunho. Revise foto, nome, descrição e preço.", "info", 4200);
    } else {
      storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.editingProduct, id);
      storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProductSeed);
    }
  } else {
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProduct);
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProductSeed);
  }
  setStorefrontAdminTab("products");
}

function cancelarEdicaoProdutoLojaOnline() {
  storefrontProductMobileStep = 1;
  storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProduct);
  storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProductSeed);
  mostrarToast("Edição do produto cancelada.", "info", 2200);
  renderApp();
}

async function salvarProdutoLojaOnline(event) {
  event?.preventDefault?.();
  const form = event?.target;
  const botao = form?.querySelector?.("button[type='submit']");
  const store = getStorefrontAdminStoreLocal();
  const products = getStorefrontAdminProductsLocal();
  let shouldRestoreCatalog = false;
  let operacaoUX = "";
  if (isStorefrontProductMobileFlow() && !validarTodasEtapasProdutoLojaOnline(form)) return;
  if (!storefrontBeginOperation("storefront-product-save")) return;
  try {
    const id = getStorefrontProductFormField(form, "productId")?.value || "";
    const templateSourceId = getStorefrontProductFormField(form, "productTemplateSourceId")?.value || "";
    const title = validarTextoVisualLoja(getStorefrontProductFormField(form, "productTitle")?.value, 60, "nome do produto");
    if (!title) throw new Error("Informe o título público do produto.");
    const shortDescription = validarTextoVisualLoja(getStorefrontProductFormField(form, "productShortDescription")?.value, 100, "descrição curta");
    const description = validarTextoVisualLoja(getStorefrontProductFormField(form, "productDescription")?.value, 180, "descrição");
    const slug = storefrontAdminSlugify(getStorefrontProductFormField(form, "productSlug")?.value || title);
    if (products.some((product) => !storefrontIsDemoProduct(product) && product.slug === slug && product.id !== id)) throw new Error("Já existe produto com este nome.");
    const limits = getStorefrontLimitsLocal(getPlanoAtual()?.slug);
    if (!id && Number.isFinite(limits.productLimit) && limits.productLimit <= 0) throw new Error("Produtos da loja online ficam disponíveis no Start ou Pro.");
    if (!id && products.length >= limits.productLimit) throw new Error(`Limite de ${limits.productLimit} produto(s) para este plano.`);
    const selectedPriceMode = getStorefrontProductFormField(form, "productPriceMode")?.value || "fixed";
    const price = Math.max(0, Number(String(getStorefrontProductFormField(form, "productPrice")?.value || "0").replace(",", ".")) || 0);
    const compare = Math.max(0, Number(String(getStorefrontProductFormField(form, "productComparePrice")?.value || "0").replace(",", ".")) || 0);
    if (selectedPriceMode === "promo" && compare <= price) throw new Error("O preço anterior deve ser maior que o preço atual.");
    const priceMode = selectedPriceMode === "quote" ? "quote" : compare > price ? "promo" : "fixed";
    const selectedStockMode = getStorefrontProductFormField(form, "productStockMode")?.value || "unlimited";
    const stockMode = ["unlimited", "manual", "unavailable"].includes(selectedStockMode) ? selectedStockMode : "unlimited";
    const stockQuantityValue = getStorefrontProductFormField(form, "productStockQuantity")?.value;
    if (priceMode !== "quote" && price <= 0) throw new Error("Informe um preço válido.");
    let nextProduct = {
      id: id || `prod-${Date.now()}`,
      store_id: store.id,
      owner_id: store.owner_id || storefrontAdminCurrentOwnerId(),
      erp_product_id: getStorefrontProductFormField(form, "erpProductId")?.value?.trim() || null,
      title,
      short_description: shortDescription,
      slug,
      description,
      price,
      compare_price: priceMode === "promo" && compare > price ? compare : null,
      price_mode: priceMode,
      show_price: priceMode !== "quote",
      category_id: templateSourceId ? null : (getStorefrontProductFormField(form, "productCategory")?.value || null),
      visible: !!getStorefrontProductFormField(form, "productVisible")?.checked,
      featured: !!getStorefrontProductFormField(form, "productFeatured")?.checked,
      is_customizable: !!getStorefrontProductFormField(form, "productCustomizable")?.checked,
      estimated_production_time: getStorefrontProductFormField(form, "productTime")?.value?.trim() || "",
      public_observations: getStorefrontProductFormField(form, "productObservations")?.value?.trim() || "",
      stock_mode: stockMode,
      stock_quantity: stockMode === "manual" && stockQuantityValue !== "" ? Math.max(0, Number(stockQuantityValue) || 0) : null
    };
    if (!await requestSensitiveActionConfirmation({
      actionLabel: id ? "editar produto, preço ou publicação da loja" : "criar produto na loja",
      titulo: id ? "Autorizar alteração de produto" : "Autorizar novo produto",
      mensagem: id
        ? "Confirme sua senha antes de alterar preço, visibilidade, destaque ou dados públicos do produto."
        : "Confirme sua senha antes de criar um produto público na loja.",
      confirmar: "Autorizar produto",
      cancelar: "Cancelar",
      exigirConfirmacaoVisual: true
    })) return;
    setBotaoLoading(botao, true, "Salvando...");
    operacaoUX = iniciarOperacaoUX({
      name: "save-storefront-product",
      title: "Salvando produto",
      message: "Validando informações...",
      context: "loja-produtos",
      steps: ["Validando dados", "Salvando produto", "Atualizando catálogo", "Finalizando"],
      progress: 15
    });
    let next = id ? products.map((product) => product.id === id ? { ...product, ...nextProduct } : product) : [...products, nextProduct];
    storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.products, next);
    atualizarOperacaoUX(operacaoUX, { stepIndex: 1, message: "Salvando produto...", progress: 40 });
    let syncPending = false;
    if (storefrontAdminRemoteReady()) {
      try {
        storefrontAdminRequireRemoteStore();
        atualizarOperacaoUX(operacaoUX, { stepIndex: 2, message: "Atualizando catálogo online...", progress: 70 });
        nextProduct = await storefrontAdminUpsertProduct(nextProduct);
        next = id ? next.map((product) => String(product.id) === String(id) ? { ...product, ...nextProduct } : product) : next.map((product) => String(product.id) === String(nextProduct.id) || String(product.slug) === String(nextProduct.slug) ? { ...product, ...nextProduct } : product);
        storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.products, next);
      } catch (syncError) {
        syncPending = true;
        storefrontQueuePendingAction("product-upsert", nextProduct);
        registrarStorefrontDebugLeve("persistencia_falhou", "Produto salvo localmente e aguardando sincronização.", { message: syncError?.message || String(syncError) });
      }
    } else {
      syncPending = true;
      storefrontQueuePendingAction("product-upsert", nextProduct);
    }
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProduct);
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProductSeed);
    limparStorefrontAlteracoesPendentes(syncPending ? "Produto salvo; atualização online automática" : "Produto salvo");
    if (telaAtual === "lojaPublica" && (isMobile() || isWebPwaProfile())) {
      shouldRestoreCatalog = true;
      returnToStorefrontGuidedCatalog("products", {
        highlightId: String(nextProduct.id || ""),
        source: "guided-product-save"
      });
    } else {
      storefrontGuidedSelection = { type: "product", id: String(nextProduct.id || "") };
    }
    registrarStorefrontActivity(id ? "Produto atualizado" : "Produto criado", nextProduct.title);
    if (syncPending) confirmarStorefrontSalvamentoLocal("Produto salvo neste aparelho.");
    else mostrarToast(nextProduct.visible ? "Produto publicado na loja." : "Produto salvo como oculto.", "sucesso", 3400);
    atualizarOperacaoUX(operacaoUX, { stepIndex: 3, message: "Produto salvo.", progress: 100 });
    concluirOperacaoUX(operacaoUX, "Produto salvo");
    renderApp();
    if (shouldRestoreCatalog) restoreStorefrontGuidedCatalogState("products");
    concluirNavegacaoPendenteLoja();
  } catch (error) {
    falharOperacaoUX(operacaoUX, error, "Erro ao salvar");
    mostrarToast("Não foi possível salvar o produto agora.", "erro", 4200);
    registrarStorefrontDebugLeve("save_falhou", "Falha ao salvar produto da loja.", { message: error?.message || String(error) });
    console.error("[Storefront admin] salvar produto", error);
  } finally {
    setBotaoLoading(botao, false);
    storefrontEndOperation("storefront-product-save");
  }
}
