function labelStatusPedido(status = "aberto") {
  const mapa = {
    aberto: "Aberto",
    pendente: "Pendente",
    producao: "Produção",
    produção: "Produção",
    pronto: "Pronto",
    aguardando: "Aguardando",
    pausado: "Aguardando",
    entregue: "Entregue",
    finalizado: "Pago",
    pago: "Pago",
    cancelado: "Cancelado"
  };
  return mapa[String(status || "aberto").toLowerCase()] || String(status || "Aberto");
}

function classeStatusPedido(status = "aberto") {
  const valor = String(status || "aberto").toLowerCase();
  if (["producao", "produção"].includes(valor)) return "order-status-production";
  if (["pronto", "prontos"].includes(valor)) return "order-status-ready";
  if (["entregue"].includes(valor)) return "order-status-delivered";
  if (["aguardando", "pausado"].includes(valor)) return "order-status-waiting";
  if (["pago", "finalizado"].includes(valor)) return "order-status-paid";
  if (valor === "cancelado") return "order-status-cancelled";
  return "order-status-open";
}

function normalizarStatusPedidoFiltro(pedido = {}) {
  const status = String(pedido.status || "aberto").toLowerCase();
  if (pedidoJaCancelado(pedido) || status === "cancelado") return "cancelados";
  if (["pago", "finalizado"].includes(status)) return "pagos";
  if (status === "entregue") return "entregues";
  if (["pronto", "prontos"].includes(status)) return "prontos";
  if (["producao", "produção"].includes(status)) return "producao";
  return "pendentes";
}

function garantirNumeracaoSequencialPedidos(lista = pedidos) {
  const registros = (Array.isArray(lista) ? lista : []).filter(Boolean);
  // Existing numbers need no allocation or chronological sorting on each card render.
  if (registros.every((pedido) => Math.floor(Number(pedido.numeroPedido || pedido.numero_pedido) || 0) > 0)) {
    return registros;
  }
  const usados = new Set(registros
    .map((pedido) => Math.floor(Number(pedido.numeroPedido || pedido.numero_pedido) || 0))
    .filter((numero) => numero > 0));
  let proximo = 1;
  [...registros]
    .sort((a, b) => {
      const dataA = Date.parse(a.criadoEm || a.createdAt || a.created_at || 0) || Number(a.id) || 0;
      const dataB = Date.parse(b.criadoEm || b.createdAt || b.created_at || 0) || Number(b.id) || 0;
      return dataA - dataB;
    })
    .forEach((pedido) => {
      const atual = Math.floor(Number(pedido.numeroPedido || pedido.numero_pedido) || 0);
      if (atual > 0) return;
      while (usados.has(proximo)) proximo += 1;
      pedido.numeroPedido = proximo;
      pedido.numero_pedido = proximo;
      usados.add(proximo);
      proximo += 1;
    });
  return registros;
}

function getNumeroSequencialPedido(pedido = {}) {
  garantirNumeracaoSequencialPedidos();
  return Math.max(1, Math.floor(Number(pedido.numeroPedido || pedido.numero_pedido) || 1));
}

function encontrarPedidoPorId(id) {
  return pedidos.find((pedido) => String(pedido?.id ?? "") === String(id ?? "")) || null;
}

function getProximoNumeroSequencialPedido() {
  garantirNumeracaoSequencialPedidos();
  return pedidos.reduce((maior, pedido) => Math.max(maior, Number(pedido.numeroPedido || pedido.numero_pedido) || 0), 0) + 1;
}

function pedidoEhHoje(pedido = {}) {
  return dataPedidoIso(pedido) === hojeIsoData();
}

function pedidoEstaAtrasado(pedido = {}) {
  const status = normalizarStatusPedidoFiltro(pedido);
  if (["entregues", "pagos", "cancelados"].includes(status)) return false;
  const prazo = String(pedido.prazo || pedido.dataPrazo || "").trim();
  if (!prazo) return false;
  return prazo < hojeIsoData();
}

