async function abrirEtapasPedido(id) {
  const pedido = encontrarPedidoPorId(id);
  if (!pedido || pedidoJaCancelado(pedido)) return;
  const escolha = await solicitarEscolhaPedido({
    titulo: `Etapas do pedido ${getNumeroSequencialPedido(pedido)}`,
    mensagem: `Etapa atual: ${labelStatusPedido(pedido.status || "aberto")}. Escolha a atualização desejada. Valores e cobranças ficam em Financeiro.`,
    opcoes: [
      { id: "producao", label: "Liberar para produção", classe: "secondary" },
      { id: "pronto", label: "Marcar como pronto", classe: "ghost" },
      { id: "entregue", label: "Marcar como entregue", classe: "ghost" },
      { id: "pago", label: "Marcar status como pago", classe: "ghost" },
      { id: "financeiro", label: "Financeiro e cobrança", classe: "ghost" }
    ]
  });
  // Re-read after the dialog: the order may have been cancelled or removed meanwhile.
  const atual = encontrarPedidoPorId(id);
  if (!atual || pedidoJaCancelado(atual)) return;
  if (escolha === "producao") return abrirLiberacaoProducao(id);
  if (escolha === "financeiro") return abrirFinanceiroPedido(id);
  if (["pronto", "entregue", "pago"].includes(escolha)) return alterarStatusPedido(id, escolha);
}

async function abrirMaisOpcoesPedido(id) {
  const pedido = encontrarPedidoPorId(id);
  if (!pedido) return;
  const cancelado = pedidoJaCancelado(pedido);
  const escolha = await solicitarEscolhaPedido({
    titulo: `Pedido ${getNumeroSequencialPedido(pedido)}`,
    mensagem: cancelado
      ? "Pedido cancelado. A área financeira está disponível somente para consulta."
      : "Opções adicionais do pedido.",
    opcoes: [
      { id: "copiar", label: "Copiar orçamento", classe: "ghost", icone: "▣" },
      { id: "financeiro", label: cancelado ? "Resumo financeiro" : "Financeiro e cobrança", classe: "secondary", icone: "pix" },
      ...(!cancelado ? [{ id: "excluir", label: "Cancelar pedido", classe: "danger", icone: "🗑" }] : [])
    ]
  });
  if (escolha === "copiar") copiarOrcamentoPedidoSalvo(id);
  if (escolha === "financeiro") abrirFinanceiroPedido(id);
  if (escolha === "excluir") removerPedido(id);
}

function duplicarPedidoSalvo(id) {
  mostrarToast("Duplicar pedido foi desativado para evitar pedidos repetidos. Use edição de quantidade nos itens.", "info", 4200);
}

async function abrirFinanceiroPedido(id) {
  const pedido = encontrarPedidoPorId(id);
  if (!pedido) return mostrarToast("Pedido não encontrado.", "erro");
  const cancelado = pedidoJaCancelado(pedido);
  const resumo = calcularResumoFinanceiroPedido(pedido);
  if (cancelado) {
    await solicitarEscolhaPedido({
      titulo: `Resumo financeiro do pedido ${getNumeroSequencialPedido(pedido)}`,
      mensagem: `Pedido cancelado • Total ${formatarMoeda(resumo.total)} • Entrada ${formatarMoeda(resumo.entrada)} • Restante ${formatarMoeda(resumo.restante)}. Novas cobranças estão desativadas.`,
      opcoes: [{ id: "fechar", label: "Fechar resumo", classe: "secondary", icone: "close" }]
    });
    return;
  }
  const escolha = await solicitarEscolhaPedido({
    titulo: `Financeiro do pedido #${getNumeroSequencialPedido(pedido)}`,
    mensagem: `Total ${formatarMoeda(resumo.total)} • Entrada ${formatarMoeda(resumo.entrada)} • Restante ${formatarMoeda(resumo.restante)}`,
    opcoes: [
      { id: "copiar-pix", label: "Copiar cobrança Pix", classe: "secondary", icone: "pix" },
      { id: "whatsapp-pix", label: "Enviar cobrança no WhatsApp", classe: "ghost", icone: "☘" },
      { id: "copiar-completo", label: "Copiar pedido com cobrança", classe: "ghost", icone: "▣" },
      { id: "editar", label: "Editar valores do pedido", classe: "ghost", icone: "✎" }
    ]
  });
  if (escolha === "copiar-pix") copiarCobrancaPixPedido(id);
  if (escolha === "whatsapp-pix") sendQuoteToWhatsApp(pedido, { incluirPix: true, tipo: "pedido" });
  if (escolha === "copiar-completo") copiarCobrancaPixPedido(id, { mensagemCompleta: true });
  if (escolha === "editar") editarPedido(id);
}

async function copiarOrcamentoPedidoSalvo(id) {
  const pedido = encontrarPedidoPorId(id);
  if (!pedido) return;
  const texto = montarMensagemOrcamentoWhatsapp(pedido);
  try {
    await navigator.clipboard?.writeText(texto);
    mostrarToast("Orçamento copiado.", "sucesso", 2400);
  } catch (_) {
    window.prompt("Copie o orçamento:", texto);
  }
}

function solicitarEscolhaPedido({ titulo = "Opções", mensagem = "", opcoes = [] } = {}) {
  return new Promise((resolve) => {
    const popup = document.getElementById("popup");
    if (!popup) {
      resolve("");
      return;
    }
    const fechar = (valor = "") => {
      fecharPopup();
      resolve(valor);
    };
    const nomeCallback = `__pedidoEscolha_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    window[nomeCallback] = (valor) => {
      delete window[nomeCallback];
      fechar(valor);
    };
    popup.innerHTML = `
      <div class="modal-backdrop" role="dialog" aria-modal="true" onclick="${nomeCallback}('')">
        <section class="modal-card order-more-options modal-enter" onclick="event.stopPropagation()">
          <div class="modal-header">
            <h2>${escaparHtml(titulo)}</h2>
            <button class="icon-button" type="button" onclick="${nomeCallback}('')" title="Fechar">✕</button>
          </div>
          ${mensagem ? `<p class="muted">${escaparHtml(mensagem)}</p>` : ""}
          <div class="order-more-grid">
            ${opcoes.map((opcao) => `
              <button class="order-more-action ${escaparAttr(opcao.classe || "ghost")}" type="button" onclick="${nomeCallback}('${escaparAttr(opcao.id)}')">
                <span class="action-symbol" aria-hidden="true">${renderIconeAcaoPedido(opcao.icone || "⋯", opcao.label)}</span>
                <strong>${escaparHtml(opcao.label)}</strong>
              </button>
            `).join("")}
          </div>
        </section>
      </div>
    `;
    promoverPopupParaDialogUiV3(popup, { title: titulo, onClose: () => window[nomeCallback]?.("") });
  });
}

