function getApresentacaoPlanoEmpresaSaas(resumo = {}) {
  const assinatura = resumo.assinatura || {};
  const plano = resumo.plano || getPlanoSaas("free");
  const vencimento = resumo.vencimento || "";
  const vencimentoMs = getTimestampPlano(vencimento);
  const agora = Date.now();
  const data = vencimentoMs ? new Date(vencimentoMs).toLocaleDateString("pt-BR") : "";
  const pago = ["start", "pro"].includes(plano.slug);
  const manual = assinatura.manualOverride === true || assinatura.manual_override === true;

  if (!pago) {
    return {
      titulo: plano.name || "Free",
      detalhe: resumo.acessoVencido ? "Plano anterior encerrado • acesso atual Free" : "Sem vencimento",
      alerta: false
    };
  }

  if (vencimentoMs) {
    const dias = Math.max(0, Math.ceil((vencimentoMs - agora) / 86400000));
    if (vencimentoMs <= agora) {
      return { titulo: `${plano.name} encerrado`, detalhe: `Venceu em ${data} • retorna ao Free`, alerta: true };
    }
    return {
      titulo: `${plano.name} até ${data}`,
      detalhe: `${dias} ${dias === 1 ? "dia restante" : "dias restantes"} • depois volta ao Free`,
      alerta: dias <= 3
    };
  }

  return manual
    ? { titulo: `${plano.name} sem data final`, detalhe: "Acesso manual • definir vencimento", alerta: true }
    : { titulo: `${plano.name} ativo`, detalhe: "Assinatura atual • renovação mensal", alerta: false };
}

function getApresentacaoAtividadeEmpresaSaas(resumo = {}) {
  const ultimoAcesso = resumo.ultimoAcesso || "";
  if (resumo.online) return { titulo: "Online agora", detalhe: "Sessão ativa nos últimos 5 minutos", online: true };
  if (!ultimoAcesso) return { titulo: "Sem acesso registrado", detalhe: "Cliente ainda não utilizou o aplicativo", online: false };
  return {
    titulo: formatarTempoRelativo(ultimoAcesso),
    detalhe: new Date(ultimoAcesso).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" }),
    online: false
  };
}

function renderLinhaClienteSaas(cliente) {
  const resumo = getResumoEmpresaSaas(cliente);
  const assinatura = resumo.assinatura;
  const plano = resumo.plano;
  const usuarioPrincipal = resumo.responsavel;
  const clienteIdAttr = escaparAttr(cliente.id);
  const selecionado = String(window.__clienteSaasSelecionadoId || "") === String(cliente.id);
  const badgeTeste = cliente.isTestUser ? `<span class="status-badge badge-teste">Teste</span>` : "";
  const statusFinanceiro = resumo.statusPlano;
  const apresentacaoPlano = getApresentacaoPlanoEmpresaSaas(resumo);
  const apresentacaoAtividade = getApresentacaoAtividadeEmpresaSaas(resumo);
  const dataCadastro = cliente.createdAt ? new Date(cliente.createdAt).toLocaleDateString("pt-BR") : "-";
  return `
    <div class="client-admin-row ${selecionado ? "selected" : ""}" data-client-row="saas" data-client-id="${clienteIdAttr}" role="button" tabindex="0" aria-selected="${selecionado ? "true" : "false"}" onpointerdown="prepararSelecaoClienteSaas(event, '${clienteIdAttr}')" onpointermove="atualizarMovimentoClienteSaas(event, '${clienteIdAttr}')" onpointercancel="cancelarSelecaoClienteSaas(event, '${clienteIdAttr}')" ontouchstart="prepararSelecaoClienteSaas(event, '${clienteIdAttr}')" ontouchmove="atualizarMovimentoClienteSaas(event, '${clienteIdAttr}')" ontouchcancel="cancelarSelecaoClienteSaas(event, '${clienteIdAttr}')" onclick="selecionarResultadoClienteSaas(event, '${clienteIdAttr}')" onkeydown="acionarClienteSaasPorTeclado(event, '${clienteIdAttr}')">
      <div class="client-admin-main">
        <small>Empresa</small>
        <span class="client-admin-title"><strong>${escaparHtml(cliente.name)}</strong><span class="status-badge ${classeStatusPlano(cliente.status)}">${escaparHtml(rotuloStatusCliente(cliente.status))}</span>${badgeTeste}</span>
        <span class="muted">${escaparHtml(cliente.email)}${cliente.phone ? " • " + escaparHtml(cliente.phone) : ""}</span>
        <span class="muted client-admin-tech">ID ${escaparHtml(cliente.clientCode || cliente.id)} • user_id ${escaparHtml(assinatura?.userId || usuarioPrincipal?.id || "-")}</span>
      </div>
      <div class="client-admin-access ${apresentacaoPlano.alerta ? "needs-attention" : ""}">
        <small>Plano e acesso</small>
        <span><i class="status-badge ${classePlanoSaasCompacto(plano.slug)}">${escaparHtml(plano.name)}</i><strong>${escaparHtml(apresentacaoPlano.titulo)}</strong></span>
        <em>${escaparHtml(apresentacaoPlano.detalhe)}</em>
        <small>${escaparHtml(statusFinanceiro)}${assinatura?.pendingPlan || cliente.pendingPlan ? ` • troca pendente para ${escaparHtml(assinatura?.pendingPlan || cliente.pendingPlan)}` : ""}</small>
      </div>
      <div class="client-meta client-admin-activity">
        <small>Último acesso</small>
        <strong class="${apresentacaoAtividade.online ? "sa-online" : ""}">${escaparHtml(apresentacaoAtividade.titulo)}</strong>
        <span>${escaparHtml(apresentacaoAtividade.detalhe)}</span>
        <span>Cadastro ${escaparHtml(dataCadastro)}</span>
      </div>
      <div class="row-actions">
        <button class="btn ghost" onclick="editarClienteSaas('${clienteIdAttr}')">Editar</button>
        <button class="btn ghost" onclick="alterarPlanoClienteSaas('${clienteIdAttr}')">Plano</button>
        ${renderMenuAcoesSuperadmin(`
          <button class="btn warning" onclick="alterarStatusClienteSaas('${clienteIdAttr}', '${cliente.status === "blocked" ? "active" : "blocked"}')">${cliente.status === "blocked" ? "Reativar empresa" : "Bloquear empresa"}</button>
          <button class="btn ghost" onclick="liberarDiasManualClienteSaas('${clienteIdAttr}')">Adicionar dias ao acesso</button>
          <button class="btn ghost" onclick="alternarUsuarioTesteSaas('${clienteIdAttr}')">${cliente.isTestUser ? "Desativar usuário de teste" : "Marcar como usuário de teste"}</button>
          <button class="btn ghost" onclick="exportarClienteSaas('${clienteIdAttr}')">Exportar dados da empresa</button>
          <button class="btn warning" onclick="arquivarClienteSaas('${clienteIdAttr}')">Arquivar empresa</button>
          <button class="btn danger" onclick="anonimizarClienteSaas('${clienteIdAttr}')">Anonimizar dados pessoais</button>
          ${cliente.isTestUser ? `<button class="btn danger" onclick="excluirUsuarioTesteSaas('${clienteIdAttr}')">Excluir usuário de teste</button>` : ""}
        `, "Mais")}
      </div>
    </div>
  `;
}

function renderPaginacaoClientesSaas(paginaInfo) {
  if (paginaInfo.total <= SUPERADMIN_PAGE_SIZE) return "";
  return `
    <div class="actions pagination-actions">
      <button class="btn ghost" onclick="setPaginaClientesSaas(${paginaInfo.pagina - 1})" ${paginaInfo.pagina <= 1 ? "disabled" : ""}>Anterior</button>
      <span class="muted">Mostrando ${paginaInfo.inicio + 1}-${paginaInfo.fim} de ${paginaInfo.total}</span>
      <button class="btn ghost" onclick="setPaginaClientesSaas(${paginaInfo.pagina + 1})" ${paginaInfo.pagina >= paginaInfo.totalPaginas ? "disabled" : ""}>Próxima</button>
    </div>
  `;
}

function renderListaClientesSaasConteudo(totalClientes) {
  const listaFiltrada = getClientesSaasFiltrados();
  const paginaInfo = getClientesSaasPagina(listaFiltrada);
  const estadoRemoto = renderEstadoClientesSaasRemoto(totalClientes, listaFiltrada.length);
  const vazioFiltro = `<p id="clientesSaasFiltroVazio" class="empty" ${listaFiltrada.length === 0 && totalClientes > 0 ? "" : "hidden"}>Nenhuma empresa corresponde aos filtros atuais.</p>`;
  const linhas = paginaInfo.itens.map(renderLinhaClienteSaas).join("");
  const cabecalho = listaFiltrada.length ? `
    <div class="client-admin-table-head" aria-hidden="true">
      <span>Empresa</span>
      <span>Plano</span>
      <span>Plano e acesso</span>
      <span>Último acesso</span>
      <span>Ações</span>
    </div>
  ` : "";
  return `${estadoRemoto}${cabecalho}${linhas}${vazioFiltro}${renderPaginacaoClientesSaas(paginaInfo)}`;
}

function formatarDataPerfilSaas(valor, fallback = "-") {
  const data = Date.parse(valor || "");
  if (!Number.isFinite(data)) return fallback;
  return new Date(data).toLocaleDateString("pt-BR");
}

function getStatusPlanoClienteSaas(cliente, assinatura) {
  if (!cliente) return "indefinido";
  if (cliente.status === "blocked") return "Bloqueado";
  if (cliente.status === "overdue") return "Atrasado";
  const status = normalizarStatusPlano(assinatura?.status || cliente.statusAssinatura || cliente.subscriptionStatus || cliente.status || "active");
  if (["past_due", "expired", "cancelled"].includes(status)) return "Atrasado";
  return "Em dia";
}

function renderSuperAdminProfileRow(label, value, options = {}) {
  const badge = options.badge ? ` <span class="status-badge ${escaparAttr(options.badgeClass || "")}">${escaparHtml(options.badge)}</span>` : "";
  const action = options.onclick ? ` role="button" tabindex="0" onclick="${options.onclick}" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();${options.onclick}}"` : "";
  const arrow = options.onclick ? `<span class="profile-row-arrow">›</span>` : "";
  return `
    <div class="superadmin-profile-row"${action}>
      <span>${escaparHtml(label)}</span>
      <strong>${escaparHtml(value || "-")}${badge}</strong>
      ${arrow}
    </div>
  `;
}

function getSuperAdminCompanyProfileTabs() {
  return [
    { id: "resumo", label: "Resumo" },
    { id: "assinatura", label: "Assinatura" },
    { id: "limites", label: "Limites" },
    { id: "loja", label: "Loja" },
    { id: "financeiro", label: "Financeiro" },
    { id: "logs", label: "Logs" },
    { id: "suporte", label: "Suporte" }
  ];
}

function normalizarAbaPerfilEmpresaSaas(tab = "resumo") {
  const id = String(tab || "resumo").toLowerCase();
  return getSuperAdminCompanyProfileTabs().some((item) => item.id === id) ? id : "resumo";
}

function trocarAbaPerfilEmpresaSaas(tab) {
  fecharTecladoBuscaClientesSaas();
  window.__superAdminCompanyProfileTab = normalizarAbaPerfilEmpresaSaas(tab);
  renderApp();
}

function renderSuperAdminCompanyTabs(tab = "resumo") {
  const ativa = normalizarAbaPerfilEmpresaSaas(tab);
  return `
    <div class="superadmin-company-tabs" role="tablist" aria-label="Áreas da empresa">
      ${getSuperAdminCompanyProfileTabs().map((item) => `
        <button class="${ativa === item.id ? "active" : ""}" type="button" role="tab" aria-selected="${ativa === item.id ? "true" : "false"}" onclick="trocarAbaPerfilEmpresaSaas('${item.id}')">${escaparHtml(item.label)}</button>
      `).join("")}
    </div>
  `;
}

function renderSuperAdminEmptyCard(titulo, texto) {
  return `
    <div class="superadmin-profile-card superadmin-profile-empty-card">
      <h3>${escaparHtml(titulo)}</h3>
      <p class="empty">${escaparHtml(texto)}</p>
    </div>
  `;
}

function renderSuperAdminCompanyPaymentList(pagamentos = []) {
  if (!pagamentos.length) return renderSuperAdminEmptyCard("Financeiro", "Nenhum pagamento registrado para esta empresa.");
  return `
    <div class="superadmin-profile-card">
      <h3>Pagamentos recentes</h3>
      <div class="superadmin-profile-list">
        ${pagamentos.slice(0, 8).map((pagamento) => `
          <div class="superadmin-profile-list-row">
            <div>
              <strong>${escaparHtml(pagamento.description || pagamento.planSlug || pagamento.planId || "Pagamento")}</strong>
              <span>${escaparHtml(formatarDataPerfilSaas(pagamento.createdAt || pagamento.created_at || pagamento.updatedAt || ""))}</span>
            </div>
            <span class="status-badge ${pagamento.status === "approved" ? "badge-ativo" : pagamento.status === "pending" ? "badge-warning" : "badge-danger"}">${escaparHtml(pagamento.status || "pendente")}</span>
            <strong>${formatarMoeda(Number(pagamento.amount ?? pagamento.valor ?? pagamento.price ?? 0) || 0)}</strong>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function renderSuperAdminCompanyLogList(cliente) {
  const id = String(cliente?.id || "");
  const logs = [
    ...auditLogs.filter((log) => String(log.clientId || "") === id),
    ...securityLogs.filter((log) => String(log.clientId || "") === id)
  ].sort((a, b) => Date.parse(b.at || b.createdAt || 0) - Date.parse(a.at || a.createdAt || 0));
  if (!logs.length) return renderSuperAdminEmptyCard("Logs", "Nenhum log local vinculado diretamente a esta empresa.");
  return `
    <div class="superadmin-profile-card">
      <h3>Logs e auditoria</h3>
      <div class="superadmin-profile-list">
        ${logs.slice(0, 10).map((log) => `
          <div class="superadmin-profile-list-row">
            <div>
              <strong>${escaparHtml(log.acao || log.action || "Evento")}</strong>
              <span>${escaparHtml(log.usuarioEmail || log.usuario || log.resultado || "")}</span>
            </div>
            <span>${escaparHtml(formatarDataPerfilSaas(log.at || log.createdAt || ""))}</span>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

function renderSuperAdminCompanyTabPanel(tab, dados) {
  const {
    cliente,
    assinatura,
    usuariosCliente,
    usuarioPrincipal,
    plano,
    pagamentos,
    pagamentosAprovados,
    planoCurto,
    statusPlano,
    emDia,
    criadoEm,
    ultimoAcesso,
    vencimento,
    proximaCobranca,
    acessoMes,
    acessoPercentual
  } = dados;
  const idAttr = escaparAttr(cliente.id);
  const limits = getPlanLimits(plano.slug || "free");
  const entitlements = getPlanEntitlements(plano.slug || "free");
  const loja = getStorefrontLimitsLocal(plano.slug || "free");
  const simNao = (valor) => valor ? "Sim" : "Não";
  const limite = (valor) => Number.isFinite(Number(valor)) ? String(valor) : "Ilimitado";
  const tabAtiva = normalizarAbaPerfilEmpresaSaas(tab);

  if (tabAtiva === "assinatura") {
    return `
      <div class="superadmin-company-tab-panel">
        <div class="superadmin-profile-card">
          <h3>Assinatura</h3>
          ${renderSuperAdminProfileRow("Plano atual", plano.name, { badge: planoCurto, badgeClass: classePlanoSaasCompacto(plano.slug) })}
          ${renderSuperAdminProfileRow("Status do plano", statusPlano, { badgeClass: emDia ? "badge-ativo" : "badge-danger" })}
          ${renderSuperAdminProfileRow("Plano pendente", assinatura?.pendingPlan || cliente.pendingPlan || "-")}
          ${renderSuperAdminProfileRow("Próxima cobrança", formatarDataPerfilSaas(proximaCobranca))}
          ${renderSuperAdminProfileRow("Vencimento do plano", formatarDataPerfilSaas(vencimento))}
          ${renderSuperAdminProfileRow("Preço mensal", formatarMoeda(Number(plano.price || assinatura?.planPrice || cliente.planPrice || 0)))}
        </div>
        <div class="superadmin-profile-card superadmin-profile-actions-card">
          <h3>Ações da assinatura</h3>
          <button class="profile-action-row" onclick="alterarPlanoClienteSaas('${idAttr}')">${renderUiIcon("assinatura")} <span>Alterar plano</span></button>
          <button class="profile-action-row" onclick="liberarDiasManualClienteSaas('${idAttr}')">${renderUiIcon("agenda")} <span>Adicionar dias ao acesso</span></button>
          <button class="profile-action-row warning" onclick="alterarStatusClienteSaas('${idAttr}', '${cliente.status === "blocked" ? "active" : "blocked"}')">${renderUiIcon("seguranca")} <span>${cliente.status === "blocked" ? "Reativar acesso" : "Suspender acesso"}</span></button>
        </div>
      </div>
    `;
  }

  if (tabAtiva === "limites") {
    return `
      <div class="superadmin-company-tab-panel">
        <div class="superadmin-profile-card">
          <h3>Limites do plano</h3>
          ${renderSuperAdminProfileRow("Produtos ERP", limite(limits.products))}
          ${renderSuperAdminProfileRow("Produtos loja", limite(limits.storefrontProducts))}
          ${renderSuperAdminProfileRow("Armazenamento", `${limite(limits.storageMb)} MB`)}
          ${renderSuperAdminProfileRow("Dispositivos", limite(limits.devices))}
          ${renderSuperAdminProfileRow("Usuários", limite(limits.users))}
        </div>
        <div class="superadmin-profile-card">
          <h3>Recursos liberados</h3>
          ${renderSuperAdminProfileRow("Relatórios avançados", simNao(entitlements.advancedReports))}
          ${renderSuperAdminProfileRow("Permissões avançadas", simNao(entitlements.advancedPermissions))}
          ${renderSuperAdminProfileRow("Funcionários", simNao(entitlements.employees))}
          ${renderSuperAdminProfileRow("Anúncios no plano", simNao(entitlements.ads))}
        </div>
      </div>
    `;
  }

  if (tabAtiva === "loja") {
    return `
      <div class="superadmin-company-tab-panel">
        <div class="superadmin-profile-card">
          <h3>Loja pública</h3>
          ${renderSuperAdminProfileRow("Editor habilitado", simNao(loja.enabled))}
          ${renderSuperAdminProfileRow("Publicação", simNao(loja.publishEnabled))}
          ${renderSuperAdminProfileRow("Link/QR Code", simNao(loja.shareEnabled || loja.qrCodeEnabled))}
          ${renderSuperAdminProfileRow("Contatos da loja", simNao(loja.leadsEnabled))}
          ${renderSuperAdminProfileRow("Marca Simplifica", loja.simplificaBrandingRequired ? "Obrigatória" : "Opcional")}
          ${renderSuperAdminProfileRow("Produtos permitidos", limite(loja.productLimit))}
        </div>
        <div class="superadmin-profile-card superadmin-profile-actions-card">
          <h3>Suporte da loja</h3>
          <button class="profile-action-row" onclick="trocarAbaSuperAdmin('lojas')">${renderUiIcon("lojaOnline")} <span>Ver mapa global de lojas</span></button>
          <button class="profile-action-row" onclick="editarClienteSaas('${idAttr}')">${renderUiIcon("edit")} <span>Revisar cadastro da empresa</span></button>
        </div>
      </div>
    `;
  }

  if (tabAtiva === "financeiro") {
    return `
      <div class="superadmin-company-tab-panel">
        <div class="superadmin-profile-card">
          <h3>Resumo financeiro</h3>
          ${renderSuperAdminProfileRow("Pagamentos aprovados", String(pagamentosAprovados.length))}
          ${renderSuperAdminProfileRow("Pagamentos totais", String(pagamentos.length))}
          ${renderSuperAdminProfileRow("Status assinatura", statusPlano)}
          ${renderSuperAdminProfileRow("Próxima cobrança", formatarDataPerfilSaas(proximaCobranca))}
        </div>
        ${renderSuperAdminCompanyPaymentList(pagamentos)}
      </div>
    `;
  }

  if (tabAtiva === "logs") {
    return `<div class="superadmin-company-tab-panel">${renderSuperAdminCompanyLogList(cliente)}</div>`;
  }

  if (tabAtiva === "suporte") {
    return `
      <div class="superadmin-company-tab-panel">
        <div class="superadmin-profile-card">
          <h3>Suporte</h3>
          ${renderSuperAdminProfileRow("Nome completo", cliente.name || usuarioPrincipal.nome || "-")}
          ${renderSuperAdminProfileRow("E-mail", cliente.email || usuarioPrincipal.email || "-")}
          ${renderSuperAdminProfileRow("Telefone", cliente.phone || usuarioPrincipal.phone || "-")}
          ${renderSuperAdminProfileRow("Usuários vinculados", String(usuariosCliente.length || 1))}
          ${renderSuperAdminProfileRow("Último acesso", ultimoAcesso ? formatarDataPerfilSaas(ultimoAcesso, "Agora") : "Sem acesso")}
        </div>
        <div class="superadmin-profile-card superadmin-profile-actions-card">
          <h3>Ações de suporte</h3>
          <button class="profile-action-row highlight" onclick="entrarManutencaoClienteSaas('${idAttr}')">${renderUiIcon("dashboard")} <span>Abrir ERP em manutenção</span></button>
          <button class="profile-action-row" onclick="editarClienteSaas('${idAttr}')">${renderUiIcon("edit")} <span>Editar empresa</span></button>
          <button class="profile-action-row" onclick="exportarClienteSaas('${idAttr}')">${renderUiIcon("backup")} <span>Exportar dados</span></button>
          <button class="profile-action-row" onclick="alternarUsuarioTesteSaas('${idAttr}')">${renderUiIcon("clientes")} <span>${cliente.isTestUser ? "Desativar usuário de teste" : "Marcar como usuário de teste"}</span></button>
        </div>
      </div>
    `;
  }

  return `
    <div class="superadmin-company-tab-panel">
      <div class="superadmin-profile-card">
        <h3>Resumo da conta</h3>
        ${renderSuperAdminProfileRow("Plano atual", plano.name, { badge: planoCurto, badgeClass: classePlanoSaasCompacto(plano.slug) })}
        ${renderSuperAdminProfileRow("Status do plano", statusPlano, { badgeClass: emDia ? "badge-ativo" : "badge-danger" })}
        ${renderSuperAdminProfileRow("Próxima cobrança", formatarDataPerfilSaas(proximaCobranca))}
        ${renderSuperAdminProfileRow("Vencimento do plano", formatarDataPerfilSaas(vencimento))}
        ${renderSuperAdminProfileRow("Pagamentos", String(pagamentosAprovados.length || pagamentos.length || 0))}
        ${renderSuperAdminProfileRow("Convites realizados", String(Math.max(0, usuariosCliente.length - 1)))}
      </div>
      <div class="superadmin-profile-card">
        <h3>Uso da conta</h3>
        <div class="superadmin-profile-row progress-row">
          <span>Acessos no mês</span>
          <strong>${acessoMes}</strong>
          <i class="profile-mini-progress"><em style="width:${acessoPercentual}%"></em></i>
          <small>${acessoPercentual}%</small>
        </div>
        ${renderSuperAdminProfileRow("Último acesso", ultimoAcesso ? formatarDataPerfilSaas(ultimoAcesso, "Agora") : "Agora")}
        ${renderSuperAdminProfileRow("Dispositivos ativos", String(Math.max(1, Number(cliente.deviceCount || cliente.dispositivosAtivos || usuariosCliente.length || 1))))}
      </div>
      <div class="superadmin-profile-card">
        <h3>Informações pessoais</h3>
        ${renderSuperAdminProfileRow("Nome completo", cliente.name || usuarioPrincipal.nome || "-")}
        ${renderSuperAdminProfileRow("E-mail", cliente.email || usuarioPrincipal.email || "-")}
        ${renderSuperAdminProfileRow("Telefone", cliente.phone || usuarioPrincipal.phone || "-")}
        ${renderSuperAdminProfileRow("Alterar senha", "", { onclick: usuariosCliente[0]?.id ? `redefinirSenhaUsuario('${escaparAttr(usuariosCliente[0].id)}')` : "" })}
      </div>
    </div>
  `;
}

function renderSuperAdminClientePerfil() {
  const id = window.__clienteSaasPerfilId || window.__clienteSaasSelecionadoId || "";
  const cliente = getClienteSaasPorId(id);
  if (!cliente) {
    return `
      <section class="card superadmin-profile-empty">
        <p class="empty">Usuário não encontrado.</p>
        <button class="btn secondary" onclick="voltarClientesSaas()">Voltar para clientes</button>
      </section>
    `;
  }
  const resumo = getResumoEmpresaSaas(cliente);
  const assinatura = resumo.assinatura;
  const usuariosCliente = resumo.usuarios;
  const usuarioPrincipal = resumo.responsavel;
  const plano = resumo.plano;
  const pagamentos = resumo.pagamentos;
  const pagamentosAprovados = resumo.pagamentosAprovados;
  const planoCurto = plano.slug === "pro" ? "PRO" : plano.slug === "start" ? "START" : "FREE";
  const statusPlano = getStatusPlanoClienteSaas(cliente, assinatura);
  const emDia = statusPlano === "Em dia";
  const online = cliente.status === "active";
  const criadoEm = cliente.createdAt || cliente.criadoEm || usuarioPrincipal.criadoEm || usuarioPrincipal.createdAt || "";
  const ultimoAcesso = cliente.lastAccessAt || usuarioPrincipal.lastLoginAt || usuarioPrincipal.ultimoAcesso || "";
  const vencimento = assinatura?.currentPeriodEnd || assinatura?.planExpiresAt || assinatura?.expiresAt || cliente.planExpiresAt || "";
  const proximaCobranca = assinatura?.nextBillingAt || assinatura?.proximoVencimento || "";
  const acessoMes = Math.max(1, pagamentos.length + usuariosCliente.length);
  const acessoPercentual = Math.min(100, Math.max(8, acessoMes * 8));
  const tabAtiva = normalizarAbaPerfilEmpresaSaas(window.__superAdminCompanyProfileTab || "resumo");
  const dadosPerfil = {
    cliente,
    assinatura,
    usuariosCliente,
    usuarioPrincipal,
    plano,
    pagamentos,
    pagamentosAprovados,
    planoCurto,
    statusPlano,
    emDia,
    criadoEm,
    ultimoAcesso,
    vencimento,
    proximaCobranca,
    acessoMes,
    acessoPercentual
  };
  return `
    <section class="superadmin-profile-screen">
      <div class="superadmin-profile-hero">
        <div class="superadmin-profile-avatar">
          ${usuarioPrincipal.avatarUrl || cliente.avatarUrl
            ? `<img src="${escaparAttr(usuarioPrincipal.avatarUrl || cliente.avatarUrl)}" alt="Foto de ${escaparAttr(cliente.name)}">`
            : `<span>${escaparHtml(getUserInitials(cliente.name || cliente.email))}</span>`}
          <i class="${online ? "online" : ""}"></i>
        </div>
        <div>
          <h2>${escaparHtml(cliente.name || usuarioPrincipal.nome || "Usuário")}</h2>
          <p class="muted">${escaparHtml(cliente.email || usuarioPrincipal.email || "-")}</p>
          <span class="status-badge ${classePlanoSaasCompacto(plano.slug)}">${escaparHtml(planoCurto)}</span>
        </div>
        <div class="superadmin-profile-hero-actions">
          <button class="btn primary" onclick="entrarManutencaoClienteSaas('${escaparAttr(cliente.id)}')">${renderUiIcon("dashboard")} Manutenção</button>
          <button class="btn secondary" onclick="editarClienteSaas('${escaparAttr(cliente.id)}')">${renderUiIcon("edit")} Editar</button>
          <button class="btn ghost" onclick="exportarClienteSaas('${escaparAttr(cliente.id)}')">${renderUiIcon("backup")} Exportar</button>
        </div>
      </div>

      <div class="superadmin-profile-status-grid">
        <div><span class="profile-status-dot ${online ? "online" : ""}"></span><strong>${online ? "Online" : "Offline"}</strong><small>${online ? "Agora" : "Sem sessão"}</small></div>
        <div><span class="profile-status-icon amber">${renderUiIcon("assinatura")}</span><strong>${escaparHtml(statusPlano)}</strong><small>Plano ativo</small></div>
        <div><span class="profile-status-icon purple">${renderUiIcon("agenda")}</span><strong>Membro desde</strong><small>${formatarDataPerfilSaas(criadoEm)}</small></div>
        <div><span class="profile-status-icon">${renderUiIcon("clientes")}</span><strong>ID Usuário</strong><small>#${escaparHtml(cliente.clientCode || String(cliente.id).slice(0, 6))}</small></div>
      </div>

      ${renderSuperAdminCompanyTabs(tabAtiva)}
      ${renderSuperAdminCompanyTabPanel(tabAtiva, dadosPerfil)}

      <div class="superadmin-profile-card superadmin-profile-actions-card">
        <h3>Ações</h3>
        <button class="profile-action-row" onclick="editarClienteSaas('${escaparAttr(cliente.id)}')">${renderUiIcon("edit")} <span>Editar usuário</span></button>
        <button class="profile-action-row warning" onclick="alterarStatusClienteSaas('${escaparAttr(cliente.id)}', '${cliente.status === "blocked" ? "active" : "blocked"}')">${renderUiIcon("seguranca")} <span>${cliente.status === "blocked" ? "Reativar acesso" : "Suspender acesso"}</span></button>
        <button class="profile-action-row" onclick="exportarClienteSaas('${escaparAttr(cliente.id)}')">${renderUiIcon("backup")} <span>Exportar dados</span></button>
      </div>

      <div class="superadmin-profile-card superadmin-profile-danger-zone">
        <h3>Zona de risco</h3>
        <p class="muted">${cliente.isTestUser ? "Exclusão permanente deve ser usada apenas para usuários de teste criados em validação." : "Anonimização remove dados pessoais e deve ser usada somente quando houver solicitação ou necessidade administrativa."}</p>
        <button class="superadmin-profile-danger" onclick="${cliente.isTestUser ? `excluirUsuarioTesteSaas('${escaparAttr(cliente.id)}')` : `anonimizarClienteSaas('${escaparAttr(cliente.id)}')`}">
          ${cliente.isTestUser ? "Excluir usuário de teste permanentemente" : "Anonimizar dados pessoais"}
        </button>
      </div>
    </section>
  `;
}

function renderClientesSaas() {
  if (!isSuperAdmin()) return renderClientesOperacionais();
  garantirEstruturaSaasLocal();
  const clientesVisiveis = saasClients.filter((cliente) => normalizarEmail(cliente.email) !== SUPERADMIN_BOOTSTRAP_EMAIL && !cliente.archivedAt);
  const total = clientesVisiveis.length;
  const ativos = clientesVisiveis.filter((cliente) => cliente.status === "active").length;
  const atrasados = clientesVisiveis.filter((cliente) => cliente.status === "overdue").length;
  const bloqueados = clientesVisiveis.filter((cliente) => cliente.status === "blocked").length;
  const inativos = clientesVisiveis.filter((cliente) => cliente.status === "inactive").length;
  const pagantes = clientesVisiveis.filter((cliente) => getResumoEmpresaSaas(cliente).plano.slug !== "free").length;
  const comTeste = clientesVisiveis.filter((cliente) => cliente.isTestUser).length;
  const filtros = window.__clientesSaasFiltros || {};
  const linhas = renderListaClientesSaasConteudo(total);

  return `
    <section class="card clients-saas-panel">
      <div class="superadmin-company-head">
        <div>
          <span class="eyebrow">Gestão SaaS</span>
          <h2>${renderUiIcon("clientes")} Empresas</h2>
          <p class="muted">Acompanhe empresas, assinaturas, acessos e ações administrativas sem sair do modo plataforma.</p>
        </div>
        <span class="status-badge badge-superadmin">${ativos} ativas</span>
      </div>
      <div class="superadmin-company-metrics">
        ${renderSuperAdminMetricCard("Total", total, `${pagantes} pagantes`, "clientes")}
        ${renderSuperAdminMetricCard("Ativas", ativos, "com acesso liberado", "dashboard", "success")}
        ${renderSuperAdminMetricCard("Atenção", atrasados + bloqueados, `${atrasados} atrasadas / ${bloqueados} bloqueadas`, "seguranca", atrasados || bloqueados ? "warning" : "")}
        ${renderSuperAdminMetricCard("Inativas", inativos, `${comTeste} usuários de teste`, "history")}
      </div>
      <div class="superadmin-company-toolbar">
        <label class="field">
          <span>Nome</span>
          <input id="clientesSaasFiltroNome" value="${escaparAttr(filtros.nome || "")}" oninput="filtrarClientesSaas('nome', this.value)" placeholder="empresa" autocomplete="off">
        </label>
        <label class="field">
          <span>E-mail</span>
          <input id="clientesSaasFiltroEmail" value="${escaparAttr(filtros.email || "")}" oninput="filtrarClientesSaas('email', this.value)" placeholder="cliente@email.com" autocomplete="off">
        </label>
        <label class="field">
          <span>Plano</span>
          <select onchange="filtrarClientesSaas('plano', this.value)">
            <option value="">Todos</option>
            ${garantirPlanosSaas().map((plano) => `<option value="${plano.slug}" ${filtros.plano === plano.slug ? "selected" : ""}>${escaparHtml(plano.name)}</option>`).join("")}
          </select>
        </label>
        <label class="field">
          <span>Status</span>
          <select onchange="filtrarClientesSaas('status', this.value)">
            <option value="">Todos</option>
            ${["active", "overdue", "blocked", "inactive", "cancelled", "anonymized"].map((status) => `<option value="${status}" ${filtros.status === status ? "selected" : ""}>${rotuloStatusCliente(status)}</option>`).join("")}
          </select>
        </label>
      </div>
      <div class="actions admin-action-grid compact-action-grid superadmin-company-actions">
        <button class="btn secondary" onclick="atualizarClientesSaasRemoto()">Atualizar Supabase</button>
        <button class="btn secondary" onclick="marcarClientesInativosAcao()">Marcar inativos &gt;90 dias</button>
        <button class="btn ghost" onclick="exportarClientesSaas()">Exportar dados</button>
      </div>
      <div id="clientesSaasLista" class="history-list users-list">${linhas}</div>
    </section>
  `;
}

function filtrarClientesSaas(campo, valor) {
  window.__clientesSaasFiltros = {
    ...(window.__clientesSaasFiltros || {}),
    [campo]: valor
  };
  window.__clientesSaasPagina = 1;
  clearTimeout(window.__clientesSaasFiltroTimer);
  window.__clientesSaasFiltroTimer = setTimeout(aplicarFiltroClientesSaasNaTela, 300);
}

function alvoInterativoClienteSaas(event) {
  return !!event?.target?.closest?.("button, a, input, select, textarea, label, .row-actions, .modal-card");
}

function fecharTecladoBuscaClientesSaas() {
  const ativo = document.activeElement;
  if (ativo && ["INPUT", "TEXTAREA", "SELECT"].includes(ativo.tagName)) {
    ativo.blur();
  }
}

function prepararSelecaoClienteSaas(event, id) {
  if (alvoInterativoClienteSaas(event)) return;
  const ponto = getPontoInteracaoClienteSaas(event);
  if (!ponto) return;
  window.__clienteSaasToque = {
    id: String(id),
    startX: ponto.x,
    startY: ponto.y,
    moved: false,
    cancelled: false,
    startedAt: Date.now()
  };
}

function getPontoInteracaoClienteSaas(event) {
  const toque = event?.changedTouches?.[0] || event?.touches?.[0] || null;
  const x = Number(toque?.clientX ?? event?.clientX);
  const y = Number(toque?.clientY ?? event?.clientY);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  return { x, y };
}

function atualizarMovimentoClienteSaas(event, id) {
  const estado = window.__clienteSaasToque;
  if (!estado || String(estado.id) !== String(id)) return;
  const ponto = getPontoInteracaoClienteSaas(event);
  if (!ponto) return;
  const dx = Math.abs(ponto.x - estado.startX);
  const dy = Math.abs(ponto.y - estado.startY);
  if (dx > 10 || dy > 10) {
    estado.moved = true;
  }
}

function cancelarSelecaoClienteSaas(event, id) {
  const estado = window.__clienteSaasToque;
  if (!estado || String(estado.id) !== String(id)) return;
  estado.cancelled = true;
  estado.moved = true;
}

function selecaoClienteSaasFoiArrasto(event, id) {
  const estado = window.__clienteSaasToque;
  if (!estado || String(estado.id) !== String(id)) return false;
  atualizarMovimentoClienteSaas(event, id);
  const foiArrasto = estado.moved === true || estado.cancelled === true;
  window.__clienteSaasToque = null;
  return foiArrasto;
}

function selecionarResultadoClienteSaas(event, id) {
  if (alvoInterativoClienteSaas(event)) return;
  if (selecaoClienteSaasFoiArrasto(event, id)) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  event.preventDefault();
  selecionarClienteSaasResultado(id);
}

function acionarClienteSaasPorTeclado(event, id) {
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  selecionarClienteSaasResultado(id);
}

async function selecionarClienteSaasResultado(id) {
  if (!id || window.__clienteSaasSelecaoEmAndamento === String(id)) return;
  window.__clienteSaasSelecaoEmAndamento = String(id);
  window.__clienteSaasSelecionadoId = String(id);
  fecharTecladoBuscaClientesSaas();
  try {
    abrirPerfilClienteSaas(id);
  } finally {
    window.__clienteSaasSelecaoEmAndamento = "";
  }
}

function abrirPerfilClienteSaas(id) {
  if (!isSuperAdmin() || !id) return;
  window.__clienteSaasSelecionadoId = String(id);
  window.__clienteSaasPerfilId = String(id);
  window.__superAdminTab = "clientePerfil";
  renderAppComTransicaoNavegacao("forward");
}

function voltarClientesSaas() {
  window.__superAdminTab = "clientes";
  window.__clienteSaasPerfilId = "";
  renderAppComTransicaoNavegacao("back");
}

function getClienteSaasPorId(id) {
  return saasClients.find((cliente) => String(cliente.id) === String(id));
}

async function editarClienteSaas(id) {
  if (!isSuperAdmin()) return;
  const cliente = getClienteSaasPorId(id);
  if (!cliente) return;
  const nomeAnterior = cliente.name;
  const telefoneAnterior = cliente.phone || "";
  const nome = await solicitarEntradaTexto({
    titulo: "Editar cliente",
    mensagem: "Nome da empresa",
    valor: cliente.name,
    obrigatorio: true
  });
  if (nome === null) return;
  const telefone = await solicitarEntradaTexto({
    titulo: "Editar cliente",
    mensagem: "Telefone",
    valor: cliente.phone || "",
    tipo: "tel"
  });
  const nomeAtualizado = nome.trim() || cliente.name;
  const telefoneAtualizado = telefone === null ? cliente.phone : (normalizePhoneBR(telefone) || telefone.trim());
  const mudou = nomeAtualizado !== nomeAnterior || telefoneAtualizado !== telefoneAnterior;
  if (!mudou) return;
  const toast = mostrarToast("Salvando...", "loading");
  try {
    if (podeSalvarAdminSupabaseRemoto()) {
      await atualizarClienteSaasSupabaseParcial(id, {
        name: nomeAtualizado,
        responsible_name: nomeAtualizado,
        nome_responsavel: nomeAtualizado,
        phone: telefoneAtualizado || null
      });
      await atualizarDadosPerfisClienteSupabase(id, {
        name: nomeAtualizado,
        phone: telefoneAtualizado || null
      });
    }
    cliente.name = nomeAtualizado;
    cliente.responsibleName = nomeAtualizado;
    cliente.phone = telefoneAtualizado;
    cliente.updatedAt = new Date().toISOString();
    getUsuariosDoCliente(id).forEach((usuario) => {
      const nomeUsuarioIgualAnterior = normalizarSugestaoClienteTexto(usuario.nome) === normalizarSugestaoClienteTexto(nomeAnterior);
      const telefoneUsuarioIgualAnterior = normalizarTelefoneWhatsapp(usuario.phone) === normalizarTelefoneWhatsapp(telefoneAnterior);
      if (!usuario.nome || nomeUsuarioIgualAnterior) usuario.nome = nomeAtualizado;
      if (!usuario.phone || telefoneUsuarioIgualAnterior) usuario.phone = telefoneAtualizado || "";
      usuario.atualizadoEm = cliente.updatedAt;
    });
    salvarDados();
    registrarAuditoria("cliente editado", { email: cliente.email, remoto: podeSalvarAdminSupabaseRemoto() }, cliente.id);
    mostrarToast(podeSalvarAdminSupabaseRemoto() ? "Usuário atualizado." : "Usuário salvo neste aparelho.", "sucesso", 3600);
  } catch (erro) {
    registrarDiagnostico("Superadmin", "Erro ao editar cliente", erro.message);
    mostrarToast(`Falha ao salvar usuário: ${erro.message}`, "erro", 6500);
  } finally {
    toast?.remove?.();
    renderApp();
  }
}

function pareceUuid(valor = "") {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(valor || ""));
}

function podeSalvarAdminSupabaseRemoto() {
  return isSuperAdmin() && !!syncConfig.supabaseAccessToken && !!syncConfig.supabaseUrl;
}

function getAlvoRpcClienteSaas(id) {
  const referencias = getReferenciasClienteSaas(id);
  const assinatura = getAssinaturaSaas(id);
  const candidatos = [
    assinatura?.userId,
    assinatura?.user_id,
    ...referencias.usuariosCliente.map((usuario) => usuario.userId || usuario.user_id || usuario.id),
    id
  ];
  return String(candidatos.find((valor) => pareceUuid(valor)) || id);
}

function aplicarLicencaEfetivaClienteSaas(id, licenca = {}) {
  if (!licenca || typeof licenca !== "object") return;
  const statusEfetivo = normalizarStatusLicencaEfetiva(licenca.effective_status || licenca.effectiveStatus || licenca.status);
  const activePlan = slugPlanoPorLicencaEfetiva(licenca);
  const cliente = getClienteSaasPorId(id || licenca.client_id);
  let assinatura = getAssinaturaSaas(id || licenca.client_id);
  if (!assinatura && (id || licenca.client_id)) {
    assinatura = normalizarAssinaturaSaas({ clientId: id || licenca.client_id, planSlug: activePlan, activePlan });
    saasSubscriptions.push(assinatura);
  }
  if (assinatura) {
    assinatura.userId = licenca.user_id || assinatura.userId || "";
    assinatura.planCode = String(licenca.plan_code || "").toUpperCase();
    assinatura.effectiveStatus = statusEfetivo;
    assinatura.planSlug = activePlan;
    assinatura.activePlan = activePlan;
    assinatura.pendingPlan = licenca.pending_plan || "";
    assinatura.paymentStatus = licenca.payment_status || (statusEfetivo === PLAN_ACCESS_STATES.PENDING ? "pending" : "none");
    assinatura.subscriptionStatus = normalizarStatusAssinaturaDefinitivo(licenca.subscription_status || (statusEfetivo === PLAN_ACCESS_STATES.ACTIVE ? "active" : "free"));
    assinatura.status = statusLegadoPorLicencaEfetiva(statusEfetivo);
    assinatura.statusAssinatura = assinatura.status;
    assinatura.planExpiresAt = licenca.premium_until || licenca.expires_at || "";
    assinatura.currentPeriodEnd = licenca.current_period_end || assinatura.planExpiresAt;
    assinatura.expiresAt = assinatura.planExpiresAt;
    assinatura.trialStartedAt = licenca.trial_start_at || licenca.trial_started_at || "";
    assinatura.trialExpiresAt = licenca.trial_end_at || licenca.trial_expires_at || "";
    assinatura.trialConsumedAt = licenca.trial_consumed_at || assinatura.trialConsumedAt || "";
    assinatura.isTrialActive = false;
    assinatura.manualOverride = licenca.manual_override === true;
    assinatura.manualOverrideReason = licenca.manual_override_reason || "";
    assinatura.blockedAt = licenca.blocked_at || "";
    assinatura.blockedReason = licenca.blocked_reason || "";
    assinatura.archivedAt = licenca.archived_at || "";
    assinatura.anonymizedAt = licenca.anonymized_at || "";
  }
  if (cliente) {
    cliente.activePlan = activePlan;
    cliente.planoAtual = activePlan;
    cliente.pendingPlan = licenca.pending_plan || "";
    cliente.paymentStatus = licenca.payment_status || (statusEfetivo === PLAN_ACCESS_STATES.PENDING ? "pending" : "none");
    cliente.subscriptionStatus = normalizarStatusAssinaturaDefinitivo(licenca.subscription_status || (statusEfetivo === PLAN_ACCESS_STATES.ACTIVE ? "active" : "free"));
    cliente.statusAssinatura = statusLegadoPorLicencaEfetiva(statusEfetivo);
    cliente.planExpiresAt = licenca.premium_until || licenca.expires_at || "";
    cliente.trialStartedAt = licenca.trial_start_at || licenca.trial_started_at || "";
    cliente.trialExpiresAt = licenca.trial_end_at || licenca.trial_expires_at || "";
    cliente.trialConsumedAt = licenca.trial_consumed_at || cliente.trialConsumedAt || "";
    cliente.isTrialActive = false;
    cliente.blockedAt = licenca.blocked_at || "";
    cliente.blockedReason = licenca.blocked_reason || "";
    cliente.archivedAt = licenca.archived_at || cliente.archivedAt || "";
    cliente.anonymizedAt = licenca.anonymized_at || cliente.anonymizedAt || "";
    if (statusEfetivo === PLAN_ACCESS_STATES.BLOCKED) cliente.status = "blocked";
    else if (cliente.anonymizedAt) cliente.status = "anonymized";
    else if (cliente.status !== "inactive") cliente.status = "active";
    cliente.updatedAt = licenca.updated_at || new Date().toISOString();
  }
  salvarDados();
}

