function alternarSenhaVisivel(idOuBotao) {
  const input = typeof idOuBotao === "string"
    ? document.getElementById(idOuBotao)
    : idOuBotao?.closest?.(".password-row")?.querySelector("input");
  if (!input) return;
  const botao = typeof idOuBotao === "string"
    ? input.closest?.(".password-row")?.querySelector?.(".icon-button")
    : idOuBotao;
  const mostrar = input.type === "password";
  input.type = mostrar ? "text" : "password";
  if (botao?.classList) {
    botao.classList.toggle("is-password-visible", mostrar);
    botao.setAttribute("aria-pressed", String(mostrar));
    botao.setAttribute("title", mostrar ? "Ocultar senha" : "Mostrar senha");
  }
  input.focus();
}

function carregarEmailLoginSalvo() {
  try {
    return String(localStorage.getItem(BROWSER_LOGIN_EMAIL_STORAGE_KEY) || "").trim();
  } catch (_) {
    return "";
  }
}

async function oferecerSalvarCredencialNavegador(email, senha) {
  appConfig.browserPasswordSaveOffer = document.getElementById("lembrarSenhaNavegador") ? !!document.getElementById("lembrarSenhaNavegador")?.checked : appConfig.browserPasswordSaveOffer !== false;
  salvarDados();
  try {
    if (appConfig.browserPasswordSaveOffer === false) {
      localStorage.removeItem(BROWSER_LOGIN_EMAIL_STORAGE_KEY);
      return;
    }
    if (email) localStorage.setItem(BROWSER_LOGIN_EMAIL_STORAGE_KEY, email);
  } catch (_) {
    // O navegador pode bloquear o armazenamento; o login continua normalmente.
  }
  if (!email || !senha) return;
  try {
    if ("PasswordCredential" in window && navigator.credentials?.store) {
      const credencial = new PasswordCredential({
        id: email,
        name: email,
        password: senha
      });
      await navigator.credentials.store(credencial);
    }
  } catch (erro) {
    registrarDiagnostico("login", "Navegador não ofereceu salvar senha", erro.message || erro);
  }
}

async function confirmarBiometriaSeDisponivel(mensagem = "Use digital, rosto ou padrão para continuar.") {
  const plugin = window.Capacitor?.Plugins?.SimplificaBiometric;
  if (!isAndroid() || !plugin?.authenticate) return { disponivel: false, ok: true };

  try {
    const resultado = await plugin.authenticate({
      title: "Simplifica 3D",
      subtitle: mensagem
    });

    if (resultado?.available === false) {
      return { disponivel: false, ok: true, codigo: resultado.code || "" };
    }

    return { disponivel: true, ok: resultado?.ok === true, codigo: resultado?.code || "" };
  } catch (erro) {
    registrarDiagnostico("login", "Biometria nativa falhou", erro.message || erro);
    return { disponivel: true, ok: false, codigo: "erro" };
  }
}

const SENSITIVE_ACTION_PIN_STORAGE_PREFIX = "simplificaSensitiveActionPin:";
const SENSITIVE_ACTION_PIN_ATTEMPTS_KEY = "simplificaSensitiveActionPinAttempts";
const SENSITIVE_ACTION_PIN_MAX_ATTEMPTS = 5;
const SENSITIVE_ACTION_PIN_LOCK_MS = 60 * 1000;

function normalizarPinAcoesSensiveis(config = {}) {
  const origem = config && typeof config === "object" && !Array.isArray(config) ? config : {};
  return {
    hash: String(origem.hash || ""),
    owner: String(origem.owner || ""),
    updatedAt: String(origem.updatedAt || "")
  };
}

function getDonoPinAcoesSensiveis() {
  const usuario = getUsuarioAtual();
  return String(usuario?.id || syncConfig.supabaseUserId || normalizarEmail(usuario?.email || usuarioAtualEmail || syncConfig.supabaseEmail || "")).trim();
}

function getChavePinAcoesSensiveis() {
  const owner = getDonoPinAcoesSensiveis();
  return owner ? `${SENSITIVE_ACTION_PIN_STORAGE_PREFIX}${owner}` : "";
}

function getPinAcoesSensiveisConfig() {
  const chave = getChavePinAcoesSensiveis();
  return chave ? normalizarPinAcoesSensiveis(carregarObjeto(chave, {})) : normalizarPinAcoesSensiveis();
}

function pinAcoesSensiveisAtivo() {
  const config = getPinAcoesSensiveisConfig();
  const owner = getDonoPinAcoesSensiveis();
  return !!(config.hash && owner && config.owner === owner);
}

function getTentativasPinAcoesSensiveis() {
  try {
    const estado = JSON.parse(sessionStorage.getItem(SENSITIVE_ACTION_PIN_ATTEMPTS_KEY) || "{}");
    return {
      count: Math.max(0, Number(estado.count) || 0),
      lockedUntil: Math.max(0, Number(estado.lockedUntil) || 0)
    };
  } catch (_) {
    return { count: 0, lockedUntil: 0 };
  }
}

function registrarTentativaPinAcoesSensiveis(ok) {
  if (ok) {
    sessionStorage.removeItem(SENSITIVE_ACTION_PIN_ATTEMPTS_KEY);
    return;
  }
  const atual = getTentativasPinAcoesSensiveis();
  const count = atual.lockedUntil > Date.now() ? atual.count : atual.count + 1;
  const lockedUntil = count >= SENSITIVE_ACTION_PIN_MAX_ATTEMPTS ? Date.now() + SENSITIVE_ACTION_PIN_LOCK_MS : 0;
  sessionStorage.setItem(SENSITIVE_ACTION_PIN_ATTEMPTS_KEY, JSON.stringify({ count: lockedUntil ? 0 : count, lockedUntil }));
}

async function validarPinAcoesSensiveis(pin) {
  if (!pinAcoesSensiveisAtivo() || !/^\d{4,12}$/.test(String(pin || ""))) return false;
  const tentativas = getTentativasPinAcoesSensiveis();
  if (tentativas.lockedUntil > Date.now()) {
    const segundos = Math.max(1, Math.ceil((tentativas.lockedUntil - Date.now()) / 1000));
    throw new Error(`Muitas tentativas incorretas. Aguarde ${segundos} segundos.`);
  }
  const ok = await verificarHashSenha(String(pin), getPinAcoesSensiveisConfig().hash);
  registrarTentativaPinAcoesSensiveis(ok);
  return ok;
}

async function salvarPinAcoesSensiveis() {
  const pin = String(document.getElementById("sensitiveActionPinConfig")?.value || "").trim();
  const confirmarPin = String(document.getElementById("sensitiveActionPinConfirmConfig")?.value || "").trim();
  const pinAtual = String(document.getElementById("sensitiveActionPinCurrentConfig")?.value || "").trim();
  if (!/^\d{4,12}$/.test(pin)) {
    mostrarToast("O PIN deve ter de 4 a 12 dígitos numéricos.", "erro", 3800);
    return;
  }
  if (/^(\d)\1+$/.test(pin) || ["1234", "4321", "0123", "9876"].includes(pin)) {
    mostrarToast("Escolha um PIN menos previsível.", "erro", 3600);
    return;
  }
  if (pin !== confirmarPin) {
    mostrarToast("A confirmação do PIN não confere.", "erro", 3400);
    return;
  }
  if (pinAcoesSensiveisAtivo()) {
    if (!pinAtual) {
      mostrarToast("Informe o PIN atual para continuar.", "erro", 3400);
      return;
    }
    try {
      if (!await validarPinAcoesSensiveis(pinAtual)) {
        mostrarToast("O PIN atual está incorreto.", "erro", 3400);
        return;
      }
    } catch (erro) {
      mostrarToast("Não foi possível validar o PIN atual.", "erro", 4200);
      return;
    }
    if (await verificarHashSenha(pin, getPinAcoesSensiveisConfig().hash)) {
      mostrarToast("O novo PIN deve ser diferente do PIN atual.", "aviso", 3600);
      return;
    }
  } else {
    const autorizado = await requestSensitiveActionConfirmation({
      actionLabel: "criar o PIN de segurança",
      permitirPin: false
    });
    if (!autorizado) return;
  }

  const chave = getChavePinAcoesSensiveis();
  if (!chave) {
    mostrarToast("Não foi possível vincular o PIN à conta atual.", "erro", 3600);
    return;
  }
  salvarJsonLocalSeMudou(chave, {
    hash: await gerarHashSenha(pin),
    owner: getDonoPinAcoesSensiveis(),
    updatedAt: new Date().toISOString()
  });
  registrarSeguranca("PIN de ações importantes configurado", "sucesso", "PIN vinculado à conta atual");
  mostrarToast("PIN salvo. Ele já pode autorizar alterações importantes no computador.", "sucesso", 4200);
  renderApp();
  registrarVisualizacaoProdutoLojaPublica(route);
}

async function removerPinAcoesSensiveis() {
  if (!pinAcoesSensiveisAtivo()) return;
  const autorizado = await requestSensitiveActionConfirmation({
    actionLabel: "remover o PIN de segurança",
    permitirPin: false
  });
  if (!autorizado) return;

  const chave = getChavePinAcoesSensiveis();
  if (chave) {
    localStorage.removeItem(chave);
    localStorageWriteCache.delete(chave);
  }
  registrarSeguranca("PIN de ações importantes removido", "sucesso");
  mostrarToast("PIN removido. As confirmações no computador voltarão a usar a senha.", "sucesso", 3800);
  renderApp();
}

async function alternarBiometriaSeguranca(ativar = null) {
  const desejaAtivar = ativar === null ? !!document.getElementById("biometricEnabledConfig")?.checked : !!ativar;
  if (!desejaAtivar && appConfig.biometricEnabled) {
    const confirmado = await solicitarConfirmacaoAcao({
      titulo: "Desativar proteção do aparelho?",
      mensagem: "O Simplifica 3D deixará de pedir digital, rosto, PIN, padrão ou senha do Android ao abrir seus dados neste aparelho.",
      confirmar: "Desativar proteção",
      cancelar: "Manter ativada",
      perigo: true
    });
    if (!confirmado) {
      const controle = document.getElementById("biometricEnabledConfig");
      if (controle) controle.checked = true;
      mostrarToast("A proteção do aparelho continua ativada.", "info", 2600);
      return;
    }
  }
  if (desejaAtivar) {
    const biometria = await confirmarBiometriaSeDisponivel("Confirme para ativar a entrada por digital, rosto ou padrão.");
    if (biometria.disponivel && !biometria.ok) {
      alert("Não foi possível confirmar a biometria agora.");
      appConfig.biometricEnabled = false;
      salvarDados();
      renderApp();
      return;
    }
    if (!biometria.disponivel && isAndroid()) {
      alert("Este aparelho não informou biometria, rosto ou padrão disponível para o app.");
    }
  }

  appConfig.biometricEnabled = desejaAtivar;
  if (desejaAtivar) appConfig.localLockEnabled = true;
  appConfig.biometricOfferDismissed = true;
  salvarDados();
  mostrarToast(desejaAtivar ? "Biometria ativada para este aparelho." : "Biometria desativada neste aparelho.", "sucesso");
  renderApp();
}

function oferecerAtivarBiometriaAposLogin() {
  if (!isAndroid() || appConfig.biometricEnabled || appConfig.biometricOfferDismissed) return;
  setTimeout(() => {
    if (!getUsuarioAtual()) return;
    const aceitar = confirm("Deseja ativar digital, rosto ou padrão para proteger a abertura do Simplifica 3D neste aparelho?");
    appConfig.biometricOfferDismissed = true;
    salvarDados();
    if (aceitar) {
      trocarTela("seguranca");
      setTimeout(() => alternarBiometriaSeguranca(true), 300);
    }
  }, 800);
}

async function entrarComCredencialSalva() {
  if (!navigator.credentials?.get) {
    alert("Este dispositivo não liberou login por senha salva, digital ou padrão para este app.");
    return;
  }

  try {
    if (appConfig.biometricEnabled) {
      const biometria = await confirmarBiometriaSeDisponivel("Use digital, rosto ou padrão para liberar a senha salva.");
      if (biometria.disponivel && !biometria.ok) {
        alert("Confirmação cancelada ou não autorizada.");
        return;
      }
    }

    const credencial = await navigator.credentials.get({
      password: true,
      mediation: "optional"
    });

    if (!credencial?.id || !credencial?.password) {
      alert("Nenhuma senha salva encontrada. Entre uma vez com e-mail e senha e marque a opção de salvar.");
      return;
    }

    const emailInput = document.getElementById("usuarioLoginEmail");
    const senhaInput = document.getElementById("usuarioLoginSenha");
    if (emailInput) emailInput.value = credencial.id;
    if (senhaInput) senhaInput.value = credencial.password;
    await loginUsuario();
  } catch (erro) {
    registrarDiagnostico("login", "Login por credencial salva falhou", erro.message || erro);
    alert("Não foi possível usar a senha salva neste dispositivo.");
  }
}

