function filtrarBuscaSuperadmin(valor) {
  const busca = String(valor || "");
  window.__superAdminBuscaGlobal = busca;
  window.__clientesSaasFiltros = {
    ...(window.__clientesSaasFiltros || {}),
    busca
  };
  window.__clientesSaasPagina = 1;
  if (normalizarAbaSuperAdmin(window.__superAdminTab || "") === "clientes") aplicarFiltroClientesSaasNaTela();
}

function fecharBuscaSuperadminAoEnviar(event) {
  if (!event || (event.key !== "Enter" && event.key !== "Escape")) return;
  event.preventDefault();
  fecharTecladoBuscaClientesSaas();
}

function limparBuscaSuperadmin(event) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  window.__superAdminBuscaGlobal = "";
  window.__clientesSaasFiltros = {
    ...(window.__clientesSaasFiltros || {}),
    busca: ""
  };
  window.__clientesSaasPagina = 1;
  document.querySelectorAll(".superadmin-platform-search input").forEach((input) => {
    input.value = "";
    input.blur();
  });
  if (normalizarAbaSuperAdmin(window.__superAdminTab || "") === "clientes") aplicarFiltroClientesSaasNaTela();
}

function voltarSuperAdminParaErp() {
  fecharTecladoBuscaClientesSaas();
  window.__superAdminTab = "dashboard";
  trocarTela("dashboard", { resetStack: true, skipStack: true, menuRoot: true, replaceHistory: true });
}

const SUPERADMIN_SECONDARY_LOAD_DELAYS = Object.freeze({
  suggestions: 160,
  diagnostics: 360
});

function esperarCarregamentoSuperadmin(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function agendarSincronizacaoSaasSuperadmin() {
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUrl) return;
  const ultima = Number(window.__superAdminSaasSyncAt) || 0;
  if (window.__superAdminSaasSyncPending || Date.now() - ultima < 30000) return;
  window.__superAdminSaasSyncPending = true;
  window.__superAdminSaasSyncPromise = (async () => {
    try {
      const resultados = await Promise.allSettled([
        carregarSaasSupabaseSilencioso({ renderizar: false, feedback: false }),
        esperarCarregamentoSuperadmin(SUPERADMIN_SECONDARY_LOAD_DELAYS.suggestions)
          .then(() => carregarSugestoesSupabase({ renderizar: false })),
        esperarCarregamentoSuperadmin(SUPERADMIN_SECONDARY_LOAD_DELAYS.diagnostics)
          .then(() => carregarDiagnosticosSuperadminSupabase({ renderizar: false }))
      ]);
      if (resultados[0]?.value?.ok !== false) window.__superAdminSaasSyncAt = Date.now();
    } finally {
      window.__superAdminSaasSyncPending = false;
      window.__superAdminSaasSyncPromise = null;
      if (telaAtual === "superadmin" && isSuperAdmin()) renderApp();
    }
  })();
}

function carregarDadosSecundariosSuperadmin() {
  if (!window.__superAdminSaasSyncPending) agendarSincronizacaoSaasSuperadmin();
}

function renderSuperAdmin() {
  if (!isSuperAdmin()) {
    return renderBloqueioPlano("Super Admin");
  }

  agendarSincronizacaoSaasSuperadmin();

  const tab = normalizarAbaSuperAdmin(window.__superAdminTab || "dashboard");

  if (tab === "clientePerfil") {
    return `
      <section class="ui3-real-screen ui3-superadmin superadmin-platform-shell superadmin-platform-profile-shell" data-ui-version="v3" data-ui3-screen="superadmin">
        ${renderSuperAdminSidebar("clientes")}
        <div class="superadmin-platform-main">
          ${renderSuperAdminTopbar("clientes")}
          <div class="superadmin-platform-content superadmin-profile-panel">
            <button class="btn ghost superadmin-platform-inline-back" type="button" onclick="voltarClientesSaas()">${renderUiIcon("back")} Voltar para empresas</button>
            ${renderSuperAdminConteudo(tab)}
          </div>
        </div>
      </section>
      ${renderSuperAdminMobileNav("clientes")}
    `;
  }

  return `
    <section class="ui3-real-screen ui3-superadmin superadmin-platform-shell" data-ui-version="v3" data-ui3-screen="superadmin">
      ${renderSuperAdminSidebar(tab)}
      <div class="superadmin-platform-main">
        ${renderSuperAdminTopbar(tab)}
        <main class="superadmin-platform-content">
          <div class="superadmin-platform-module superadmin-panel">
            ${renderSuperAdminConteudo(tab)}
          </div>
        </main>
      </div>
    </section>
    ${renderSuperAdminMobileNav(tab)}
  `;
}

function trocarAbaSuperAdmin(tab) {
  fecharTecladoBuscaClientesSaas();
  window.__superAdminTab = normalizarAbaSuperAdmin(tab || "dashboard");
  renderApp();
}

function abrirSuperAdminFiltro(tab, filtro) {
  if (tab === "clientes") {
    window.__superAdminTab = "clientes";
    window.__clientesSaasFiltros = filtro ? { ...(window.__clientesSaasFiltros || {}), plano: filtro } : {};
  } else if (tab === "clientesStatus") {
    window.__superAdminTab = "clientes";
    window.__clientesSaasFiltros = { ...(window.__clientesSaasFiltros || {}), status: filtro || "" };
  } else if (tab === "pagamentos") {
    window.__superAdminTab = "pagamentos";
    window.__superAdminPagamentoFiltro = filtro || "";
  }
  renderApp();
}

function filtrarPagamentosSuperAdmin(status) {
  window.__superAdminPagamentoFiltro = status || "";
  renderApp();
}

function filtrarSuperAdmin(valor) {
  window.__superAdminBusca = valor || "";
  renderApp();
}

async function atualizarUsuariosSuperAdminSupabase() {
  if (!isSuperAdmin()) return;
  if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUrl) {
    mostrarToast("Entre com uma sessão Supabase para carregar usuários online.", "erro");
    return;
  }
  await carregarSaasSupabaseSilencioso();
  mostrarToast("Usuários do Supabase atualizados no Superadmin.", "sucesso");
  renderApp();
}

function salvarAcessoSuperAdmin() {
  if (!isSuperAdmin()) return;
  const email = normalizarEmail(document.getElementById("superEmail")?.value || "");
  const tipo = document.getElementById("superPlanoTipo")?.value || "pro";
  const dias = Math.max(1, parseFloat(document.getElementById("superPlanoDias")?.value || 7) || 7);
  if (!email) {
    alert("Informe o e-mail.");
    return;
  }

  usuarios = normalizarUsuarios(usuarios);
  let usuario = usuarios.find((item) => item.email === email);
  if (!usuario) {
    usuario = normalizarUsuario({ nome: email.split("@")[0], email, senha: "Simplifica@123", papel: "admin", mustChangePassword: true });
    usuarios.push(usuario);
  }

  usuario.ativo = true;
  usuario.bloqueado = false;
  if (tipo === "pro") {
    usuario.planStatus = "active";
    usuario.trialStartedAt = "";
    usuario.trialDays = 0;
    usuario.planExpiresAt = new Date(Date.now() + dias * 24 * 60 * 60 * 1000).toISOString();
  } else {
    usuario.planStatus = "free";
    usuario.planExpiresAt = "";
  }

  salvarDados();
  registrarHistorico("Super Admin", `Acesso ${tipo} salvo para ${email}`);
  renderApp();
}

async function ajustarDiasUsuario(id, dias) {
  if (!isSuperAdmin()) return;
  const usuario = usuarios.find((item) => String(item.id) === String(id));
  if (!usuario) return;
  const quantidadeDias = Math.max(1, Math.floor(Number(dias) || 0));
  const clienteId = usuario.clientId || usuario.companyId || "";
  const targetUserId = usuario.supabaseUserId || usuario.id || usuario.email;
  if (!clienteId || !targetUserId) {
    mostrarToast("Este usuário não possui empresa ou identidade Supabase vinculada.", "erro", 4600);
    return;
  }

  let licencaAtual = null;
  try {
    licencaAtual = await consultarLicencaSupabaseSilencioso({ targetUserId, aplicar: false });
  } catch (erro) {
    registrarDiagnostico("Superadmin", "Licença não consultada antes de adicionar dias", erro.message || erro);
  }
  const validadeAtual = getTimestampPlano(
    licencaAtual?.premium_until
    || licencaAtual?.plan_expires_at
    || licencaAtual?.current_period_end
    || licencaAtual?.expires_at
    || usuario.planExpiresAt
    || 0
  );
  const premiumUntil = new Date(Math.max(Date.now(), validadeAtual || 0) + quantidadeDias * 86400000).toISOString();
  const confirmado = await solicitarConfirmacaoAcao({
    titulo: "Confirmar acesso Pro",
    mensagem: `Adicionar ${quantidadeDias} dia(s) de Pro para ${usuario.nome} (${usuario.email})? O acesso volta ao Free em ${new Date(premiumUntil).toLocaleDateString("pt-BR")}.`,
    confirmar: `Adicionar ${quantidadeDias} dias`
  });
  if (!confirmado) return;

  const toast = mostrarToast("Aplicando acesso Pro no banco...", "loading");
  try {
    const licenca = await chamarSuperadminUpdateSubscription(clienteId, "ACTIVATE_PREMIUM_MANUAL", {
      targetUserId,
      planCode: "PRO",
      premiumUntil,
      reason: `Cortesia manual pelo Superadmin (${quantidadeDias} dia(s))`
    });
    const validadeConfirmada = getTimestampPlano(
      licenca?.premium_until
      || licenca?.plan_expires_at
      || licenca?.current_period_end
      || licenca?.expires_at
      || 0
    );
    if (!validadeConfirmada || validadeConfirmada < getTimestampPlano(premiumUntil) - 60000) {
      throw new Error("O banco não confirmou a nova data de vencimento.");
    }
    usuario.planStatus = "paid";
    usuario.planExpiresAt = new Date(validadeConfirmada).toISOString();
    usuario.bloqueado = false;
    await carregarSaasSupabaseSilencioso({ renderizar: false, feedback: false });
    salvarDados();
    registrarHistorico("Super Admin", `+${quantidadeDias} dias Pro para ${usuario.email} até ${usuario.planExpiresAt}`);
    mostrarToast(`Pro confirmado até ${new Date(validadeConfirmada).toLocaleDateString("pt-BR")}. Depois retorna ao Free.`, "sucesso", 5200);
  } catch (erro) {
    registrarDiagnostico("Superadmin", "Erro ao adicionar dias ao usuário", erro.message || erro);
    mostrarToast(`Não foi possível adicionar os dias: ${erro.message}`, "erro", 6200);
  } finally {
    toast?.remove?.();
    renderApp();
  }
}

function alternarBloqueioUsuario(id) {
  if (!isSuperAdmin()) return;
  const usuario = usuarios.find((item) => String(item.id) === String(id));
  if (!usuario || isSuperAdminPrincipal(usuario)) return;
  usuario.bloqueado = !usuario.bloqueado;
  usuario.ativo = !usuario.bloqueado;
  salvarDados();
  registrarHistorico("Super Admin", `${usuario.bloqueado ? "Bloqueado" : "Desbloqueado"}: ${usuario.email}`);
  renderApp();
}

function excluirUsuarioSuperAdmin(id) {
  if (!isSuperAdmin()) return;
  const usuario = usuarios.find((item) => String(item.id) === String(id));
  if (!usuario || isSuperAdminPrincipal(usuario)) {
    alert("O superadmin principal não pode ser excluído.");
    return;
  }
  if (!confirm(`Excluir ${usuario.email}?`)) return;
  usuarios = usuarios.filter((item) => String(item.id) !== String(id));
  salvarDados();
  registrarHistorico("Super Admin", `Usuário excluído: ${usuario.email}`);
  renderApp();
}

function desbloquearRelatoriosComAnuncio() {
  if (!ADS_ENABLED) {
    mostrarToast("Relatórios avançados estão disponíveis no plano Pro.", "info", 4200);
    return;
  }
  mostrarModalDesbloqueioAnuncio({
    tipo: "reports",
    titulo: "Relatórios avançados",
    texto: "Assista a um anúncio para liberar relatórios avançados temporariamente ou assine o PRO para acesso permanente."
  }).then((liberado) => {
    if (liberado) renderizarPreservandoScroll();
  });
}

