    localStorage,
    mostrarToast,
    normalizarAppearanceSettings,
    normalizarCorTemaControlado,
    normalizarPdfTheme,
    normalizarPreferenciaTemaInterface,
    normalizePhoneBR,
    get PlanService() { return PlanService; },
    registrarDiagnostico,
    registrarFluxoSalvamento,
    registrarHistorico,
    renderizarPreservandoScroll,
