function getResumoPlanoUnico(estadoPlano, precoVigente, superadmin = false) {
  if (superadmin) {
    return {
      classe: "pro",
      titulo: "PRO ativo",
      detalhe: "Acesso interno liberado",
      status: "Ativo",
      dias: "Ativo",
      preco: `${formatarMoeda(precoVigente)}/mês`
    };
  }
  if (estadoPlano.state === PLAN_ACCESS_STATES.ACTIVE) {
    const dias = Math.max(0, Number(estadoPlano.planRemainingDays || 0));
    const dataRenovacao = estadoPlano.planExpiresAt ? new Date(estadoPlano.planExpiresAt).toLocaleDateString("pt-BR") : "";
    return {
      classe: "pro",
      titulo: "PRO ativo",
      detalhe: dataRenovacao ? `Renovação em ${dataRenovacao}.` : "Recursos completos liberados.",
      status: "Ativo",
      dias: dias > 0 && dias < 9999 ? `${dias} dias restantes` : "Ativo",
      preco: `${formatarMoeda(precoVigente)}/mês`
    };
  }
  if (estadoPlano.pending) {
    return {
      classe: "pending",
      titulo: "Plano atual: FREE",
      detalhe: "Existe um pagamento pendente. Ele não libera PRO e não bloqueia sua conta atual.",
      status: "Pagamento pendente",
      dias: "-",
      preco: `${formatarMoeda(precoVigente)}/mês`
    };
  }
  return {
    classe: "free",
    titulo: "Plano atual: FREE",
    detalhe: "Recursos básicos com anúncios leves. Faça upgrade para liberar o PRO.",
    status: "Gratuito",
    dias: "-",
    preco: `${formatarMoeda(precoVigente)}/mês`
  };
}

function renderStatusPlanoUnico(resumo) {
  return `
    <div class="plan-current-card plan-current-${escaparAttr(resumo.classe)}">
      <span class="plan-badge">${escaparHtml(resumo.status)}</span>
      <h3>${escaparHtml(resumo.titulo)}</h3>
      <p>${escaparHtml(resumo.detalhe)}</p>
      <div class="comparison-grid">
        <div class="metric"><span>Status</span><strong>${escaparHtml(resumo.status)}</strong></div>
        <div class="metric"><span>Período</span><strong>${escaparHtml(resumo.dias)}</strong></div>
        <div class="metric"><span>PRO</span><strong>${escaparHtml(resumo.preco)}</strong></div>
      </div>
    </div>
  `;
}

function registrarEventoPlanoSeguro(eventType, metadata = {}, onceKey = "") {
  const key = String(onceKey || "");
  if (key && planDiagnosticsSeen.has(key)) return;
  if (key) planDiagnosticsSeen.add(key);
  try {
    if (typeof window.reportDiagnosticEvent !== "function") return;
    void window.reportDiagnosticEvent(eventType, {
      screen: "planos",
      action: eventType,
      metadata
    });
  } catch (_) {}
}

function getCheckoutVisualState() {
  limparCheckoutsLocaisExpirados();
  // Abrir ou abandonar o checkout não é um estado de pagamento e não deve
  // deixar aviso persistente na tela de planos. Pendências reais são tratadas
  // exclusivamente por accessState.shouldShowPendingPayment.
  return { type: "", message: "" };
}

function renderPlanPaymentNotice(accessState, checkoutState) {
  if (accessState.shouldShowPendingPayment) {
    return `
      <div class="plans-state-notice pending" role="status">
        <strong>Pagamento em processamento.</strong>
        <span>Assim que houver confirmação, seu plano será atualizado automaticamente.</span>
      </div>
    `;
  }
  if (sugestoesInteligentesAtivas()) {
    const memoria = UsageMemoryManager.exportUserUsageMemory();
    const telaFrequente = valorPreferidoMemoriaUso(memoria.screenStats);
    const telasPermitidas = {
      calculadora: { label: "Calculadora", icon: "calculadora" },
      pedidos: { label: "Pedidos", icon: "pedidos" },
      pedido: { label: "Novo pedido", icon: "pedidos" },
      estoque: { label: "Estoque", icon: "estoque" },
      producao: { label: "Produção", icon: "producao" },
      clientes: { label: "Clientes", icon: "clientes" },
      caixa: { label: "Caixa", icon: "caixa" }
    };
    const sugestao = telasPermitidas[telaFrequente];
    if (sugestao) {
      const usuario = getUsuarioAtual();
      const nome = String(usuario?.nome || usuario?.email || "você").split(/\s+/)[0] || "você";
      const pendentes = getPedidosAguardandoEnvioDashboard().length;
      const complemento = pendentes
        ? ` Há ${pendentes} pedido${pendentes === 1 ? "" : "s"} aguardando envio.`
        : " Posso ajudar com outra tarefa quando precisar.";
      return `
        <section class="dashboard-smart-insight">
          <span class="insight-icon">${renderUiIcon(sugestao.icon)}</span>
          <div>
            <strong>Olá, ${escaparHtml(nome)}. Quer abrir ${escaparHtml(sugestao.label)} novamente?</strong>
            <small>${escaparHtml(complemento.trim())}</small>
          </div>
          <button class="btn secondary compact-action" type="button" onclick="trocarTela('${escaparAttr(telaFrequente)}')">Abrir</button>
        </section>
      `;
    }
  }
  return "";
}

function selecionarPresetMargemCalculadora(valor) {
  const margem = Math.max(0, Math.round(Number(valor) || 0));
  const campo = document.getElementById("defaultMarginConfig");
  if (campo) campo.value = String(margem);
  appConfig.defaultMargin = margem;
  salvarDados();
  mostrarToast(`Margem padrão ajustada para ${margem}%.`, "sucesso", 2600);
  renderizarPreservandoScroll();
}

