async function chamarFuncaoSaas(nome, corpo = {}) {
  if (!syncConfig.supabaseAccessToken) {
    throw new Error("Entre na conta online antes de iniciar o pagamento.");
  }
  syncConfig.supabaseUrl = normalizarUrlSupabase(syncConfig.supabaseUrl || SUPABASE_DEFAULT_URL);
  syncConfig.supabaseAnonKey = syncConfig.supabaseAnonKey || SUPABASE_DEFAULT_ANON_KEY;
  return await requisicaoSupabase(`/functions/v1/${nome}`, {
    method: "POST",
    body: JSON.stringify(corpo)
  });
}

function registrarPagamentoLocalPendente(plano, dados = {}, tipo = "subscription") {
  limparCheckoutsLocaisExpirados({ force: true });
  const clientId = getClientIdAtual() || billingConfig.clientId;
  const assinatura = garantirAssinaturaClienteLocal(clientId);
  const billingVariant = normalizarBillingVariant(dados.billing_variant || dados.billingVariant || getBillingVariantAssinatura(assinatura));
  const precoPadrao = getPrecoBillingVariant(billingVariant);
  const planPrice = Math.max(0, Number(dados.plan_price ?? dados.planPrice ?? dados.amount ?? dados.valor ?? precoPadrao) || precoPadrao);
  const createdAt = new Date().toISOString();
  const expiresAt = new Date(Date.now() + LOCAL_CHECKOUT_PENDING_TTL_MS).toISOString();
  const pagamento = normalizarPagamentoSaas({
    clientId,
    subscriptionId: assinatura.id,
    mercadoPagoSubscriptionId: dados.subscriptionId || assinatura.mercadoPagoSubscriptionId || "",
    preferenceId: dados.preference_id || dados.preferenceId || "",
    externalReference: dados.external_reference || "",
    planSlug: plano.slug,
    billingVariant,
    amount: Number(dados.amount || dados.valor || planPrice),
    status: "checkout_opened",
    paymentMethod: "mercado_pago",
    createdAt
  });
  pagamento.planPrice = planPrice;
  pagamento.checkoutExpiresAt = expiresAt;
  saasPayments.unshift(pagamento);
  saasPayments = saasPayments.slice(0, 500);
  if (dados.subscriptionId) assinatura.mercadoPagoSubscriptionId = String(dados.subscriptionId);
  assinatura.lastCheckoutAt = createdAt;
  assinatura.lastCheckoutPlan = plano.slug;
  assinatura.lastCheckoutExpiresAt = expiresAt;
  assinatura.lastCheckoutPrice = planPrice;
  billingConfig.lastCheckoutAt = createdAt;
  billingConfig.lastCheckoutPlan = plano.slug;
  billingConfig.lastCheckoutExpiresAt = expiresAt;
  billingConfig.lastCheckoutPrice = planPrice;
  try {
    window.sessionStorage?.setItem?.(CHECKOUT_SESSION_STORAGE_KEY, JSON.stringify({
      planSlug: plano.slug,
      billingVariant,
      planPrice,
      preferenceId: pagamento.preferenceId,
      createdAt,
      expiresAt
    }));
  } catch (_) {}
  salvarDados();
  registrarAuditoria("checkout aberto", { tipo, plano: plano.slug, preferenceId: pagamento.preferenceId, subscriptionId: pagamento.mercadoPagoSubscriptionId }, clientId);
  registrarEventoPlanoSeguro("checkout_opened", { plan: plano.slug, type: tipo });
}

async function abrirLinkMercadoPago(slug = "pro") {
  const plano = getPlanoSaas(slug);
  if (plano.slug === "start" && !isStartPlanCommerciallyEnabled()) {
    registrarEventoPlanoSeguro("plan_start_unavailable_clicked", { plan: "start" });
    mostrarToast("O plano Start será liberado em breve. A contratação segura disponível agora é o Pro.", "info", 6500);
    return;
  }
  if (!["start", "pro"].includes(plano.slug)) {
    trocarTela("assinatura");
    return;
  }

  const clientId = getClientIdAtual() || billingConfig.clientId;
  if (!clientId) {
    alert("Crie ou entre na conta antes de escolher um plano.");
    trocarTela("admin");
    return;
  }

  const planEvent = plano.slug === "start" ? "start_plan_checkout_requested" : "plan_checkout_clicked";
  registrarEventoPlanoSeguro(planEvent, { plan: plano.slug });
  if (plano.slug === "pro" && normalizarSlugPlano(billingConfig.activePlan || billingConfig.planSlug || "free") === "start") {
    registrarEventoPlanoSeguro("start_to_pro_upgrade_requested", { from: "start", to: "pro" });
  }
  const confirmou = await solicitarConfirmacaoAcao({
    titulo: `Assinar plano ${plano.slug === "start" ? "Start" : "Pro"}`,
    mensagem: "Você será direcionado ao pagamento seguro do Mercado Pago. Seu plano será ativado automaticamente após a confirmação.",
    confirmar: "Continuar para pagamento"
  });
  if (!confirmou) return;

  registrarAuditoria("tentativa", { tipo: "assinatura", plano: plano.slug }, clientId);
  try {
    const assinatura = garantirAssinaturaClienteLocal(clientId);
    const billingVariant = plano.slug === "start" ? "start_monthly" : "pro_monthly";
    const planPrice = getPrecoBillingVariant(billingVariant);
    const checkoutFunction = plano.slug === "start" ? "mercadopago-create-subscription" : "mercadopago-create-payment";
    const dados = await chamarFuncaoSaas(checkoutFunction, {
      clienteId: clientId,
      plan_id: plano.slug,
      billing_variant: billingVariant,
      plan_price: planPrice,
      amount: planPrice,
      plan: plano.slug,
      planSlug: plano.slug,
      email: getEmailLicencaAtual()
    });
    if (!dados?.init_point) throw new Error("Link de pagamento não retornado.");
    if (plano.slug === "start") registrarEventoPlanoSeguro("start_plan_checkout_created", { plan: "start" });
    registrarPagamentoLocalPendente(plano, dados, "payment");
    window.open(dados.init_point, "_blank");
  } catch (erro) {
    if (plano.slug === "start") registrarEventoPlanoSeguro("start_plan_checkout_failed", { plan: "start", reason: erro?.message || "unknown" });
    registrarDiagnostico("Mercado Pago", "Pagamento não criado", erro.message);
    registrarErroAplicacaoSilencioso("PAYMENT_STATUS_FAILED", erro, "Criar pagamento Mercado Pago", { plano: plano.slug });
    if (billingConfig.mercadoPagoLink) {
      window.open(billingConfig.mercadoPagoLink, "_blank");
      return;
    }
    alert(erro.message || "Não foi possível iniciar o pagamento agora.");
  }
}

async function criarPagamentoUnicoMercadoPago(slug = "pro") {
  const plano = getPlanoSaas(slug);
  if (plano.slug === "start" && !isStartPlanCommerciallyEnabled()) {
    registrarEventoPlanoSeguro("plan_start_unavailable_clicked", { plan: "start", origin: "single-payment" });
    mostrarToast("O plano Start ainda não está disponível para contratação.", "info", 5500);
    return;
  }
  if (!["start", "pro"].includes(plano.slug)) {
    alert("Pagamento disponível para planos pagos.");
    return;
  }

  const clientId = getClientIdAtual() || billingConfig.clientId;
  if (!clientId) {
    alert("Crie ou entre na conta antes de pagar.");
    trocarTela("admin");
    return;
  }

  try {
    const assinatura = garantirAssinaturaClienteLocal(clientId);
    const billingVariant = plano.slug === "start" ? "start_monthly" : "pro_monthly";
    const planPrice = getPrecoBillingVariant(billingVariant);
    const checkoutFunction = plano.slug === "start" ? "mercadopago-create-subscription" : "mercadopago-create-payment";
    const dados = await chamarFuncaoSaas(checkoutFunction, {
      clienteId: clientId,
      plan_id: plano.slug,
      billing_variant: billingVariant,
      plan_price: planPrice,
      amount: planPrice,
      plan: plano.slug,
      planSlug: plano.slug,
      email: getEmailLicencaAtual()
    });
    if (!dados?.init_point) throw new Error("Link de pagamento não retornado.");
    registrarPagamentoLocalPendente(plano, dados, "payment");
    window.open(dados.init_point, "_blank");
  } catch (erro) {
    registrarDiagnostico("Mercado Pago", "Pagamento não criado", erro.message);
    registrarErroAplicacaoSilencioso("PAYMENT_STATUS_FAILED", erro, "Criar pagamento avulso Mercado Pago", { plano: plano.slug });
    alert(erro.message || "Não foi possível iniciar o pagamento agora.");
  }
}

