async function iniciarAdicionarItemPedido() {
  const abrir = await solicitarConfirmacaoAcao({
    titulo: "Adicionar item",
    mensagem: "Deseja abrir a calculadora para calcular este item?",
    confirmar: "Sim, abrir calculadora",
    cancelar: "Adicionar manual"
  });
  if (abrir) {
    openCalculatorForOrder();
    return;
  }
  abrirItemManualPedido();
}

function openCalculatorForOrder() {
  calculadoraModoPedido = true;
  abrirCalculadora({ fromOrder: true });
  mostrarToast("Calcule o item e confirme para adicionar ao pedido.", "info", 3200);
}

async function removerItem(i) {
  const confirmado = await solicitarConfirmacaoAcao({
    titulo: "Remover item",
    mensagem: "Remover este item do pedido?",
    confirmar: "Remover",
    cancelar: "Cancelar",
    perigo: true
  });
  if (!confirmado) return;
  if (!await consumirCreditoAcaoFree("excluir_item", "excluir item do pedido")) return;
  itensPedido.splice(i, 1);
  window.__pedidoItensSelecionados = getItensPedidoSelecionados()
    .filter((selecionado) => selecionado !== i)
    .map((selecionado) => selecionado > i ? selecionado - 1 : selecionado);
  const atual = Number(window.__pedidoItemSelecionado);
  if (Number.isInteger(atual)) window.__pedidoItemSelecionado = Math.max(0, Math.min(atual, itensPedido.length - 1));
  renderizarPreservandoScroll();
}

function selecionarItemPedido(i) {
  return SimplificaOrdersHandlers.selectOrderItem(i, {
    items: () => itensPedido,
    setCurrentItem: (index) => { window.__pedidoItemSelecionado = index; },
    updateSelectedItemUi: (index) => {
      document.querySelectorAll(".order-item-card").forEach((card) => {
        const active = Number(card.dataset.orderItemIndex) === index;
        card.classList.toggle("selected", active);
        if (active) card.open = true;
      });
      document.querySelectorAll(".order-item-selector").forEach((selector, itemIndex) => { selector.textContent = itemIndex === index ? "✓" : String(itemIndex + 1); });
      const label = document.querySelector("[data-selected-item-label]");
      if (label) label.textContent = "Item " + (index + 1) + " selecionado";
    }
  });
}

