function createOrderHeader() {
  validarSugestaoClienteAntesSalvar();
  const header = SimplificaOrdersController.buildOrderHeader({
    customer: document.getElementById("clienteNome")?.value || clientePedido,
    phone: document.getElementById("clienteTelefone")?.value || clienteTelefonePedido,
    email: document.getElementById("clienteEmail")?.value || clienteEmailPedido,
    notes: document.getElementById("pedidoObservacao")?.value || observacaoPedido,
    dueDate: document.getElementById("pedidoPrazo")?.value || prazoPedido,
    downPayment: document.getElementById("pedidoEntrada")?.value ?? entradaPedido,
    paymentMethodId: document.getElementById("pedidoMetodoPagamento")?.value || quickOrderPaymentMethodDraft || pedidoEditando?.paymentMethodId || pedidoEditando?.payment_method_id || "pix",
    status: document.getElementById("pedidoStatus")?.value || statusPedido || pedidoEditando?.status || "aberto"
  }, { normalizePhone: normalizarTelefoneWhatsapp, parseNumber: numeroMonetarioPedido, normalizePaymentMethod: normalizarMetodoPagamentoCaixa });
  clientePedido = header.cliente;
  clienteTelefonePedido = header.telefone;
  clienteEmailPedido = header.email;
  observacaoPedido = header.observacao;
  prazoPedido = header.prazo;
  entradaPedido = header.entrada;
  quickOrderPaymentMethodDraft = header.paymentMethodId;
  return header;
}

function solicitarDecisaoItemDuplicado(item, existente) {
  return new Promise((resolve) => {
    const popup = document.getElementById("popup");
    if (!popup) {
      resolve(null);
      return;
    }
    popup.innerHTML = `
      <div class="modal-backdrop" role="dialog" aria-modal="true">
        <div class="modal-card">
          <div class="modal-header">
            <h2>Item já existe</h2>
            <button class="icon-button" type="button" data-dup-action="cancel" title="Fechar">✕</button>
          </div>
          <p class="muted">Este item parece já existir no pedido. Deseja adicionar mais uma unidade?</p>
          <div class="duplicate-item-preview">
            <strong>${escaparHtml(existente.nome || "Item")}</strong>
            <span>${formatarMoeda(Number(existente.valor) || 0)} • qtd atual ${Number(existente.qtd) || 1}</span>
          </div>
          <div class="actions stacked-actions">
            <button class="btn" type="button" data-dup-action="increment">Adicionar como +1 unidade</button>
            <button class="btn secondary" type="button" data-dup-action="separate">Adicionar separado</button>
            <button class="btn ghost" type="button" data-dup-action="cancel">Cancelar</button>
          </div>
        </div>
      </div>
    `;
    let settled = false;
    const finalizar = (valor) => {
      if (settled) return;
      settled = true;
      fecharPopup();
      resolve(valor);
    };
    const host = promoverPopupParaDialogUiV3(popup, { title: "Item já existe", onClose: () => finalizar(null) });
    host.querySelectorAll("[data-dup-action]").forEach((botao) => {
      botao.addEventListener("click", () => {
        const action = botao.dataset.dupAction || "cancel";
        finalizar(action === "increment" || action === "separate" ? action : null);
      }, { once: true });
    });
    host.querySelector(".modal-backdrop")?.addEventListener("click", (event) => {
      if (event.target === event.currentTarget) {
        finalizar(null);
      }
    }, { once: true });
  });
}

async function addCalculatedItemToOrder(item, opcoes = {}) {
  return SimplificaOrdersHandlers.addCalculatedItem(item, opcoes, {
    isAdding: () => itemAdicionandoPedido,
    setAdding: (value) => { itemAdicionandoPedido = value; },
    document,
    toast: mostrarToast,
    validateItem: validarItemPedidoParaSalvar,
    fingerprint: fingerprintItemPedido,
    nowMillis: Date.now,
    lastFingerprint: () => lastOrderItemAddFingerprint,
    lastAddedAt: () => lastOrderItemAddAt,
    setLastAdded: (fingerprint, at) => { lastOrderItemAddFingerprint = fingerprint; lastOrderItemAddAt = at; },
    findEquivalent: encontrarItemEquivalentePedido,
    findSimilar: encontrarItemSemelhantePedido,
    items: () => itensPedido,
    decideDuplicate: solicitarDecisaoItemDuplicado,
    consumeCredit: consumirCreditoAcaoFree,
    setSelectedItem: (index) => { window.__pedidoItemSelecionado = index; },
    recordUsage: registrarEventoUsoLocal,
    minimizeCalculator: minimizarCalculadora,
    navigateToOrder: () => trocarTela("pedido"),
    notify: ErrorService.notify
  });
}

async function confirmCalculatorResult() {
  if (!ultimoCalculo) {
    const calculou = calcular();
    if (!calculou || !ultimoCalculo) {
      alert("Preencha peso, tempo, material e quantidade antes de adicionar.");
      return false;
    }
  }
  if (!ultimoCalculo || ultimoCalculo.preco <= 0) {
    alert("Calcule um valor válido antes de adicionar");
    return false;
  }
  const nome = String(document.getElementById("nomeItem")?.value || "").trim() || `Item ${ultimoCalculo.materialNome || "3D"}`;
  const qtd = Math.max(1, Number(ultimoCalculo.qtd) || 1);
  const valorManual = numeroCalculadora(document.getElementById("valorManualItem")?.value, ultimoCalculo.preco, 0);
  const observacoesCalculo = String(document.getElementById("observacoesCalculo")?.value || "").trim();
  const titulo = calculadoraModoPedido || telaAtual === "pedido" ? "Adicionar item ao pedido" : "Criar pedido com este item";
  const mensagem = calculadoraModoPedido || telaAtual === "pedido"
    ? `Deseja adicionar "${nome}" ao pedido por ${formatarMoeda(valorManual)} cada?`
    : `Deseja criar um pedido com "${nome}" por ${formatarMoeda(valorManual)} cada?`;
  const confirmado = await solicitarConfirmacaoAcao({
    titulo,
    mensagem,
    confirmar: calculadoraModoPedido || telaAtual === "pedido" ? "Adicionar item" : "Criar pedido",
    cancelar: "Voltar e editar"
  });
  if (!confirmado) return false;
  const item = {
    id: "item-" + Date.now().toString(36),
    nome,
    tipoImpressao: ultimoCalculo.tipoImpressao,
    impressora: ultimoCalculo.printer,
    tempoHoras: ultimoCalculo.tempo,
    tempoMinutos: Math.round((Number(ultimoCalculo.tempo) || 0) * 60),
    materialId: "",
    material: ultimoCalculo.materialNome,
    materialGramsTotal: ultimoCalculo.peso,
    materiais: [],
    custoMaterial: ultimoCalculo.custoMaterial,
    custoEnergia: ultimoCalculo.custoEnergia,
    custoTotal: ultimoCalculo.custoTotal,
    baseProduto: ultimoCalculo.baseProduto,
    lucroProduto: ultimoCalculo.lucroProduto,
    valorProduto: ultimoCalculo.valorProduto,
    taxaExtra: ultimoCalculo.taxaExtra,
    loteAtivo: ultimoCalculo.impressaoLote === true,
    modoLote: ultimoCalculo.modoLote || "per_piece",
    pesoInformado: ultimoCalculo.pesoInformado ?? ultimoCalculo.peso,
    pesoTotal: ultimoCalculo.pesoTotal ?? ultimoCalculo.peso,
    tempoInformadoMinutos: ultimoCalculo.tempoInformadoMinutos ?? Math.round((Number(ultimoCalculo.tempo) || 0) * 60),
    tempoTotalMinutos: ultimoCalculo.tempoTotalMinutos ?? Math.round((Number(ultimoCalculo.tempo) || 0) * 60),
    taxaExtraAtiva: ultimoCalculo.taxaExtra > 0,
    tipoTaxaExtra: ultimoCalculo.taxaExtraMode === "manual" ? "fixed" : "percent",
    calculoOrigem: {
      pesoInformado: ultimoCalculo.peso,
      tempoHoras: ultimoCalculo.tempo,
      valorTotalCalculado: ultimoCalculo.totalFinal,
      quantidadeLote: qtd,
      loteAtivo: ultimoCalculo.impressaoLote === true,
      modoLote: ultimoCalculo.modoLote || "per_piece",
      pesoTotal: ultimoCalculo.pesoTotal ?? ultimoCalculo.peso,
      tempoInformadoMinutos: ultimoCalculo.tempoInformadoMinutos,
      tempoTotalMinutos: ultimoCalculo.tempoTotalMinutos,
      taxaExtraAtiva: ultimoCalculo.taxaExtra > 0,
      tipoTaxaExtra: ultimoCalculo.taxaExtraMode === "manual" ? "fixed" : "percent",
      valorUnitarioCalculado: ultimoCalculo.preco,
      observacoes: observacoesCalculo
    },
    observacoesCalculo,
    qtd,
    valor: valorManual,
    total: valorManual * qtd
  };
  const adicionado = await addCalculatedItemToOrder(item);
  if (adicionado) {
    calculadoraModoPedido = false;
    limparCalculo();
  }
  return adicionado;
}

function garantirMateriaisItem(i) {
  return SimplificaOrdersController.ensureItemMaterials(itensPedido, i, { normalizeItem: normalizarItemPedido });
}

function editarMaterialItem(itemIndex, materialIndex, materialId) {
  const materiais = garantirMateriaisItem(itemIndex);
  const material = getMaterialEstoque(materialId);
  const anterior = materiais[materialIndex] || {};
  const quantidadePadrao = material ? (["kg", "g", "ml", "l", "m", "cm"].includes(String(material.unidade)) ? 0.001 : 1) : 0;
  materiais[materialIndex] = {
    ...anterior,
    materialId,
    nome: material?.nome || "",
    quantidade: Number(anterior.quantidade) || quantidadePadrao,
    unidade: material?.unidade || "un",
    valorUnitario: Math.max(0, Number(anterior.valorUnitario) || Number(material?.custoUnitario || material?.unit_cost) || 0),
    gramas: 0
  };
  ajustarTotalPorMaterialPedido(itemIndex, anterior, materiais[materialIndex]);
  renderizarPreservandoScroll();
}

function selecionarMaterialPedidoPorPesquisa(itemIndex, materialIndex, termo = "") {
  const busca = normalizarTextoBusca(termo);
  const material = normalizarEstoque().find((item) => normalizarTextoBusca(item.nome) === busca || String(item.id) === String(termo));
  if (!material) {
    mostrarToast("Selecione um item cadastrado na lista do estoque.", "info", 3200);
    renderizarPreservandoScroll();
    return;
  }
  editarMaterialItem(itemIndex, materialIndex, material.id);
}

function ajustarTotalPorMaterialPedido(itemIndex, anterior = {}, atual = {}) {
  if (SimplificaOrdersController.adjustItemTotalForMaterial(itensPedido, itemIndex, anterior, atual)) atualizarResumoPedidoSemRender(itemIndex);
}

function editarQuantidadeMaterialItem(itemIndex, materialIndex, quantidade) {
  const materiais = garantirMateriaisItem(itemIndex);
  try {
    const estoqueItem = getMaterialEstoque(materiais[materialIndex]?.materialId);
    const anterior = { ...(materiais[materialIndex] || {}) };
    materiais[materialIndex] = {
      ...anterior,
      quantidade: InventoryService.parseNumberStrict(quantidade, "quantidade usada", { min: 0 }),
      unidade: estoqueItem?.unidade || materiais[materialIndex]?.unidade || "un",
      gramas: 0
    };
    ajustarTotalPorMaterialPedido(itemIndex, anterior, materiais[materialIndex]);
  } catch (erro) {
    ErrorService.notify(erro, { area: "Estoque", action: "Editar quantidade usada" });
  }
}

function editarValorMaterialItem(itemIndex, materialIndex, valor) {
  const materiais = garantirMateriaisItem(itemIndex);
  if (!materiais[materialIndex]) return;
  try {
    const anterior = { ...materiais[materialIndex] };
    materiais[materialIndex].valorUnitario = InventoryService.parseNumberStrict(valor, "valor adicional", { min: 0 });
    ajustarTotalPorMaterialPedido(itemIndex, anterior, materiais[materialIndex]);
  } catch (erro) {
    ErrorService.notify(erro, { area: "Pedido", action: "Editar valor do item de estoque" });
  }
}

function editarGramasItem(itemIndex, materialIndex, gramas) {
  return editarQuantidadeMaterialItem(itemIndex, materialIndex, gramas);
}

function adicionarMaterialProduto(itemIndex) {
  const materiais = garantirMateriaisItem(itemIndex);
  if (materiais.length >= 4) {
    mostrarToast("É possível adicionar até 4 materiais por item.", "info", 3200);
    return;
  }
  abrirPopupMaterialPedido(itemIndex);
}

function preencherMaterialPedidoPopup(termo = "") {
  const busca = normalizarTextoBusca(termo);
  const material = normalizarEstoque().find((item) => normalizarTextoBusca(item.nome) === busca || String(item.id) === String(termo));
  if (!material) return;
  const unidade = document.getElementById("pedidoMaterialUnidade");
  if (unidade) unidade.textContent = material.unidade || "un";
}

function abrirPopupMaterialPedido(itemIndex, materialIndex = null) {
  return SimplificaOrdersHandlers.openOrderMaterialPopup(itemIndex, materialIndex, {
    ensureMaterials: garantirMateriaisItem,
    toast: mostrarToast,
    getStockMaterial: getMaterialEstoque,
    normalizeStock: normalizarEstoque,
    escapeAttr: escaparAttr,
    escapeHtml: escaparHtml,
    formatQuantity: formatarQuantidadeEstoque,
    document,
    promotePopup: promoverPopupParaDialogUiV3,
    closePopup: fecharPopup,
    normalizeText: normalizarTextoBusca,
    parseQuantity: InventoryService.parseNumberStrict,
    adjustItemTotal: ajustarTotalPorMaterialPedido,
    render: renderizarPreservandoScroll,
    notify: ErrorService.notify
  });
}

function removerMaterialProduto(itemIndex, materialIndex) {
  const materiais = garantirMateriaisItem(itemIndex);
  const anterior = { ...(materiais[materialIndex] || {}) };
  if (materiais[materialIndex]) materiais.splice(materialIndex, 1);
  ajustarTotalPorMaterialPedido(itemIndex, anterior, {});
  renderizarPreservandoScroll();
}

function garantirPedidoAbertoParaItemManual() {
  window.__simplificaUiTabs = window.__simplificaUiTabs || {};
  window.__simplificaUiTabs.pedidoEditor = "itens";
  if (telaAtual === "pedido") return;
  telaAnterior = telas.pedidos ? "pedidos" : "dashboard";
  telaAtual = "pedido";
  atualizarHistoricoBrowserApp(true);
  renderApp();
}

function abrirItemManualPedido(event = null) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  event?.stopImmediatePropagation?.();
  adicionarProdutoManual();
  return false;
}

if (typeof window !== "undefined") {
  window.abrirItemManualPedido = abrirItemManualPedido;
}

function adicionarProdutoManual() {
  garantirPedidoAbertoParaItemManual();
  const popup = document.getElementById("popup");
  if (!popup) return;
  popup.innerHTML = `
    <div class="modal-backdrop" role="dialog" aria-modal="true">
      <form class="modal-card" id="manualOrderItemForm">
        <div class="modal-header">
          <h2>Adicionar item manual</h2>
          <button class="icon-button" type="button" data-manual-item-cancel title="Fechar">✕</button>
        </div>
        <p class="muted">Preencha os dados do item. Nada será adicionado sem confirmação.</p>
        <label class="field">
          <span>Descrição do item</span>
          <input id="manualItemNome" placeholder="Ex.: suporte personalizado" required>
        </label>
        <div class="order-item-edit-grid">
          <label class="field compact-field">
            <span>Quantidade</span>
            <input id="manualItemQtd" type="number" min="1" step="1" value="1" required>
          </label>
          <label class="field compact-field">
            <span>Valor unitário (R$)</span>
            <input id="manualItemValor" type="text" inputmode="decimal" placeholder="0,00" required>
          </label>
        </div>
        <div class="actions">
          <button class="btn ghost" type="button" data-manual-item-cancel>Cancelar</button>
          <button class="btn" type="submit">Adicionar item</button>
        </div>
      </form>
    </div>
  `;
  const host = promoverPopupParaDialogUiV3(popup, { title: "Adicionar item manual" });
  const cancelar = () => fecharPopup();
  host.querySelectorAll("[data-manual-item-cancel]").forEach((el) => el.addEventListener("click", cancelar, { once: true }));
  host.querySelector(".modal-backdrop")?.addEventListener("click", (event) => {
    if (event.target === event.currentTarget) cancelar();
  });
  document.getElementById("manualOrderItemForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    event.stopPropagation();
    let qtd = 1;
    let valor = 0;
    try {
      qtd = InventoryService.parseNumberStrict(document.getElementById("manualItemQtd")?.value, "quantidade", { min: 1 });
      valor = InventoryService.parseNumberStrict(document.getElementById("manualItemValor")?.value, "valor unitário", { min: 0.01 });
    } catch (erro) {
      ErrorService.notify(erro, { area: "Pedido", action: "Adicionar item manual" });
      return;
    }
    const item = {
      nome: String(document.getElementById("manualItemNome")?.value || "").trim(),
      tipoImpressao: "FDM",
      qtd,
      valor,
      total: valor * qtd,
      tempoHoras: 0,
      observacao: "",
      materiais: []
    };
    fecharPopup();
    const adicionado = await addCalculatedItemToOrder(item);
    if (adicionado) {
      window.__simplificaUiTabs = window.__simplificaUiTabs || {};
      window.__simplificaUiTabs.pedidoEditor = "itens";
    }
  }, { once: true });
  setTimeout(() => document.getElementById("manualItemNome")?.focus(), 80);
}

async function solicitarSenhaConfirmacaoAdmin(actionLabel = "continuar", options = {}) {
  return new Promise((resolve) => {
    const popup = document.getElementById("popup");
    if (!popup) {
      resolve(null);
      return;
    }
    const validatePassword = typeof options.validatePassword === "function" ? options.validatePassword : null;
    const usarPin = options.credentialType === "pin";
    const invalidMessage = options.invalidMessage || "Senha incorreta. Confira e tente novamente.";
    const inputLabel = usarPin ? "PIN" : "Senha";
    const inputType = "password";
    const inputMode = usarPin ? "numeric" : "text";
    const autocomplete = usarPin ? "one-time-code" : "current-password";
    const inputAttrs = usarPin ? `pattern="[0-9]*" minlength="4" maxlength="12"` : "";
    const helperText = usarPin
      ? "Digite seu PIN de segurança. O campo permanece aberto se houver erro."
      : "Digite sua senha e toque em confirmar. O campo permanece aberto se houver erro.";
    const emailConfirmacao = normalizarEmail(getUsuarioAtual()?.email || usuarioAtualEmail || syncConfig.supabaseEmail || "");
    const dicaEmailConfirmacao = emailConfirmacao ? `Conta ${mascararEmailAcesso(emailConfirmacao)}` : "";

    popup.innerHTML = `
      <div class="modal-backdrop" role="dialog" aria-modal="true">
        <form class="modal-card password-confirm-card" id="adminPasswordConfirmForm" novalidate>
          <div class="modal-header">
            <h2>Confirmar autorização</h2>
            <button class="icon-button" type="button" id="adminPasswordCancelTop" title="Fechar">✕</button>
          </div>
          <p class="muted">Para ${escaparHtml(actionLabel)}, confirme ${usarPin ? "seu PIN de segurança" : "sua senha do aplicativo"}.</p>
          ${dicaEmailConfirmacao ? `<small class="auth-account-hint">${escaparHtml(dicaEmailConfirmacao)}</small>` : ""}
          <label class="field">
            <span>${inputLabel}</span>
            <div class="password-row auth-password-row">
              <input id="adminPasswordConfirmInput" type="${inputType}" autocomplete="${autocomplete}" autocapitalize="none" spellcheck="false" inputmode="${inputMode}" enterkeyhint="done" data-preserve-focus="true" ${inputAttrs} required autofocus>
              <button class="icon-button password-visibility-button" type="button" onclick="alternarSenhaVisivel(this)" title="Mostrar/ocultar ${usarPin ? "PIN" : "senha"}">👁</button>
            </div>
          </label>
          <p class="muted auth-inline-feedback" id="adminPasswordFeedback">${helperText}</p>
          <div class="actions">
            ${usarPin && options.allowPasswordFallback ? `<button class="btn ghost" type="button" id="adminUsePasswordInstead">Usar senha do aplicativo</button>` : ""}
            <button class="btn ghost" type="button" id="adminPasswordCancel">Cancelar</button>
            <button class="btn" type="submit" id="adminPasswordConfirmBtn">Desbloquear</button>
          </div>
        </form>
      </div>
    `;

    let settled = false;
    const finalizar = (valor) => {
      if (settled) return;
      settled = true;
      fecharPopup();
      resolve(valor);
    };
    const host = promoverPopupParaDialogUiV3(popup, { title: "Confirmar autorização", onClose: () => finalizar(null) });
    document.getElementById("adminPasswordConfirmForm")?.addEventListener("submit", async (event) => {
      event.preventDefault();
      const input = document.getElementById("adminPasswordConfirmInput");
      const feedback = document.getElementById("adminPasswordFeedback");
      const botao = document.getElementById("adminPasswordConfirmBtn");
      const senha = input?.value || "";
      if (!String(senha).trim()) {
        if (feedback) feedback.textContent = usarPin ? "Informe seu PIN para continuar." : "Informe sua senha para continuar.";
        focarCampoSenha(input);
        return;
      }
      if (usarPin && !/^\d{4,12}$/.test(String(senha))) {
        if (feedback) feedback.textContent = "O PIN deve ter de 4 a 12 dígitos numéricos.";
        focarCampoSenha(input);
        return;
      }
      if (!validatePassword) {
        finalizar(senha);
        return;
      }
      try {
        if (botao) {
          botao.disabled = true;
          botao.textContent = "Validando...";
        }
        const resultado = await validatePassword(senha);
        const ok = resultado === true || resultado?.ok === true;
        if (ok) {
          finalizar(senha);
          return;
        }
        if (feedback) feedback.textContent = resultado?.message || invalidMessage;
        if (botao) {
          botao.disabled = false;
          botao.textContent = "Desbloquear";
        }
        focarCampoSenha(input);
      } catch (erro) {
        registrarDiagnostico("Auth", "Senha administrativa não validada", erro?.message || String(erro), { silent: true });
        if (feedback) feedback.textContent = invalidMessage;
        if (botao) {
          botao.disabled = false;
          botao.textContent = "Desbloquear";
        }
        focarCampoSenha(input);
      }
    });
    document.getElementById("adminUsePasswordInstead")?.addEventListener("click", () => finalizar("__USE_APP_PASSWORD__"), { once: true });
    document.getElementById("adminPasswordCancel")?.addEventListener("click", () => finalizar(null), { once: true });
    document.getElementById("adminPasswordCancelTop")?.addEventListener("click", () => finalizar(null), { once: true });
    host.querySelector(".modal-backdrop")?.addEventListener("click", (event) => {
      if (event.target === event.currentTarget) {
        event.preventDefault();
        focarCampoSenha("adminPasswordConfirmInput");
      }
    });
    setTimeout(() => focarCampoSenha("adminPasswordConfirmInput"), 80);
  });
}

async function validarSenhaSupabaseUsuarioAtual(senha) {
  return window.SimplificaAuthRemote.validarSenhaSupabaseUsuarioAtual(senha, getAuthRemoteDeps());
}

async function requestSensitiveActionConfirmation({
  actionLabel = "continuar",
  titulo = "",
  mensagem = "",
  confirmar = "Confirmar",
  cancelar = "Cancelar",
  perigo = false,
  exigirConfirmacaoVisual = false,
  permitirPin = true
} = {}) {
  const acao = String(actionLabel || "continuar").trim() || "continuar";

  if (exigirConfirmacaoVisual) {
    const confirmou = await solicitarConfirmacaoAcao({
      titulo: titulo || "Confirmar ação",
      mensagem: mensagem || `Deseja ${acao}?`,
      confirmar,
      cancelar,
      perigo
    });
    if (!confirmou) {
      mostrarToast("Confirmação cancelada.", "info", 2600);
      registrarAuditoria("acao_sensivel_cancelada", { action: acao, etapa: "confirmacao" });
      return false;
    }
  }

  const biometria = await confirmarBiometriaSeDisponivel(`Confirme para ${acao}.`);
  if (biometria.disponivel && biometria.ok) {
    registrarAuditoria("biometria_admin_validada", { action: acao });
    registrarSeguranca("biometria_admin_validada", "sucesso", acao);
    mostrarToast("Autorizado com sucesso.", "sucesso", 2200);
    return true;
  }
  if (biometria.disponivel && !biometria.ok) {
    if (isAndroidNativeApp()) {
      mostrarToast("Confirmação do aparelho cancelada. Ação não autorizada.", "info", 3200);
      registrarAuditoria("acao_sensivel_cancelada", { action: acao, etapa: "credencial_dispositivo" });
      registrarSeguranca("acao_sensivel_cancelada", "erro", acao);
      return false;
    }
    mostrarToast("Biometria cancelada. Confirme com seu PIN ou senha.", "info", 3200);
  }

  if (permitirPin && pinAcoesSensiveisAtivo() && !isAndroidNativeApp()) {
    const pin = await solicitarSenhaConfirmacaoAdmin(acao, {
      credentialType: "pin",
      allowPasswordFallback: true,
      invalidMessage: "PIN incorreto. Alteração não autorizada.",
      validatePassword: async (pinDigitado) => {
        try {
          const ok = await validarPinAcoesSensiveis(pinDigitado);
          if (ok) return { ok: true };
        } catch (erro) {
          return { ok: false, message: erro.message || "PIN temporariamente bloqueado." };
        }
        registrarAuditoria("pin_admin_falhou", { action: acao });
        registrarSeguranca("pin_admin_falhou", "erro", acao);
        return { ok: false, message: "PIN incorreto. Confira e tente novamente." };
      }
    });
    if (pin === null) {
      mostrarToast("Confirmação cancelada.", "info", 2600);
      registrarAuditoria("acao_sensivel_cancelada", { action: acao, etapa: "pin" });
      registrarSeguranca("acao_sensivel_cancelada", "erro", acao);
      return false;
    }
    if (pin !== "__USE_APP_PASSWORD__") {
      registrarAuditoria("pin_admin_validado", { action: acao });
      registrarSeguranca("pin_admin_validado", "sucesso", acao);
      mostrarToast("Autorizado com PIN.", "sucesso", 2200);
      return true;
    }
  }

  const senha = await solicitarSenhaConfirmacaoAdmin(acao, {
    invalidMessage: /excluir|remover|cancelar/i.test(acao)
      ? "Senha incorreta. Ação não autorizada."
      : "Senha incorreta. Alteração não autorizada.",
    validatePassword: async (senhaDigitada) => {
      if (!String(senhaDigitada || "").trim()) {
        registrarAuditoria("senha_admin_falhou", { action: acao, motivo: "senha_vazia" });
        registrarSeguranca("senha_admin_falhou", "erro", acao);
        return { ok: false, message: "Informe sua senha para continuar." };
      }
      try {
        const ok = await validarSenhaSupabaseUsuarioAtual(senhaDigitada);
        if (ok) return { ok: true };
      } catch (erro) {
        registrarDiagnostico("Auth", "Senha administrativa não validada", erro.message, { silent: true });
      }
      registrarAuditoria("senha_admin_falhou", { action: acao });
      registrarSeguranca("senha_admin_falhou", "erro", acao);
      return {
        ok: false,
        message: /excluir|remover|cancelar/i.test(acao)
          ? "Senha incorreta. Ação não autorizada."
          : "Senha incorreta. Alteração não autorizada."
      };
    }
  });
  if (senha === null) {
    mostrarToast("Confirmação cancelada.", "info", 2600);
    registrarAuditoria("acao_sensivel_cancelada", { action: acao, etapa: "senha" });
    registrarSeguranca("acao_sensivel_cancelada", "erro", acao);
    return false;
  }
  registrarAuditoria("senha_admin_validada", { action: acao });
  registrarSeguranca("senha_admin_validada", "sucesso", acao);
  mostrarToast("Autorizado com sucesso.", "sucesso", 2200);
  return true;
}

