function normalizarCalculadoraWidget(widget = {}) {
  return CalculatorDomain.normalizeWidget(widget, { width: window.innerWidth, height: window.innerHeight, mobile: isMobile() });
}

function salvarCalculadoraWidget(valores = {}, salvar = false) {
  const atual = normalizarCalculadoraWidget(appConfig.calculatorWidget || {});
  const proxima = normalizarCalculadoraWidget({ ...atual, ...valores });
  appConfig.calculatorWidget = proxima;

  const janela = document.querySelector(".calc-widget-window");
  if (janela) {
    janela.style.left = `${proxima.x}px`;
    janela.style.top = `${proxima.y}px`;
    janela.style.width = `${proxima.w}px`;
    janela.style.height = `${proxima.h}px`;
  }

  if (salvar) salvarDados();
  return proxima;
}

function normalizarTipoImpressoraCalculadora(tipo = "FDM") {
  return CalculatorDomain.normalizePrinterType(tipo);
}

function numeroCalculadora(valor, fallback = 0, minimo = 0) {
  return CalculatorDomain.normalizeNumber(valor, fallback, minimo, numeroMonetarioPedido);
}

function valorCampoCalculadora(id, fallback = "") {
  const campo = document.getElementById(id);
  if (!campo) return fallback;
  return campo.value === undefined || campo.value === null ? fallback : String(campo.value);
}

function getConfiguracaoCalculadora() {
  const salvo = appConfig.calculatorDefaults && typeof appConfig.calculatorDefaults === "object" ? appConfig.calculatorDefaults : {};
  const tipo = normalizarTipoImpressoraCalculadora(salvo.printerType || appConfig.defaultPrinterType || "FDM");
  const modeloFrequente = valorFrequenteUso("impressora_usada", "impressora", 40);
  const modeloSalvo = modeloFrequente || salvo.printerModel || appConfig.defaultPrinterModel || "Ender 3";
  const modeloValido = printers[modeloSalvo]?.tipo === tipo
    ? modeloSalvo
    : Object.keys(printers).find((nome) => printers[nome].tipo === tipo) || "Ender 3";
  const impressora = printers[modeloValido] || printers["Ender 3"];
  const materialFrequente = valorFrequenteUso("material_usado", "materialId", 40);
  const materialSalvo = materialFrequente || salvo.materialId || appConfig.defaultMaterial || "";
  const materialIdValido = materialSalvo && getMaterialEstoque(materialSalvo) ? materialSalvo : "";
  return {
    printerType: tipo,
    printerModel: modeloValido,
    materialId: materialIdValido,
    peso: calculatorDraftState.peso,
    tempoMinutos: calculatorDraftState.tempoMinutos,
    filamento: salvo.filamento ?? appConfig.defaultFilamentCost ?? 150,
    tempo: calculatorDraftState.tempo,
    quantidade: calculatorDraftState.quantity || salvo.quantidade || 2,
    energia: salvo.energia ?? appConfig.defaultEnergy ?? 0.85,
    consumo: salvo.consumo ?? impressora.consumo ?? "",
    custoHora: salvo.custoHora ?? impressora.custo ?? "",
    margem: salvo.margem ?? appConfig.defaultMargin ?? 100,
    taxaExtra: "",
    taxaExtraMode: appConfig.calcExtraFeeMode || "percent",
    taxaExtraPercent: Number(appConfig.calcExtraFeePercent) || 0,
    taxaExtraValue: Number(appConfig.calcExtraFeeValue) || 0,
    nomeItem: salvo.nomeItem || ""
  };
}

function salvarConfiguracaoCalculadora(persistir = true) {
  const atual = getConfiguracaoCalculadora();
  const printer = document.getElementById("printer")?.value || atual.printerModel;
  const tipo = normalizarTipoImpressoraCalculadora(document.getElementById("printerType")?.value || printers[printer]?.tipo || atual.printerType);
  const proxima = {
    printerType: tipo,
    printerModel: printer,
    materialId: "",
    peso: "",
    filamento: numeroCalculadora(valorCampoCalculadora("filamento", atual.filamento), atual.filamento),
    tempo: "",
    tempoMinutos: "",
    quantidade: numeroCalculadora(valorCampoCalculadora("quantidade", atual.quantidade), atual.quantidade, 1),
    energia: numeroCalculadora(valorCampoCalculadora("energia", atual.energia), atual.energia),
    consumo: numeroCalculadora(valorCampoCalculadora("consumo", atual.consumo), atual.consumo),
    custoHora: numeroCalculadora(valorCampoCalculadora("custoHora", atual.custoHora), atual.custoHora),
    margem: numeroCalculadora(valorCampoCalculadora("margem", atual.margem), atual.margem),
    taxaExtra: "",
    nomeItem: valorCampoCalculadora("nomeItem", atual.nomeItem).trim()
  };
  appConfig.calculatorDefaults = proxima;
  appConfig.defaultPrinterType = proxima.printerType;
  appConfig.defaultPrinterModel = proxima.printerModel;
  appConfig.defaultFilamentCost = proxima.filamento;
  appConfig.defaultEnergy = proxima.energia;
  appConfig.defaultMargin = proxima.margem;
  if (persistir) salvarDados();
  return proxima;
}

function obterPerfilAtivoCalculadora(config = getConfiguracaoCalculadora()) {
  const impressora = printers[config.printerModel] || printers["Ender 3"];
  const material = getMaterialEstoque(config.materialId);
  const materialNome = material?.nome || valorFrequenteUso("material_usado", "materialNome", 40) || "PLA";
  const ultima = normalizarUsoInteligente(usageLearning).events
    .filter((evento) => evento.tipo === "calculadora_aberta" || evento.tipo === "impressora_usada" || evento.tipo === "material_usado")
    .slice(-1)[0];
  const ultimaData = ultima?.at ? new Date(ultima.at) : null;
  const ultimoUso = ultimaData && !Number.isNaN(ultimaData.getTime())
    ? `Último usado ${ultimaData.toLocaleDateString("pt-BR")} às ${ultimaData.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}`
    : "Pronto para novo cálculo";
  return {
    nome: config.printerModel || "Ender 3",
    tipo: impressora?.tipo || config.printerType || "FDM",
    materialNome,
    camada: appConfig.defaultLayerHeight || "0.20mm",
    bico: appConfig.defaultNozzle || "0.4mm",
    ultimoUso
  };
}

function renderDicaSmartCalculadora(config = getConfiguracaoCalculadora()) {
  if (!sugestoesInteligentesAtivas() || usageLearning?.dismissed?.calcSmartTip === hojeIsoData()) return "";
  const impressoraFrequente = valorFrequenteUso("impressora_usada", "impressora", 40);
  let texto = "";
  let acao = "";
  let label = "";
  if (impressoraFrequente && impressoraFrequente !== config.printerModel) {
    texto = `Você costuma usar ${impressoraFrequente}`;
    acao = `aplicarPerfilCalculadora('${escaparAttr(impressoraFrequente)}')`;
    label = "Aplicar perfil";
  } else if (Number(config.margem) < Number(appConfig.minimumRecommendedMargin || 60)) {
    texto = "Margem abaixo do recomendado";
    acao = "abrirConfiguracoesCalculadora()";
    label = "Ajustar margem";
  } else {
    texto = "Use peso e tempo para ver o valor em tempo real";
    acao = "agendarCalculoTempoReal()";
    label = "Atualizar";
  }
  return `
    <div class="calc-smart-tip">
      <span class="calc-tip-icon">${renderUiIcon("preferencias")}</span>
      <div>
        <strong>Dica inteligente</strong>
        <small>${escaparHtml(texto)}</small>
      </div>
      <button class="btn ghost" type="button" onclick="${acao}">${escaparHtml(label)}</button>
      <button class="icon-button" type="button" onclick="dispensarDicaCalculadora()" title="Dispensar">×</button>
    </div>
  `;
}

function getEstadoTaxaExtraCalculadora() {
  const modo = String(appConfig.calcExtraFeeMode || "percent") === "manual" ? "manual" : "percent";
  const percent = Math.max(0, Number(appConfig.calcExtraFeePercent) || 0);
  const value = Math.max(0, Number(appConfig.calcExtraFeeValue) || 0);
  return { modo, percent, value };
}

function valorExibidoTaxaExtraCalculadora(estado = getEstadoTaxaExtraCalculadora()) {
  return CalculatorDomain.getDisplayedExtraFee({ mode: estado.modo, percent: estado.percent, value: estado.value });
}

function atualizarVisualTaxaExtraCalculadora(opcoes = {}) {
  const estado = getEstadoTaxaExtraCalculadora();
  const campo = document.getElementById("taxaExtra");
  const unidade = document.getElementById("taxaExtraUnit");
  const slider = document.getElementById("taxaExtraPercentRange");
  const personalizada = document.querySelector(".calc-custom-fee-toggle input");
  if (campo) {
    const preservarDigitacao = opcoes.preservarDigitacao === true || (estado.modo === "manual" && document.activeElement === campo);
    if (!preservarDigitacao) {
      campo.value = valorExibidoTaxaExtraCalculadora(estado) ? Number(valorExibidoTaxaExtraCalculadora(estado)).toFixed(2).replace(".", ",") : "";
    }
    campo.readOnly = false;
    campo.max = estado.modo === "manual" ? "" : "100";
    campo.step = estado.modo === "manual" ? "0.01" : "1";
    campo.classList.toggle("is-manual-fee", estado.modo === "manual");
  }
  if (unidade) unidade.textContent = estado.modo === "manual" ? "R$" : "%";
  if (slider) {
    slider.value = String(estado.percent);
    slider.disabled = estado.modo === "manual";
  }
  if (personalizada) personalizada.checked = estado.modo === "manual";
  document.querySelectorAll("[data-extra-fee-mode]").forEach((botao) => {
    const modoBotao = botao.getAttribute("data-extra-fee-mode");
    const percentBotao = Number(botao.getAttribute("data-extra-fee-percent") || 0);
    botao.classList.toggle("active", modoBotao === estado.modo && (modoBotao === "manual" || percentBotao === estado.percent));
  });
}

function selecionarTaxaExtraPercentual(percent = 0) {
  appConfig.calcExtraFeeMode = "percent";
  appConfig.calcExtraFeePercent = Math.max(0, Number(percent) || 0);
  salvarDados();
  atualizarVisualTaxaExtraCalculadora();
  agendarCalculoTempoReal();
}

function selecionarTaxaExtraManual() {
  appConfig.calcExtraFeeMode = "manual";
  appConfig.calcExtraFeeValue = Math.max(0, Number(appConfig.calcExtraFeeValue) || Number(appConfig.defaultExtraFee) || 0);
  salvarDados();
  atualizarVisualTaxaExtraCalculadora();
  setTimeout(() => {
    const campo = document.getElementById("taxaExtra");
    if (!campo) return;
    campo.readOnly = false;
    campo.focus();
    campo.select?.();
  }, 30);
  agendarCalculoTempoReal();
}

function atualizarTaxaExtraManual() {
  appConfig.calcExtraFeeMode = "manual";
  appConfig.calcExtraFeeValue = numeroCalculadora(document.getElementById("taxaExtra")?.value, 0, 0);
  salvarDados();
  atualizarVisualTaxaExtraCalculadora({ preservarDigitacao: true });
  agendarCalculoTempoReal();
}

function calcularTaxaExtraAplicada(valorComercialBase = 0) {
  const estado = getEstadoTaxaExtraCalculadora();
  const fee = CalculatorDomain.calculateExtraFee({ base: valorComercialBase, mode: estado.modo, percent: estado.percent, value: estado.value });
  return { valor: fee.value, rotulo: fee.label, modo: fee.mode };
}

function renderListaPedidosPwa(args = {}) {
  return SimplificaOrdersRenderer.renderOrderPwaList(args, {
    isDetailClosed: () => !!window.__pedidoDetalheFechado,
    renderDetalhePedido,
    renderContextualAdvancedToggle,
    renderUiIcon,
    escaparAttr,
    escaparHtml,
    searchValue: () => window.__pedidosBusca,
    isContextAdvancedVisible,
    renderPedidoStatusSelect
  });
}
function renderResumoCalculo(calculo = ultimoCalculo) {
  if (!calculo) {
    return `
      <div class="calc-summary-card muted-summary">
        <div class="calc-summary-head">
          <strong>${renderUiIcon("calculadora")} Resumo do cálculo</strong>
          <span>Preencha peso e tempo</span>
        </div>
        <p class="muted">O valor final será atualizado automaticamente.</p>
      </div>
    `;
  }
  const margem = Number(document.getElementById("margem")?.value || appConfig.defaultMargin || 0) || 0;
  const margemMinima = Number(appConfig.minimumRecommendedMargin || 60) || 60;
  const baseProduto = Math.max(0, Number(calculo.baseProduto ?? calculo.custoTotal) || 0);
  const lucroProduto = Math.max(0, Number(calculo.lucroProduto ?? ((Number(calculo.precoSemTaxa) || 0) - baseProduto)) || 0);
  const valorProduto = Math.max(0, Number(calculo.valorProduto ?? calculo.precoSemTaxa) || 0);
  const taxaExtra = Math.max(0, Number(calculo.taxaExtra) || 0);
  const totalFinal = Math.max(0, Number(calculo.totalFinal ?? calculo.precoTotal) || 0);
  const ajusteArredondamento = Math.max(0, Number(calculo.ajusteArredondamento) || 0);
  const quantidadeLote = Math.max(1, Number(calculo.qtd) || 1);
  const valorUnitario = Math.max(0, Number(calculo.preco) || totalFinal);
  const status = valorProduto < baseProduto
    ? "Preço abaixo do custo estimado"
    : margem < margemMinima
      ? "Margem abaixo do recomendado"
      : "Margem dentro do recomendado";
  return `
    <div class="calc-summary-card">
      <div class="calc-summary-head">
        <strong>${renderUiIcon("calculadora")} Resumo do cálculo</strong>
        <button class="calc-summary-toggle" type="button" onclick="alternarResumoCalculadora(this)" title="Ver detalhes do cálculo" aria-expanded="false" aria-controls="calcSummaryLines">Toque para ver detalhes <span class="expand-toggle-indicator" aria-hidden="true"></span></button>
      </div>
      <div class="calc-summary-lines is-collapsed" id="calcSummaryLines">
        <span>Peso total</span><strong>${Number((calculo.pesoTotal ?? calculo.peso) || 0).toLocaleString("pt-BR", { maximumFractionDigits: 2 })} g</strong>
        <span>Tempo de máquina</span><strong>${CalculatorDomain.formatMinutes(calculo.tempoTotalMinutos ?? Math.round((Number(calculo.tempo) || 0) * 60)).label}</strong>
        ${calculo.impressaoLote ? `<span>Quantidade</span><strong>${quantidadeLote} un.</strong><span>Modo do lote</span><strong>${calculo.modoLote === "whole_batch" ? "Lote inteiro" : "Dados por peça"}</strong>` : ""}
        <span>Custo do material</span><strong>${formatarMoeda(calculo.custoMaterial)}</strong>
        <span>Custo de impressão</span><strong>${formatarMoeda((Number(calculo.custoEnergia) || 0) + (Number(calculo.custoMaquina) || 0))}</strong>
        <span>Base do produto</span><strong>${formatarMoeda(baseProduto)}</strong>
        <span>Margem de lucro (${margem}%)</span><strong>${formatarMoeda(lucroProduto)}</strong>
        <span>Valor do produto</span><strong>${formatarMoeda(valorProduto)}</strong>
        ${taxaExtra > 0 ? `<span>Taxa extra${calculo.taxaExtraRotulo ? ` (${escaparHtml(calculo.taxaExtraRotulo)})` : ""}</span><strong>${formatarMoeda(taxaExtra)}</strong>` : ""}
        ${ajusteArredondamento > 0 ? `<span>Arredondamento</span><strong>${formatarMoeda(ajusteArredondamento)}</strong>` : ""}
        ${calculo.impressaoLote ? `<span>Quantidade no lote</span><strong>${quantidadeLote} un.</strong><span>Valor unitário calculado</span><strong>${formatarMoeda(valorUnitario)}</strong>` : ""}
      </div>
      <label class="field inline-result-field">
        <span>${calculo.impressaoLote ? "Valor unitário ajustável" : "Preço final ajustável"}</span>
        <input id="valorManualItem" type="text" inputmode="decimal" value="${escaparAttr((Number(calculo.preco) || 0).toFixed(2).replace('.', ','))}" placeholder="0,00">
      </label>
      <div class="calc-final-row">
        <span>${calculo.impressaoLote ? "Valor total do lote" : "Valor estimado"}</span>
        <strong>${formatarMoeda(totalFinal)}</strong>
      </div>
      <small class="calc-margin-status">${escaparHtml(status)}</small>
    </div>
  `;
}

function formatarTempoCalculadora(horas = 0, minutos = 0) {
  return window.CalculatorDomain.formatTimeInput(horas, minutos);
}

function sincronizarTempoFormatadoCalculadora(valor = "") {
  const tempo = CalculatorDomain.parseFormattedTime(valor);
  if (!tempo) return false;
  const campoHoras = document.getElementById("tempo");
  const campoMinutos = document.getElementById("tempoMinutos");
  if (campoHoras) campoHoras.value = String(tempo.hours);
  if (campoMinutos) campoMinutos.value = String(tempo.minutes);
  agendarCalculoTempoReal();
  return true;
}

function normalizarCampoTempoCalculadora() {
  const campo = document.getElementById("tempoFormato");
  if (!campo) return;
  if (!sincronizarTempoFormatadoCalculadora(campo.value)) {
    campo.value = formatarTempoCalculadora(
      document.getElementById("tempo")?.value,
      document.getElementById("tempoMinutos")?.value
    );
    mostrarToast("Use o formato horas:minutos, por exemplo 3:47.", "aviso", 2800);
    return;
  }
  campo.value = formatarTempoCalculadora(
    document.getElementById("tempo")?.value,
    document.getElementById("tempoMinutos")?.value
  );
}

function sincronizarTempoSeparadoCalculadora() {
  const campoHoras = document.getElementById("tempo");
  const campoMinutos = document.getElementById("tempoMinutos");
  const campoFormato = document.getElementById("tempoFormato");
  const horas = String(campoHoras?.value ?? "");
  const minutos = String(campoMinutos?.value ?? "");
  if (campoFormato) campoFormato.value = formatarTempoCalculadora(horas, minutos);
  calculatorDraftState.tempo = horas;
  calculatorDraftState.tempoMinutos = minutos;
  agendarCalculoTempoReal();
}

function normalizarTempoSeparadoCalculadora() {
  const campoHoras = document.getElementById("tempo");
  const campoMinutos = document.getElementById("tempoMinutos");
  if (!campoHoras || !campoMinutos) return;
  const possuiValor = String(campoHoras.value || "").trim() || String(campoMinutos.value || "").trim();
  if (!possuiValor) return sincronizarTempoSeparadoCalculadora();
  const normalizado = CalculatorDomain.formatMinutes(CalculatorDomain.toMinutes(campoHoras.value, campoMinutos.value));
  campoHoras.value = normalizado.hours ? String(normalizado.hours) : "";
  campoMinutos.value = normalizado.minutes ? String(normalizado.minutes) : "";
  sincronizarTempoSeparadoCalculadora();
}

function concluirTempoCalculadora(event = null) {
  if (event?.key && event.key !== "Enter") return;
  if (event?.key === "Enter") event.preventDefault();
  normalizarTempoSeparadoCalculadora();
  ocultarTecladoCalculadora();
}

function ocultarTecladoCalculadora() {
  const ativo = document.activeElement;
  if (ativo instanceof HTMLElement && ativo.closest?.("[data-ui3-screen=\"calculadora\"]")) ativo.blur();
  atualizarBarraTecladoCalculadora(false);
}

function atualizarBarraTecladoCalculadora(visivel = null) {
  const barra = document.getElementById("calcKeyboardResultBar");
  if (!barra) return;
  const foco = document.activeElement;
  const deveExibir = visivel === null
    ? !!(foco instanceof HTMLElement && foco.matches("input, textarea, select") && foco.closest?.("[data-ui3-screen=\"calculadora\"]"))
    : visivel === true;
  barra.hidden = !deveExibir;
  const valor = barra.querySelector("[data-calc-keyboard-total]");
  if (valor) valor.textContent = ultimoCalculo ? formatarMoeda(ultimoCalculo.totalFinal ?? ultimoCalculo.precoTotal ?? ultimoCalculo.preco) : "Preencha peso e tempo";
}

function prepararEdicaoCalculadora(campo) {
  if (!campo) return;
  setTimeout(() => {
    campo.scrollIntoView?.({ block: "center", inline: "nearest", behavior: "smooth" });
    atualizarBarraTecladoCalculadora(true);
  }, 180);
}

function configurarInteracaoCalculadoraMobile() {
  return window.SimplificaAppDomainEvents.configureCalculatorMobileInteraction(getAppDomainEventsDeps());
}

function getModoLoteCalculadora() {
  const modo = document.querySelector('input[name="calcBatchMode"]:checked')?.value === "whole_batch" ? "whole_batch" : "per_piece";
  calculatorDraftState.batchMode = modo;
  return modo;
}

function ajustarQuantidadeLoteCalculadora(delta = 0) {
  const campo = document.getElementById("quantidade");
  if (!campo) return;
  campo.value = String(Math.max(2, Math.min(999, Math.floor(Number(campo.value) || 2) + Number(delta || 0))));
  calculatorDraftState.quantity = Number(campo.value);
  atualizarResumoLoteCalculadora();
  agendarCalculoTempoReal();
}

function atualizarResumoLoteCalculadora() {
  return window.SimplificaInventoryScreenRenderer.atualizarResumoLoteCalculadora(getInventoryScreenRendererDeps());
}

function alternarTaxaExtraAtiva(ativa = false) {
  calculatorDraftState.extraFeeActive = ativa === true;
  const campos = document.getElementById("calcExtraFeeFields");
  if (campos) campos.hidden = !ativa;
  if (!ativa) {
    appConfig.calcExtraFeePercent = 0;
    appConfig.calcExtraFeeValue = 0;
  }
  atualizarVisualTaxaExtraCalculadora();
  estabilizarViewportCalculadora();
  agendarCalculoTempoReal();
}

function selecionarTipoTaxaExtraCalculadora(tipo = "percent") {
  appConfig.calcExtraFeeMode = tipo === "fixed" ? "manual" : "percent";
  salvarDados();
  atualizarVisualTaxaExtraCalculadora();
  estabilizarViewportCalculadora();
  agendarCalculoTempoReal();
}

function estabilizarViewportCalculadora() {
  const panel = document.querySelector(".mobile-panel-calculator");
  const content = panel?.querySelector(".calculator-panel-content");
  const resetar = () => {
    [document.documentElement, document.body, panel, content].filter(Boolean).forEach((elemento) => {
      if (elemento.scrollLeft) elemento.scrollLeft = 0;
    });
  };
  resetar();
  requestAnimationFrame(resetar);
}

function atualizarTaxaExtraControle(valor = 0) {
  const estado = getEstadoTaxaExtraCalculadora();
  const numero = Math.max(0, numeroCalculadora(valor, 0, 0));
  if (estado.modo === "manual") {
    appConfig.calcExtraFeeValue = numero;
  } else {
    appConfig.calcExtraFeePercent = Math.min(100, numero);
  }
  salvarDados();
  atualizarVisualTaxaExtraCalculadora({ preservarDigitacao: true });
  agendarCalculoTempoReal();
}

function atualizarTaxaExtraPeloSlider(valor = 0) {
  appConfig.calcExtraFeeMode = "percent";
  appConfig.calcExtraFeePercent = Math.max(0, Math.min(100, Number(valor) || 0));
  salvarDados();
  atualizarVisualTaxaExtraCalculadora();
  agendarCalculoTempoReal();
}

function alternarTaxaExtraPersonalizada(ativada = false) {
  if (ativada) selecionarTaxaExtraManual();
  else selecionarTaxaExtraPercentual(Number(appConfig.calcExtraFeePercent) || 0);
}

function renderCalculadoraConteudo() {
  const config = getConfiguracaoCalculadora();
  const perfil = obterPerfilAtivoCalculadora(config);
  const taxaEstado = getEstadoTaxaExtraCalculadora();
  const emPedido = calculadoraModoPedido === true;
  const acaoPrincipal = emPedido ? "Adicionar ao pedido" : "Criar pedido";
  return `
    <div class="calc-toolbar">
      <button class="icon-button" type="button" onclick="voltarTela()" title="Voltar">‹</button>
      <strong>Calculadora</strong>
      <button class="icon-button" type="button" onclick="abrirConfiguracoesCalculadora()" title="Configurações" aria-label="Configurações">${renderUiIcon("config")}</button>
    </div>

    <section class="calc-active-profile">
      <div class="calc-printer-art">${renderUiIcon("producao")}</div>
      <div>
        <span>Perfil ativo</span>
        <strong>${escaparHtml(perfil.nome)}</strong>
        <small>${escaparHtml(perfil.camada)} • ${escaparHtml(perfil.bico)}</small>
        <em>${escaparHtml(perfil.ultimoUso)}</em>
      </div>
    </section>


    <section class="calc-input-panel">
      <div class="calc-section-title">
        <strong>${renderUiIcon("producao")} Dados da impressão</strong>
        <button class="btn ghost" type="button" onclick="limparCalculo()">Limpar</button>
      </div>
      <input id="printerType" type="hidden" value="${escaparAttr(config.printerType)}">
      ${isProfissionalMode() ? `<label class="field calc-printer-selector"><span>Impressora</span><select id="printer"></select><small>Usa potência e custo por hora do cadastro.</small></label>` : `<select id="printer" hidden></select>`}
      <input id="filamento" type="hidden" value="${escaparAttr(config.filamento)}">
      <input id="energia" type="hidden" value="${escaparAttr(config.energia)}">
      <input id="consumo" type="hidden" value="${escaparAttr(config.consumo)}">
      <input id="custoHora" type="hidden" value="${escaparAttr(config.custoHora)}">
      <input id="margem" type="hidden" value="${escaparAttr(config.margem)}">

      <div class="calc-modern-grid">
        <label class="field calc-field-card calc-weight-card">
          <span>Peso</span>
          <input id="peso" type="number" inputmode="decimal" min="0" step="0.01" placeholder="120" value="${escaparAttr(config.peso)}" onfocus="prepararEdicaoCalculadora(this)" oninput="calculatorDraftState.peso=this.value;agendarCalculoTempoReal()">
          <i>g</i>
        </label>
        <label class="field calc-field-card calc-time-card"><span>Horas</span><input id="tempo" type="number" inputmode="numeric" min="0" step="1" placeholder="2" value="${escaparAttr(Number(config.tempo) > 0 ? config.tempo : "")}" onfocus="prepararEdicaoCalculadora(this)" oninput="sincronizarTempoSeparadoCalculadora()" onblur="normalizarTempoSeparadoCalculadora()"><i>h</i></label>
        <label class="field calc-field-card calc-minutes-card"><span>Minutos</span><input id="tempoMinutos" type="number" inputmode="numeric" enterkeyhint="done" min="0" max="59" step="1" placeholder="30" value="${escaparAttr(Number(config.tempoMinutos) > 0 ? config.tempoMinutos : "")}" onfocus="prepararEdicaoCalculadora(this)" oninput="sincronizarTempoSeparadoCalculadora()" onblur="concluirTempoCalculadora()" onkeydown="concluirTempoCalculadora(event)"><i>min</i></label>
        <input id="tempoFormato" type="hidden" value="${escaparAttr(formatarTempoCalculadora(config.tempo, config.tempoMinutos))}">
        <section class="calc-option-block wide" data-calc-option="batch">
          <label class="calc-option-header">
            <input id="impressaoLote" type="checkbox" ${calculatorDraftState.batchActive ? "checked" : ""} onchange="alternarImpressaoLote(this.checked)">
            <span><strong>Calcular várias peças</strong><small>Define quantidade e consumo total do lote.</small></span>
          </label>
          <div class="calc-option-fields" id="calcBatchFields" ${calculatorDraftState.batchActive ? "" : "hidden"}>
            <div class="calc-stepper-row"><span>Quantidade</span><div><button type="button" onclick="ajustarQuantidadeLoteCalculadora(-1)" aria-label="Diminuir quantidade">−</button><input id="quantidade" type="number" inputmode="numeric" min="2" max="999" step="1" placeholder="5" value="${escaparAttr(Number(calculatorDraftState.quantity) >= 2 ? calculatorDraftState.quantity : "")}" onfocus="prepararEdicaoCalculadora(this)" oninput="calculatorDraftState.quantity=this.value;atualizarResumoLoteCalculadora();agendarCalculoTempoReal()"><small>unidades</small><button type="button" onclick="ajustarQuantidadeLoteCalculadora(1)" aria-label="Aumentar quantidade">+</button></div></div>
            <div class="calc-segmented" role="radiogroup" aria-label="Interpretação dos dados do lote">
              <label><input type="radio" name="calcBatchMode" value="per_piece" ${calculatorDraftState.batchMode !== "whole_batch" ? "checked" : ""} onchange="calculatorDraftState.batchMode='per_piece';atualizarResumoLoteCalculadora();agendarCalculoTempoReal()"><span>Dados por peça</span></label>
              <label><input type="radio" name="calcBatchMode" value="whole_batch" ${calculatorDraftState.batchMode === "whole_batch" ? "checked" : ""} onchange="calculatorDraftState.batchMode='whole_batch';atualizarResumoLoteCalculadora();agendarCalculoTempoReal()"><span>Lote inteiro</span></label>
            </div>
            <div id="calcBatchSummary" class="calc-batch-summary"><strong>Resumo do lote</strong><span>Preencha os dados da impressão.</span></div>
          </div>
        </section>
        <section class="calc-option-block wide" data-calc-option="extra-fee">
          <label class="calc-option-header">
            <input id="taxaExtraAtiva" type="checkbox" ${calculatorDraftState.extraFeeActive ? "checked" : ""} onchange="alternarTaxaExtraAtiva(this.checked)">
            <span><strong>Adicionar taxa extra</strong><small>Acréscimo para acabamento, urgência ou complexidade.</small></span>
          </label>
          <div class="calc-option-fields" id="calcExtraFeeFields" ${calculatorDraftState.extraFeeActive ? "" : "hidden"}>
            <div class="calc-segmented" role="radiogroup" aria-label="Tipo da taxa extra">
              <label><input type="radio" name="calcExtraFeeType" value="percent" ${taxaEstado.modo === "percent" ? "checked" : ""} onchange="selecionarTipoTaxaExtraCalculadora('percent')"><span>Percentual (%)</span></label>
              <label><input type="radio" name="calcExtraFeeType" value="fixed" ${taxaEstado.modo === "manual" ? "checked" : ""} onchange="selecionarTipoTaxaExtraCalculadora('fixed')"><span>Valor fixo (R$)</span></label>
            </div>
            <div class="calc-fee-stepper"><button type="button" onclick="atualizarTaxaExtraControle(Math.max(0, numeroMonetarioPedido(document.getElementById('taxaExtra').value, 0) - 1))" aria-label="Diminuir taxa">−</button><label><i id="taxaExtraUnit">${taxaEstado.modo === "manual" ? "R$" : "%"}</i><input id="taxaExtra" type="text" inputmode="decimal" placeholder="10" value="${escaparAttr(String(valorExibidoTaxaExtraCalculadora(taxaEstado) || "").replace('.', ','))}" onfocus="prepararEdicaoCalculadora(this)" oninput="atualizarTaxaExtraControle(this.value)"></label><button type="button" onclick="atualizarTaxaExtraControle(numeroMonetarioPedido(document.getElementById('taxaExtra').value, 0) + 1)" aria-label="Aumentar taxa">+</button></div>
          </div>
        </section>
      </div>
      <label class="field">
        <span>Nome do item</span>
        <input id="nomeItem" placeholder="Ex.: suporte personalizado" value="${escaparAttr(config.nomeItem)}" onfocus="prepararEdicaoCalculadora(this)" oninput="salvarConfiguracaoCalculadora(false)">
      </label>
      <label class="field">
        <span>Observações do cálculo</span>
        <textarea id="observacoesCalculo" rows="2" placeholder="Detalhes opcionais para enviar ao pedido" onfocus="prepararEdicaoCalculadora(this)"></textarea>
      </label>
    </section>

    <div id="res" class="result-box calc-result-modern">${renderResumoCalculo()}</div>
    <div id="calcKeyboardResultBar" class="calc-keyboard-result-bar" hidden aria-live="polite">
      <span>Preço estimado</span><strong data-calc-keyboard-total>Preencha peso e tempo</strong>
      <button class="btn ghost" type="button" onclick="ocultarTecladoCalculadora()">Ocultar teclado</button>
    </div>

    <div class="calc-primary-actions">
      <button class="btn calc-main-action" id="confirmCalculatorItemButton" onclick="adicionarItem()" ${itemAdicionandoPedido ? "disabled" : ""}>
        ${renderUiIcon("pedido")} <span>${itemAdicionandoPedido ? "Adicionando item..." : acaoPrincipal}</span>
      </button>
      <button class="btn ghost calc-save-action" onclick="salvarOrcamento()">${renderIconeAcaoPedido("▣", "Salvar")} Salvar item</button>
    </div>

    <div class="calc-secondary-actions">
      ${renderAcaoPedidoCompacta("☘", "WhatsApp", "enviarWhatsCalculadora()", "ghost")}
      ${renderAcaoPedidoCompacta("▣", "PDF", "gerarPdfCalculadora()", "ghost")}
      ${renderAcaoPedidoCompacta("🗑", "Excluir", "limparCalculo()", "danger")}
    </div>
  `;
}

function dispensarDicaCalculadora() {
  usageLearning = normalizarUsoInteligente({
    ...usageLearning,
    dismissed: {
      ...(usageLearning?.dismissed || {}),
      calcSmartTip: hojeIsoData()
    }
  });
  salvarUsoInteligenteLocal();
  renderizarPreservandoScroll();
}

function getQuickActionById(id) {
  return QUICK_ACTIONS_CATALOG.find((acao) => acao.id === String(id || "")) || null;
}

function quickActionDisponivel(acao = {}) {
  if (!acao || QUICK_ACTIONS_DANGEROUS.has(acao.id)) return false;
  if (acao.requiresOrder && !pedidos.length) return false;
  if (acao.tela && !shouldShowMenuItem(acao)) return false;
  if (acao.tela && !canAccessScreen(acao.tela)) return false;
  return true;
}

function getEventosAtalhosRapidos(limite = 120) {
  return normalizarUsoInteligente(usageLearning).events
    .filter((evento) => evento.tipo === "atalho_acionado" && evento.actionId)
    .slice(-limite);
}

function pontuarAtalhoRapido(id) {
  const agora = Date.now();
  const eventos = getEventosAtalhosRapidos(180).filter((evento) => evento.actionId === id);
  const seteDias = 7 * 24 * 60 * 60 * 1000;
  const trintaDias = 30 * 24 * 60 * 60 * 1000;
  return eventos.reduce((score, evento) => {
    const idade = agora - (Date.parse(evento.at || "") || 0);
    const recente7 = idade <= seteDias ? 6 : 0;
    const recente30 = idade <= trintaDias ? 2 : 0;
    const recencia = idade <= 24 * 60 * 60 * 1000 ? 3 : idade <= seteDias ? 1 : 0;
    return score + 1 + recente7 + recente30 + recencia;
  }, 0);
}

function calcularOrdemAtalhosRapidos() {
  const eventos = getEventosAtalhosRapidos();
  const temHistorico = eventos.length >= QUICK_ACTION_REORDER_MIN_USES;
  const padraoIndex = new Map(QUICK_ACTIONS_DEFAULT_ORDER.map((id, index) => [id, index]));
  const disponiveis = QUICK_ACTIONS_CATALOG.filter(quickActionDisponivel);
  const ordenados = [...disponiveis].sort((a, b) => {
    if (!temHistorico) {
      return (padraoIndex.get(a.id) ?? 99) - (padraoIndex.get(b.id) ?? 99);
    }
    const diff = pontuarAtalhoRapido(b.id) - pontuarAtalhoRapido(a.id);
    if (diff) return diff;
    return (padraoIndex.get(a.id) ?? 99) - (padraoIndex.get(b.id) ?? 99);
  });
  const basePadrao = QUICK_ACTIONS_DEFAULT_ORDER.filter((id) => disponiveis.some((acao) => acao.id === id));
  const ids = (temHistorico ? ordenados.map((acao) => acao.id) : [...basePadrao, ...ordenados.map((acao) => acao.id)])
    .filter((id, index, lista) => lista.indexOf(id) === index);
  return ids;
}

function getOrdemAtalhosRapidos() {
  const uso = normalizarUsoInteligente(usageLearning);
  const hoje = hojeIsoData();
  const precisaAtualizar = !uso.shortcutOrder.length
    || uso.shortcutOrderDate !== hoje
    || Number(uso.shortcutUsageSinceOrder || 0) >= QUICK_ACTION_REORDER_MIN_USES;
  if (!precisaAtualizar) return uso.shortcutOrder;

  const proximaOrdem = calcularOrdemAtalhosRapidos();
  usageLearning = normalizarUsoInteligente({
    ...uso,
    shortcutOrder: proximaOrdem,
    shortcutOrderDate: hoje,
    shortcutUsageSinceOrder: 0
  });
  salvarUsoInteligenteLocal();
  return proximaOrdem;
}

function getAtalhosRapidosOrdenados(limite = 5) {
  const uso = normalizarUsoInteligente(usageLearning);
  const pins = uso.shortcutPins.filter((id) => quickActionDisponivel(getQuickActionById(id)));
  const ordem = getOrdemAtalhosRapidos().filter((id) => quickActionDisponivel(getQuickActionById(id)));
  return [...pins, ...ordem]
    .filter((id, index, lista) => lista.indexOf(id) === index)
    .map(getQuickActionById)
    .filter(Boolean)
    .slice(0, Math.max(1, Number(limite) || 5));
}

function acaoAtalhoPedidoRecente(tipo) {
  const pedido = [...pedidos].filter(Boolean).sort((a, b) => {
    const dataB = Date.parse(b.updatedAt || b.criadoEm || b.createdAt || b.data || "") || Number(b.id) || 0;
    const dataA = Date.parse(a.updatedAt || a.criadoEm || a.createdAt || a.data || "") || Number(a.id) || 0;
    return dataB - dataA;
  })[0];
  if (!pedido) {
    mostrarToast("Crie um pedido para usar este atalho.", "aviso", 3600);
    return;
  }
  if (tipo === "whatsapp") {
    enviarWhatsPedidoSalvo(Number(pedido.id));
    return;
  }
  if (tipo === "pdf") {
    baixarPdfPedidoSalvo(Number(pedido.id));
  }
}

function acionarAtalhoRapido(id) {
  const acao = getQuickActionById(id);
  if (!quickActionDisponivel(acao)) {
    mostrarToast("Atalho indisponível agora.", "aviso", 3200);
    return;
  }
  registrarEventoUsoLocal("atalho_acionado", {
    actionId: acao.id,
    tela: acao.tela || "",
    source: "dashboard"
  });
  if (acao.customAction) {
    if (acao.customAction === "secretaria_ia") {
      abrirSecretariaIaLocal3d();
      return;
    }
    acaoAtalhoPedidoRecente(acao.customAction);
    return;
  }
  if (acao.id === "novo_pedido") {
    abrirEditorCompletoNovoPedido();
    return;
  }
  trocarTela(acao.tela || "dashboard");
}

