function limparCalculo() {
  return window.SimplificaCalculatorSettings.limparCalculo(getCalculatorSettingsDeps());
}

async function adicionarItem() {
  if (!ultimoCalculo && !calcular()) return false;
  return confirmCalculatorResult();
}

async function salvarOrcamento() {
  if (!ultimoCalculo) calcular();
  if (!ultimoCalculo || ultimoCalculo.preco <= 0) return;
  if (!await consumirCreditoAcaoFree("gerar_orcamento", "gerar orçamento")) return;
  const nome = document.getElementById("nomeItem")?.value.trim() || "Orçamento 3D";
  orcamentos.unshift({
    id: Date.now(),
    nome,
    calculo: { ...ultimoCalculo },
    criadoEm: new Date().toISOString()
  });
  orcamentos = orcamentos.slice(0, 100);
  registrarEventoUsoLocal("orcamento_finalizado", {
    produto: nome,
    materialNome: ultimoCalculo.materialNome,
    materialId: ultimoCalculo.materialId,
    impressora: ultimoCalculo.printer,
    peso: ultimoCalculo.peso,
    tempo: ultimoCalculo.tempo
  });
  salvarDados();
  registrarHistorico("Orçamento", "Orçamento salvo: " + nome);
  alert("Orçamento salvo com sucesso.");
}

async function gerarPdfCalculadora() {
  if (!ultimoCalculo) calcular();
  const adicionado = await adicionarItem();
  if (!adicionado) return;
  return gerarPDF();
}

function promoverPopupParaDialogUiV3(popup, options = {}) {
  if (!popup || !window.UiV3?.Dialog || !document.querySelector('[data-ui-version="v3"].ui3-real-screen')) return popup;
  const card = popup.querySelector(options.cardSelector || ".modal-card");
  if (!card) return popup;
  const title = options.title || card.querySelector(".modal-header h2")?.textContent?.trim() || "Janela";
  const content = card.cloneNode(true);
  content.querySelector(".modal-header")?.remove();
  content.classList.remove("modal-card");
  content.classList.add("ui3-stack");
  const component = options.kind === "drawer" ? window.UiV3.Drawer : options.kind === "sheet" ? window.UiV3.BottomSheet : window.UiV3.Dialog;
  const overlay = component({ title, content: content.outerHTML, wide: options.wide === true, fullscreen: options.fullscreen === true, onClose: options.onClose, historyEntry: options.historyEntry !== false });
  if (overlay) popup.innerHTML = "";
  return overlay || popup;
}

function fecharPopup() {
  window.UiV3?.closeOverlay?.();
  closeModal();
  closeDrawer();
  hideOverlay();
  const popup = document.getElementById("popup");
  if (popup) {
    popup.innerHTML = "";
  }
}

function solicitarConfirmacaoAcao({
  titulo = "Confirmar ação",
  mensagem = "Deseja continuar?",
  confirmar = "Confirmar",
  cancelar = "Cancelar",
  perigo = false
} = {}) {
  return new Promise((resolve) => {
    const dentroDeSubpaginaConfiguracao = Boolean(document.querySelector(".ui-section.ui-subscreen-active"));
    if (window.UiV3?.Dialog && document.querySelector('[data-ui-version="v3"].ui3-real-screen') && !dentroDeSubpaginaConfiguracao) {
      let settled = false;
      const finalizar = (valor) => {
        if (settled) return;
        settled = true;
        window.UiV3.closeOverlay();
        resolve(valor);
      };
      const overlay = window.UiV3.Dialog({
        title: escaparHtml(titulo),
        onClose: () => finalizar(false),
        content: `
          <p>${escaparHtml(mensagem)}</p>
          <div class="ui3-sticky-actions">
            <button class="ui3-button" data-variant="secondary" type="button" data-confirm-cancel>${escaparHtml(cancelar)}</button>
            <button class="ui3-button" data-variant="${perigo ? "danger" : "primary"}" type="button" data-confirm-ok>${escaparHtml(confirmar)}</button>
          </div>
        `
      });
      if (overlay) {
        overlay.querySelector("[data-confirm-ok]")?.addEventListener("click", () => finalizar(true), { once: true });
        overlay.querySelector("[data-confirm-cancel]")?.addEventListener("click", () => finalizar(false), { once: true });
        return;
      }
    }
    const popup = document.getElementById("popup");
    if (!popup) {
      resolve(window.confirm(mensagem));
      return;
    }

    popup.innerHTML = `
      <div class="modal-backdrop" role="dialog" aria-modal="true">
        <div class="modal-card">
          <div class="modal-header">
            <h2>${escaparHtml(titulo)}</h2>
            <button class="icon-button" type="button" id="confirmActionCancelTop" title="Fechar">✕</button>
          </div>
          <p class="muted">${escaparHtml(mensagem)}</p>
          <div class="actions">
            <button class="btn ghost" type="button" id="confirmActionCancel">${escaparHtml(cancelar)}</button>
            <button class="btn ${perigo ? "danger" : ""}" type="button" id="confirmActionOk">${escaparHtml(confirmar)}</button>
          </div>
        </div>
      </div>
    `;

    const finalizar = (valor) => {
      fecharPopup();
      resolve(valor);
    };
    document.getElementById("confirmActionOk")?.addEventListener("click", () => finalizar(true), { once: true });
    document.getElementById("confirmActionCancel")?.addEventListener("click", () => finalizar(false), { once: true });
    document.getElementById("confirmActionCancelTop")?.addEventListener("click", () => finalizar(false), { once: true });
    popup.querySelector(".modal-backdrop")?.addEventListener("click", (event) => {
      if (event.target === event.currentTarget) finalizar(false);
    });
  });
}

